window.CODE_INDEX = {"classes":{"ActivityTabFragment":{"appearsIn":[["activity","h-classes","Logic \u00b7 class diagram"],["activity","h-sequence","Open the Activity tab, logged in \u00b7 sequence"],["index","h-screens","Screens \u00b7 how the user moves"]],"code":"class ActivityTabFragment : Fragment() {\n    interface Callback {\n        fun onNavigateTo(navTab: NavTab)\n    }\n\n    private val viewModel: ActivityTabViewModel by viewModels()\n    private val menuProvider = object : MenuProvider {\n        override fun onCreateMenu(menu: Menu, menuInflater: MenuInflater) {\n            menuInflater.inflate(R.menu.menu_activity_tab_overflow, menu)\n        }\n\n        override fun onMenuItemSelected(menuItem: MenuItem): Boolean {\n            return handleMenuItemClick(menuItem)\n        }\n    }\n\n    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {\n        super.onCreateView(inflater, container, savedInstanceState)\n        viewLifecycleOwner.lifecycleScope.launch {\n            repeatOnLifecycle(Lifecycle.State.RESUMED) {\n                FlowEventBus.events.collectLatest { event ->\n                    when (event) {\n                        is LoggedInEvent, is LoggedOutEvent, is LoggedOutInBackgroundEvent -> viewModel.loadAll()\n                    }\n                }\n            }\n        }\n        viewLifecycleOwner.lifecycleScope.launch {\n            repeatOnLifecycle(Lifecycle.State.RESUMED) {\n                viewModel.allDataLoaded.collectLatest {\n                    if (it) {\n                        val isAllDataEmpty = viewModel.hasNoReadingHistoryData() &&\n                                viewModel.hasNoImpactData() &&\n                                viewModel.hasNoGameStats() &&\n                                viewModel.hasNoDonationData()\n                        ActivityTabEvent.submit(\n                            activeInterface = \"activity_tab\",\n                            action = \"impression\",\n                            editCount = viewModel.getTotalEditsCount(),\n                            state = if (isAllDataEmpty) \"empty\" else \"complete\"\n                        )\n                    }\n                }\n            }\n        }\n        viewLifecycleOwner.lifecycleScope.launch {\n            repeatOnLifecycle(Lifecycle.State.CREATED) {\n                viewModel.impactUiState.collectLatest {\n                    if (it is UiState.Error && it.error is MwNotLoggedInException) {\n                        AccountUtil.bailWithLogout()\n                        requireActivity().window.decorView.post {\n                            if (!requireActivity().isDestroyed) {\n                                callback()?.onNavigateTo(NavTab.HOME)\n                            }\n                        }\n                    }\n                }\n            }\n        }\n        viewLifecycleOwner.lifecycleScope.launch {\n            repeatOnLifecycle(Lifecycle.State.RESUMED) {\n                viewModel.yearInReviewEntryState.collectLatest {\n                    if (it is UiState.Success) {\n                        TestKitchenAdapter.client.getInstrument(\"apps-year-in-review\")\n                            .submitInteraction(action = \"impression\", actionSource = \"activity_tab_entry_point\", actionContext = mapOf(\"personalized\" to it.data))\n                    }\n                }\n            }\n        }\n        return ComposeView(requireContext()).apply {\n            setContent {\n                BaseTheme {\n                    // Collected outside the login branch so that loadAll() after a login/logout recomposes this and re-checks the account state.\n                    val readingHistoryState = viewModel.readingHistoryState.collectAsState().value\n                    val yearInReviewEntryState = viewModel.yearInReviewEntryState.collectAsState().value\n                    if (AccountUtil.isLoggedIn && !AccountUtil.isTemporaryAccount) {\n                        LoggedInScreen(readingHistoryState, yearInReviewEntryState)\n                    } else {\n                        ActivityTabLoggedOutScreen(\n                            onCreateAccountClick = {\n                                ActivityTabEvent.submit(activeInterface = \"activity_tab_login\", action = \"create_account_click\")\n                                startActivity(LoginActivity.newIntent(requireContext(), LoginActivity.SOURCE_ACTIVITY_TAB))\n                            },\n                            onLoginClick = {\n                                ActivityTabEvent.submit(activeInterface = \"activity_tab_login\", action = \"login_click\")\n                                startActivity(LoginActivity.newIntent(requireContext(), LoginActivity.SOURCE_ACTIVITY_TAB, createAccountFirst = false))\n                            },\n                            yearInReviewEntryState = yearInReviewEntryState.takeIf { YearInReviewViewModel.canShowEntryPoint },\n                            onYirGetStartedClick = {\n                                TestKitchenAdapter.client.getInstrument(\"apps-year-in-review\")\n                                    .submitInteraction(action = \"click\", actionSource = \"activity_tab_entry_point\", elementId = \"get_started_button\",\n                                        actionContext = mapOf(\"personalized\" to ((yearInReviewEntryState as? UiState.Success)?.data ?: false)))\n                                startActivity(YearInReviewOnboardingActivity.newIntent(requireContext()))\n                            }\n                        )\n                    }\n                }\n            }\n        }\n    }\n\n    override fun onResume() {\n        super.onResume()\n        requireActivity().addMenuProvider(menuProvider, viewLifecycleOwner)\n        if (requireActivity().intent.getBooleanExtra(Constants.INTENT_EXTRA_SCROLL_TO_GAMES, false)) {\n            viewModel.onScrollToGames()\n            requireActivity().intent.removeExtra(Constants.INTENT_EXTRA_SCROLL_TO_GAMES)\n        }\n        if (!Prefs.isGameStatsUnavailableSnackbarShown) {\n            requireActivity().intent.getStringExtra(Constants.INTENT_EXTRA_SNACKBAR_MESSAGE)?.let {\n                FeedbackUtil.makeSnackbar(requireView(), it).show()\n                requireActivity().intent.removeExtra(Constants.INTENT_EXTRA_SNACKBAR_MESSAGE)\n                Prefs.isGameStatsUnavailableSnackbarShown = true\n            }\n        }\n        maybeShowReadingChallengeRewardDialog()\n        viewModel.loadAll()\n        requireActivity().invalidateOptionsMenu()\n    }\n\n    private fun maybeShowReadingChallengeRewardDialog() {\n        val intent = requireActivity().intent\n        if (ReadingChallengeWidgetRepository.shouldShowReward(intent)) {\n            intent.removeExtra(ReadingChallengeWidgetRepository.INTENT_EXTRA_READING_CHALLENGE_REWARD)\n            ExclusiveBottomSheetPresenter.show(childFragmentManager, ReadingChallengeRewardDialog())\n        }\n    }\n\n    override fun onPause() {\n        super.onPause()\n        requireActivity().removeMenuProvider(menuProvider)\n    }\n\n    @Composable\n    private fun LoggedInScreen(readingHistoryState: UiState<ActivityTabViewModel.ReadingHistory>, yearInReviewEntryState: UiState<Boolean>?) {\n        val userName = AccountUtil.userName\n        ActivityTabLoggedInScreen(\n            userName = userName,\n            languageCode = WikipediaApp.instance.wikiSite.languageCode,\n            modules = Prefs.activityTabModules,\n            haveAtLeastOneDonation = Prefs.donationResults.isNotEmpty(),\n            areGamesAvailable = WikiGames.WHICH_CAME_FIRST.isLangSupported(WikipediaApp.instance.wikiSite.languageCode),\n            refreshSilently = viewModel.shouldRefreshTimelineSilently,\n            scrollToGames = viewModel.scrollToGames.collectAsState().value,\n            readingHistoryState = readingHistoryState,\n            donationUiState = viewModel.donationUiState.collectAsState().value,\n            wikiGamesUiState = viewModel.wikiGamesUiState.collectAsState().value,\n            impactUiState = viewModel.impactUiState.collectAsState().value,\n            timelineFlow = viewModel.timelineFlow,\n            onScrollToGamesConsumed = { viewModel.onScrollToGamesConsumed() },\n            onRefresh = {\n                viewModel.shouldRefreshTimelineSilently = false\n                viewModel.loadAll()\n            },\n            onCustomizeClick = {\n                startActivity(ActivityTabCustomizationActivity.newIntent(requireContext()))\n            },\n            onArticlesReadClick = { callback()?.onNavigateTo(NavTab.SEARCH) },\n            onArticlesSavedClick = { callback()?.onNavigateTo(NavTab.READING_LISTS) },\n            onExploreClick = {\n                ActivityTabEvent.submit(activeInterface = \"activity_tab\", action = \"explore_click\", editCount = viewModel.getTotalEditsCount())\n                callback()?.onNavigateTo(NavTab.READING_LISTS)\n            },\n            onCategoryItemClick = { category ->\n                startActivity(CategoryActivity.newIntent(requireActivity(), viewModel.createPageTitleForCategory(category)))\n            },\n            onReadingHistoryRetry = { viewModel.loadReadingHistory() },\n            onEditedPageClick = { pageTitle ->\n                val entry = HistoryEntry(title = pageTitle, source = HistoryEntry.SOURCE_ACTIVITY_TAB)\n                startActivity(PageActivity.newIntentForNewTab(context = requireActivity(), entry = entry, title = pageTitle))\n            },\n            onContributionsClick = {\n                startActivity(UserContribListActivity.newIntent(requireActivity(), userName))\n            },\n            onSuggestedEditsClick = {\n                ActivityTabEvent.submit(activeInterface = \"activity_tab\", action = \"sugg_edit_click\", editCount = viewModel.getTotalEditsCount())\n                startActivity(SuggestedEditsTasksActivity.newIntent(requireActivity()))\n            },\n            onImpactRetry = { viewModel.loadImpact() },\n            onPlayGameClick = {\n                startActivity(OnThisDayGameActivity.newIntent(\n                    context = requireContext(),\n                    invokeSource = Constants.InvokeSource.ACTIVITY_TAB,\n                    wikiSite = WikipediaApp.instance.wikiSite\n                ))\n            },\n            onGameStatsClick = { startActivity(GamesHubActivity.newIntent(requireContext(), Constants.InvokeSource.ACTIVITY_TAB)) },\n            onGamesRetry = { viewModel.loadWikiGamesStats() },\n            onDonationClick = {\n                ActivityTabEvent.submit(activeInterface = \"activity_tab\", action = \"last_donation_click\",\n                    editCount = viewModel.getTotalEditsCount(), state = if (viewModel.hasNoDonationData()) \"empty\" else \"complete\")\n                (requireActivity() as? BaseActivity)?.launchDonateDialog(campaignId = ActivityTabViewModel.CAMPAIGN_ID)\n            },\n            onTimelineItemClick = { handleTimelineItemClick(it) },\n            yearInReviewEntryState = yearInReviewEntryState.takeIf { YearInReviewViewModel.canShowEntryPoint },\n            onYirGetStartedClick = {\n                TestKitchenAdapter.client.getInstrument(\"apps-year-in-review\")\n                    .submitInteraction(action = \"click\", actionSource = \"activity_tab_entry_point\", elementId = \"get_started_button\",\n                        actionContext = mapOf(\"personalized\" to ((yearInReviewEntryState as? UiState.Success)?.data ?: false)))\n                startActivity(YearInReviewOnboardingActivity.newIntent(requireContext()))\n            }\n        )\n    }\n\n    companion object {\n        fun newInstance(): ActivityTabFragment {\n            return ActivityTabFragment().apply {\n                arguments = Bundle().apply {\n                    // TODO\n                }\n            }\n        }\n    }\n\n    private fun handleMenuItemClick(menuItem: MenuItem): Boolean {\n        return when (menuItem.itemId) {\n            R.id.menu_customize_activity_tab -> {\n                ActivityTabEvent.submit(activeInterface = \"activity_tab_overflow_menu\", action = \"customize_click\")\n                startActivity(ActivityTabCustomizationActivity.newIntent(requireContext()))\n                true\n            }\n            R.id.menu_clear_history -> {\n                ActivityTabEvent.submit(activeInterface = \"activity_tab_overflow_menu\", action = \"clear_history_click\")\n                HistoryFragment.clearAllHistory(requireContext(), lifecycleScope) {\n                    viewModel.loadAll()\n                }\n                true\n            }\n            R.id.menu_clear_donation_history -> {\n                ActivityTabEvent.submit(activeInterface = \"activity_tab_overflow_menu\", action = \"clear_donation_history_click\")\n                Prefs.donationResults = emptyList()\n                Prefs.activityTabModules = Prefs.activityTabModules.setModuleEnabled(ModuleType.DONATIONS, false)\n                viewModel.loadAll()\n                true\n            }\n            R.id.menu_learn_more -> {\n                ActivityTabEvent.submit(activeInterface = \"activity_tab_overflow_menu\", action = \"learn_click\")\n                UriUtil.visitInExternalBrowser(requireActivity(), getString(R.string.activity_tab_url).toUri())\n                true\n            }\n            R.id.menu_report_feature -> {\n                ActivityTabEvent.submit(activeInterface = \"activity_tab_overflow_menu\", action = \"problem_click\")\n                FeedbackUtil.composeEmail(requireContext(),\n                    subject = getString(R.string.activity_tab_report_email_subject),\n                    body = getString(R.string.activity_tab_report_email_body))\n                true\n            }\n            else -> false\n        }\n    }\n\n    private fun handleTimelineItemClick(item: TimelineItem) {\n        viewModel.shouldRefreshTimelineSilently = true\n        when (item.activitySource) {\n            ActivitySource.EDIT -> {\n                startActivity(\n                    ArticleEditDetailsActivity.newIntent(\n                        requireContext(),\n                        PageTitle(\n                            item.apiTitle,\n                            viewModel.wikiSiteForTimeline,\n                            item.thumbnailUrl,\n                            item.description,\n                            item.displayTitle\n                        ), item.pageId, revisionTo = item.id\n                    )\n                )\n            } else -> {\n                val pageTitle = item.toPageTitle()\n                startActivity(\n                    PageActivity.newIntentForCurrentTab(\n                        requireContext(),\n                        HistoryEntry(pageTitle, HistoryEntry.SOURCE_ACTIVITY_TAB),\n                        pageTitle\n                    )\n                )\n            }\n        }\n    }\n\n    private fun callback(): Callback? {\n        return getCallback(this, Callback::class.java)\n    }\n}","file":"app/src/main/java/org/wikipedia/activitytab/ActivityTabFragment.kt","kind":"class","line":83,"members":{"Callback":[84,86],"LoggedInScreen":[216,285],"callback":[363,365],"handleMenuItemClick":[297,332],"handleTimelineItemClick":[334,361],"maybeShowReadingChallengeRewardDialog":[203,209],"menuProvider":[89,97],"newInstance":[288,294],"onCreateView":[99,182],"onPause":[211,214],"onResume":[184,201],"viewModel":[88,88]},"shot":"shots/code/ActivityTabFragment.jpg","supers":["Fragment()"]},"AppDatabase":{"appearsIn":[["activity","h-classes","Logic \u00b7 class diagram"],["activity","h-sequence","Open the Activity tab, logged in \u00b7 sequence"],["index","h-services","Services \u00b7 what the screens share"]],"code":"@Database(\n    entities = [\n        HistoryEntry::class,\n        PageImage::class,\n        RecentSearch::class,\n        TalkPageSeen::class,\n        EditSummary::class,\n        OfflineObject::class,\n        ReadingList::class,\n        ReadingListPage::class,\n        Notification::class,\n        TalkTemplate::class,\n        Category::class,\n        DailyGameHistory::class,\n        RecommendedPage::class,\n        InterestTopic::class,\n        InterestArticle::class,\n        PageTopic::class\n    ],\n    version = DATABASE_VERSION\n)\n@TypeConverters(\n    DateTypeConverter::class,\n    WikiSiteTypeConverter::class,\n    NamespaceTypeConverter::class,\n    NotificationTypeConverters::class\n)\nabstract class AppDatabase : RoomDatabase() {\n\n    abstract fun historyEntryDao(): HistoryEntryDao\n    abstract fun historyEntryWithImageDao(): HistoryEntryWithImageDao\n    abstract fun pageImagesDao(): PageImageDao\n    abstract fun recentSearchDao(): RecentSearchDao\n    abstract fun talkPageSeenDao(): TalkPageSeenDao\n    abstract fun editSummaryDao(): EditSummaryDao\n    abstract fun offlineObjectDao(): OfflineObjectDao\n    abstract fun readingListDao(): ReadingListDao\n    abstract fun readingListPageDao(): ReadingListPageDao\n    abstract fun notificationDao(): NotificationDao\n    abstract fun talkTemplateDao(): TalkTemplateDao\n    abstract fun categoryDao(): CategoryDao\n    abstract fun dailyGameHistoryDao(): DailyGameHistoryDao\n    abstract fun recommendedPageDao(): RecommendedPageDao\n    abstract fun topicInterestDao(): InterestTopicDao\n    abstract fun articleInterestDao(): InterestArticleDao\n    abstract fun pageTopicDao(): PageTopicDao\n\n    companion object {\n        val MIGRATION_19_20 = object : Migration(19, 20) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                // introduced Offline Object table\n            }\n        }\n        val MIGRATION_20_21 = object : Migration(20, 21) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                // introduced Talk Page Seen table\n            }\n        }\n        val MIGRATION_21_22 = object : Migration(21, 22) {\n            override fun migrate(db: SupportSQLiteDatabase) {}\n        }\n        val MIGRATION_22_23 = object : Migration(22, 23) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                val defaultLang = WikipediaApp.instance.appOrSystemLanguageCode\n                val defaultAuthority = WikipediaApp.instance.wikiSite.authority()\n                val defaultTitle = MainPageNameData.valueFor(defaultLang)\n\n                // convert Recent Searches table\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS `RecentSearch` (`text` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, PRIMARY KEY(`text`))\")\n                try {\n                    db.execSQL(\"INSERT OR REPLACE INTO RecentSearch (text, timestamp) SELECT text, timestamp FROM recentsearches\")\n                } catch (_: Exception) {\n                    // ignore further errors\n                }\n                db.execSQL(\"DROP TABLE IF EXISTS recentsearches\")\n\n                // convert Talk Pages Seen table\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS `TalkPageSeen_temp` (`sha` TEXT NOT NULL, PRIMARY KEY(`sha`))\")\n                try {\n                    db.query(\"SELECT * FROM sqlite_master WHERE type='table' AND name='talkpageseen'\").use {\n                        if (it.count > 0) {\n                            db.execSQL(\"INSERT OR REPLACE INTO TalkPageSeen_temp (sha) SELECT sha FROM talkpageseen\")\n                            db.execSQL(\"DROP TABLE talkpageseen\")\n                        }\n                    }\n                } catch (_: Exception) {\n                    // ignore further errors\n                }\n                db.execSQL(\"ALTER TABLE TalkPageSeen_temp RENAME TO TalkPageSeen\")\n\n                // convert Edit Summaries table\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS `EditSummary` (`summary` TEXT NOT NULL, `lastUsed` INTEGER NOT NULL, PRIMARY KEY(`summary`))\")\n                try {\n                    db.execSQL(\"INSERT OR REPLACE INTO EditSummary (summary, lastUsed) SELECT summary, lastUsed FROM editsummaries\")\n                } catch (_: Exception) {\n                    // ignore further errors\n                }\n                db.execSQL(\"DROP TABLE IF EXISTS editsummaries\")\n\n                // convert Offline Objects table\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS `OfflineObject_temp` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `url` TEXT NOT NULL, `lang` TEXT NOT NULL, `path` TEXT NOT NULL, `status` INTEGER NOT NULL, `usedByStr` TEXT NOT NULL)\")\n                try {\n                    db.query(\"SELECT * FROM sqlite_master WHERE type='table' AND name='offlineobject'\").use {\n                        if (it.count > 0) {\n                            db.execSQL(\"INSERT INTO OfflineObject_temp (id, url, lang, path, status, usedByStr) SELECT _id, url, lang, path, status, usedby FROM offlineobject\")\n                            db.execSQL(\"DROP TABLE offlineobject\")\n                        }\n                    }\n                } catch (_: Exception) {\n                    // ignore further errors\n                }\n                db.execSQL(\"ALTER TABLE OfflineObject_temp RENAME TO OfflineObject\")\n\n                // Delete vestigial Reading List tables that might have been left over from very old DB versions.\n                db.execSQL(\"DROP TABLE IF EXISTS readinglist\")\n                db.execSQL(\"DROP TABLE IF EXISTS readinglistpage\")\n\n                // convert Reading List tables\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS `ReadingList` (`listTitle` TEXT NOT NULL, `description` TEXT, `mtime` INTEGER NOT NULL, `atime` INTEGER NOT NULL, `id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sizeBytes` INTEGER NOT NULL, `dirty` INTEGER NOT NULL, `remoteId` INTEGER NOT NULL)\")\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS `ReadingListPage` (`wiki` TEXT NOT NULL, `namespace` INTEGER NOT NULL, `displayTitle` TEXT NOT NULL, `apiTitle` TEXT NOT NULL, `description` TEXT, `thumbUrl` TEXT, `listId` INTEGER NOT NULL, `id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `mtime` INTEGER NOT NULL, `atime` INTEGER NOT NULL, `offline` INTEGER NOT NULL, `status` INTEGER NOT NULL, `sizeBytes` INTEGER NOT NULL, `lang` TEXT NOT NULL, `revId` INTEGER NOT NULL, `remoteId` INTEGER NOT NULL)\")\n                try {\n                    db.execSQL(\"INSERT INTO ReadingList (id, listTitle, description, mtime, atime, sizeBytes, dirty, remoteId) SELECT _id, COALESCE(readingListTitle,''), readingListDescription, readingListMtime, readingListAtime, readingListSizeBytes, readingListDirty, readingListRemoteId FROM localreadinglist\")\n                    db.execSQL(\"INSERT INTO ReadingListPage (id, wiki, namespace, displayTitle, apiTitle, description, thumbUrl, listId, mtime, atime, offline, status, sizeBytes, lang, revId, remoteId) SELECT _id, site, namespace, title, COALESCE(apiTitle,title), description, thumbnailUrl, listId, mtime, atime, offline, status, sizeBytes, lang, revId, remoteId FROM localreadinglistpage\")\n                } catch (_: Exception) {\n                    // ignore further errors\n                }\n                db.execSQL(\"DROP TABLE IF EXISTS localreadinglist\")\n                db.execSQL(\"DROP TABLE IF EXISTS localreadinglistpage\")\n\n                // convert History table\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS `HistoryEntry` (`authority` TEXT NOT NULL, `lang` TEXT NOT NULL, `apiTitle` TEXT NOT NULL, `displayTitle` TEXT NOT NULL, `id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `namespace` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, `source` INTEGER NOT NULL, `timeSpentSec` INTEGER NOT NULL)\")\n                try {\n                    db.execSQL(\"INSERT INTO HistoryEntry (id, authority, lang, apiTitle, displayTitle, namespace, source, timestamp, timeSpentSec) SELECT _id, COALESCE(site,'$defaultAuthority'), COALESCE(lang,'$defaultLang'), COALESCE(title,'$defaultTitle'), COALESCE(displayTitle,''), COALESCE(namespace,''), COALESCE(source,2), COALESCE(timestamp,0), COALESCE(timeSpent,0) FROM history\")\n                } catch (_: Exception) {\n                    // ignore further errors\n                }\n                db.execSQL(\"DROP TABLE IF EXISTS history\")\n\n                // convert Page Images table\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS `PageImage` (`lang` TEXT NOT NULL, `namespace` TEXT NOT NULL, `apiTitle` TEXT NOT NULL, `imageName` TEXT, PRIMARY KEY(`lang`, `namespace`, `apiTitle`))\")\n                try {\n                    db.execSQL(\"INSERT OR REPLACE INTO PageImage (lang, namespace, apiTitle, imageName) SELECT COALESCE(lang,'$defaultLang'), COALESCE(namespace,''), COALESCE(title,'$defaultTitle'), imageName FROM pageimages\")\n                } catch (_: Exception) {\n                    // ignore further errors\n                }\n                db.execSQL(\"DROP TABLE pageimages\")\n            }\n        }\n        val MIGRATION_23_24 = object : Migration(23, 24) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS `Notification` (`id` INTEGER NOT NULL, `wiki` TEXT NOT NULL, `read` TEXT, `category` TEXT NOT NULL, `type` TEXT NOT NULL, `revid` INTEGER NOT NULL, `title` TEXT, `agent` TEXT, `timestamp` TEXT, `contents` TEXT, PRIMARY KEY(`id`, `wiki`))\")\n            }\n        }\n        val MIGRATION_24_25 = object : Migration(24, 25) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS `TalkTemplate` (`id` INTEGER NOT NULL, `type` INTEGER NOT NULL, `order` INTEGER NOT NULL, `title` TEXT NOT NULL, `subject` TEXT NOT NULL, `message` TEXT NOT NULL, PRIMARY KEY(`id`))\")\n            }\n        }\n        val MIGRATION_25_26 = object : Migration(25, 26) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                db.execSQL(\"ALTER TABLE HistoryEntry ADD COLUMN description TEXT NOT NULL DEFAULT ''\")\n            }\n        }\n        val MIGRATION_26_27 = object : Migration(26, 27) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                // Rename the existing HistoryEntry table, which we're preserving for now (in case\n                // things go wrong with migrations in the field).\n                db.execSQL(\"ALTER TABLE HistoryEntry RENAME TO HistoryEntry_old\")\n\n                // Create the \"new\" HistoryEntry table, which will match the new HistoryEntry structure.\n                db.execSQL(\"CREATE TABLE `HistoryEntry` (`authority` TEXT NOT NULL, `lang` TEXT NOT NULL, `apiTitle` TEXT NOT NULL, `displayTitle` TEXT NOT NULL, `id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `namespace` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, `source` INTEGER NOT NULL, `prevId` INTEGER NOT NULL DEFAULT -1)\")\n\n                // Copy everything from the old table to the new one, minus the columns that were removed.\n                db.execSQL(\"INSERT INTO HistoryEntry (authority, lang, apiTitle, displayTitle, id, namespace, timestamp, source) SELECT authority, lang, apiTitle, displayTitle, id, namespace, timestamp, source FROM HistoryEntry_old\")\n\n                // Add new columns to the PageImage table, will will now serve as a more general\n                // table for page metadata, not just the thumbnail.\n                db.execSQL(\"ALTER TABLE PageImage ADD COLUMN timeSpentSec INTEGER NOT NULL DEFAULT 0\")\n                db.execSQL(\"ALTER TABLE PageImage ADD COLUMN description TEXT DEFAULT ''\")\n                db.execSQL(\"ALTER TABLE PageImage ADD COLUMN geoLat REAL NOT NULL DEFAULT 0.0\")\n                db.execSQL(\"ALTER TABLE PageImage ADD COLUMN geoLon REAL NOT NULL DEFAULT 0.0\")\n\n                // Copy the metadata from the removed columns in the old HistoryEntry table into the\n                // new columns in the PageImage table.\n                db.execSQL(\"UPDATE PageImage SET description = (SELECT description FROM HistoryEntry_old WHERE PageImage.lang = HistoryEntry_old.lang AND PageImage.namespace = HistoryEntry_old.namespace AND PageImage.apiTitle = HistoryEntry_old.apiTitle)\")\n                db.execSQL(\"UPDATE PageImage SET timeSpentSec = COALESCE((SELECT timeSpentSec FROM HistoryEntry_old WHERE PageImage.lang = HistoryEntry_old.lang AND PageImage.namespace = HistoryEntry_old.namespace AND PageImage.apiTitle = HistoryEntry_old.apiTitle), 0)\")\n            }\n        }\n        val MIGRATION_27_28 = object : Migration(27, 28) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                db.execSQL(\"CREATE INDEX IF NOT EXISTS index_HistoryEntry_lang_namespace_apiTitle ON HistoryEntry (lang, namespace, apiTitle)\")\n                db.execSQL(\"CREATE INDEX IF NOT EXISTS index_PageImage_lang_namespace_apiTitle ON PageImage (lang, namespace, apiTitle)\")\n            }\n        }\n        val MIGRATION_26_28 = object : Migration(26, 28) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                // Rename the existing HistoryEntry table, which we're preserving for now (in case\n                // things go wrong with migrations in the field).\n                db.execSQL(\"ALTER TABLE HistoryEntry RENAME TO HistoryEntry_old\")\n\n                // Create the \"new\" HistoryEntry table, which will match the new HistoryEntry structure.\n                db.execSQL(\"CREATE TABLE `HistoryEntry` (`authority` TEXT NOT NULL, `lang` TEXT NOT NULL, `apiTitle` TEXT NOT NULL, `displayTitle` TEXT NOT NULL, `id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `namespace` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, `source` INTEGER NOT NULL, `prevId` INTEGER NOT NULL DEFAULT -1)\")\n\n                // Create indexes on the new and old HistoryEntry table.\n                db.execSQL(\"CREATE INDEX IF NOT EXISTS index_HistoryEntry_lang_namespace_apiTitle ON HistoryEntry (lang, namespace, apiTitle)\")\n                db.execSQL(\"CREATE INDEX IF NOT EXISTS index_HistoryEntry_old_lang_namespace_apiTitle ON HistoryEntry_old (lang, namespace, apiTitle)\")\n\n                // Copy everything from the old table to the new one, minus the columns that were removed.\n                db.execSQL(\"INSERT INTO HistoryEntry (authority, lang, apiTitle, displayTitle, id, namespace, timestamp, source) SELECT authority, lang, apiTitle, displayTitle, id, namespace, timestamp, source FROM HistoryEntry_old\")\n\n                // Add new columns to the PageImage table, will will now serve as a more general\n                // table for page metadata, not just the thumbnail.\n                db.execSQL(\"ALTER TABLE PageImage ADD COLUMN timeSpentSec INTEGER NOT NULL DEFAULT 0\")\n                db.execSQL(\"ALTER TABLE PageImage ADD COLUMN description TEXT DEFAULT ''\")\n                db.execSQL(\"ALTER TABLE PageImage ADD COLUMN geoLat REAL NOT NULL DEFAULT 0.0\")\n                db.execSQL(\"ALTER TABLE PageImage ADD COLUMN geoLon REAL NOT NULL DEFAULT 0.0\")\n\n                // Create an index on the PageImage table.\n                db.execSQL(\"CREATE INDEX IF NOT EXISTS index_PageImage_lang_namespace_apiTitle ON PageImage (lang, namespace, apiTitle)\")\n\n                // Copy the metadata from the removed columns in the old HistoryEntry table into the\n                // new columns in the PageImage table, for PageImage rows that already exist.\n                db.execSQL(\"UPDATE PageImage SET\" +\n                        \" description = (SELECT HistoryEntry_old.description\" +\n                        \"     FROM HistoryEntry_old\" +\n                        \"     WHERE PageImage.lang = HistoryEntry_old.lang\" +\n                        \"     AND PageImage.namespace = HistoryEntry_old.namespace\" +\n                        \"     AND PageImage.apiTitle = HistoryEntry_old.apiTitle),\" +\n                        \" timeSpentSec = COALESCE((SELECT HistoryEntry_old.timeSpentSec\" +\n                        \"     FROM HistoryEntry_old\" +\n                        \"     WHERE PageImage.lang = HistoryEntry_old.lang\" +\n                        \"     AND PageImage.namespace = HistoryEntry_old.namespace\" +\n                        \"     AND PageImage.apiTitle = HistoryEntry_old.apiTitle), 0)\")\n\n                // For PageImage rows that don't already exist (i.e. HistoryEntries that didn't have\n                // a thumbnail), insert them and copy the other metadata.\n                db.execSQL(\"INSERT INTO PageImage (lang, namespace, apiTitle, description, timeSpentSec)\" +\n                        \" SELECT lang, namespace, apiTitle, description, COALESCE(timeSpentSec, 0) as timeSpentSec FROM\" +\n                        \" (SELECT lang, namespace, apiTitle, description, MAX(COALESCE(timeSpentSec, 0)) as timeSpentSec\" +\n                        \"     FROM HistoryEntry_old GROUP BY lang, namespace, apiTitle) AS HistoryUnique\" +\n                        \" WHERE NOT EXISTS (SELECT 1 FROM PageImage\" +\n                        \"     WHERE PageImage.lang = HistoryUnique.lang AND\" +\n                        \"         PageImage.namespace = HistoryUnique.namespace AND\" +\n                        \"         PageImage.apiTitle = HistoryUnique.apiTitle)\")\n            }\n        }\n\n        val MIGRATION_28_29 = object : Migration(28, 29) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS Category (\" +\n                        \"title TEXT NOT NULL,\" +\n                        \"lang TEXT NOT NULL,\" +\n                        \"timeStamp INTEGER NOT NULL,\" +\n                        \"PRIMARY KEY (title, lang, timeStamp)\" +\n                        \")\")\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS DailyGameHistory (\" +\n                        \"    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,\" +\n                        \"    gameName INTEGER NOT NULL,\" +\n                        \"    language TEXT NOT NULL,\" +\n                        \"    year INTEGER NOT NULL,\" +\n                        \"    month INTEGER NOT NULL,\" +\n                        \"    day INTEGER NOT NULL,\" +\n                        \"    score INTEGER NOT NULL,\" +\n                        \"    playType INTEGER NOT NULL,\" +\n                        \"    gameData TEXT\" +\n                        \")\")\n            }\n        }\n        val MIGRATION_29_30 = object : Migration(29, 30) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS RecommendedPage (\" +\n                        \"    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,\" +\n                        \"    wiki TEXT NOT NULL,\" +\n                        \"    lang TEXT NOT NULL DEFAULT 'en',\" +\n                        \"    namespace INTEGER NOT NULL,\" +\n                        \"    timestamp INTEGER NOT NULL,\" +\n                        \"    apiTitle TEXT NOT NULL,\" +\n                        \"    displayTitle TEXT NOT NULL,\" +\n                        \"    description TEXT,\" +\n                        \"    thumbUrl TEXT,\" +\n                        \"    status INTEGER NOT NULL DEFAULT 0\" +\n                        \")\")\n            }\n        }\n        val MIGRATION_30_31 = object : Migration(30, 31) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                // Step 1: Create a temporary table\n                db.execSQL(\"CREATE TABLE Category_temp (\" +\n                        \"    year INTEGER NOT NULL,\" +\n                        \"    month INTEGER NOT NULL,\" +\n                        \"    title TEXT NOT NULL,\" +\n                        \"    lang TEXT NOT NULL,\" +\n                        \"    count INTEGER NOT NULL,\" +\n                        \"    PRIMARY KEY (year, month, title, lang)\" +\n                        \")\")\n\n                // Step 2: Populate the new table with the transformed data from the old table\n                db.execSQL(\"INSERT INTO Category_temp (year, month, title, lang, count)\" +\n                        \"    SELECT\" +\n                        \"        COALESCE(CAST(strftime('%Y', timeStamp / 1000, 'unixepoch') AS INTEGER), ${LocalDate.now().year}) AS year,\" +\n                        \"        COALESCE(CAST(strftime('%m', timeStamp / 1000, 'unixepoch') AS INTEGER), ${LocalDate.now().monthValue}) AS month,\" +\n                        \"        title,\" +\n                        \"        lang,\" +\n                        \"        COUNT(*) AS count\" +\n                        \"    FROM Category GROUP BY year, month, title, lang\")\n\n                // Step 3: Drop the old table\n                db.execSQL(\"DROP TABLE Category\")\n                // Step 4: Rename the temporary table to the original table name\n\n                db.execSQL(\"ALTER TABLE Category_temp RENAME TO Category\")\n            }\n        }\n\n        val MIGRATION_31_32 = object : Migration(31, 32) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                db.execSQL(\"ALTER TABLE DailyGameHistory ADD COLUMN status INTEGER NOT NULL DEFAULT 1\")\n                db.execSQL(\"ALTER TABLE DailyGameHistory ADD COLUMN currentQuestionIndex INTEGER NOT NULL DEFAULT ${OnThisDayGameViewModel.MAX_QUESTIONS}\")\n            }\n        }\n        val MIGRATION_32_33 = object : Migration(32, 33) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS InterestTopic (\" +\n                        \"topicId TEXT NOT NULL,\" +\n                        \"PRIMARY KEY (topicId)\" +\n                        \")\")\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS InterestArticle (\" +\n                        \"apiTitle TEXT NOT NULL,\" +\n                        \"lang TEXT NOT NULL,\" +\n                        \"namespace INTEGER NOT NULL,\" +\n                        \"displayTitle TEXT NOT NULL,\" +\n                        \"description TEXT NOT NULL,\" +\n                        \"thumbUrl TEXT NOT NULL,\" +\n                        \"PRIMARY KEY (apiTitle, lang, namespace)\" +\n                        \")\")\n            }\n        }\n\n        val MIGRATION_33_34 = object : Migration(33, 34) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                db.execSQL(\"ALTER TABLE RecommendedPage ADD COLUMN extract TEXT\")\n            }\n        }\n\n        val MIGRATION_34_35 = object : Migration(34, 35) {\n            override fun migrate(db: SupportSQLiteDatabase) {\n                db.execSQL(\"CREATE TABLE IF NOT EXISTS PageTopic (\" +\n                        \"lang TEXT NOT NULL,\" +\n                        \"namespace TEXT NOT NULL,\" +\n                        \"apiTitle TEXT NOT NULL,\" +\n                        \"topic TEXT NOT NULL,\" +\n                        \"score REAL NOT NULL,\" +\n                        \"PRIMARY KEY (lang, namespace, apiTitle, topic)\" +\n                        \")\")\n                db.execSQL(\"CREATE INDEX IF NOT EXISTS index_PageTopic_lang_namespace_apiTitle ON PageTopic (lang, namespace, apiTitle)\")\n                db.execSQL(\"CREATE INDEX IF NOT EXISTS index_PageTopic_topic ON PageTopic (topic)\")\n            }\n        }\n\n        val instance: AppDatabase by lazy(LazyThreadSafetyMode.SYNCHRONIZED) {\n            Room.databaseBuilder(WikipediaApp.instance, AppDatabase::class.java, DATABASE_NAME)\n                .addMigrations(MIGRATION_19_20, MIGRATION_20_21, MIGRATION_21_22, MIGRATION_22_23,\n                    MIGRATION_23_24, MIGRATION_24_25, MIGRATION_25_26, MIGRATION_26_27,\n                    MIGRATION_26_28, MIGRATION_27_28, MIGRATION_28_29, MIGRATION_29_30,\n                    MIGRATION_30_31, MIGRATION_31_32, MIGRATION_32_33, MIGRATION_33_34,\n                    MIGRATION_34_35)\n                .fallbackToDestructiveMigration(false)\n                .build()\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/database/AppDatabase.kt","kind":"class","line":50,"members":{"MIGRATION_19_20":[98,102],"MIGRATION_20_21":[103,107],"MIGRATION_21_22":[108,110],"MIGRATION_22_23":[111,197],"MIGRATION_23_24":[198,202],"MIGRATION_24_25":[203,207],"MIGRATION_25_26":[208,212],"MIGRATION_26_27":[213,237],"MIGRATION_26_28":[244,295],"MIGRATION_27_28":[238,243],"MIGRATION_28_29":[297,317],"MIGRATION_29_30":[318,333],"MIGRATION_30_31":[334,362],"MIGRATION_31_32":[364,369],"MIGRATION_32_33":[370,386],"MIGRATION_33_34":[388,392],"MIGRATION_34_35":[394,407],"articleInterestDao":[94,94],"categoryDao":[90,90],"dailyGameHistoryDao":[91,91],"editSummaryDao":[84,84],"historyEntryDao":[79,79],"historyEntryWithImageDao":[80,80],"instance":[409,418],"notificationDao":[88,88],"offlineObjectDao":[85,85],"pageImagesDao":[81,81],"pageTopicDao":[95,95],"readingListDao":[86,86],"readingListPageDao":[87,87],"recentSearchDao":[82,82],"recommendedPageDao":[92,92],"talkPageSeenDao":[83,83],"talkTemplateDao":[89,89],"topicInterestDao":[93,93]},"supers":["RoomDatabase()"]},"BackPressedHandler":{"code":"interface BackPressedHandler {\n    fun onBackPressed(): Boolean\n}","file":"app/src/main/java/org/wikipedia/BackPressedHandler.kt","kind":"interface","line":3,"members":{"onBackPressed":[4,4]},"supers":[]},"CommunicationBridge":{"appearsIn":[["article","h-classes","Logic \u00b7 class diagram"],["article","h-sequence","Open an article and follow a link \u00b7 sequence"],["index","h-services","Services \u00b7 what the screens share"]],"code":"@SuppressLint(\"AddJavascriptInterface\", \"SetJavaScriptEnabled\")\nclass CommunicationBridge constructor(private val communicationBridgeListener: CommunicationBridgeListener) {\n    private val eventListeners = HashMap<String, MutableList<JSEventListener>>()\n    private var isMetadataReady = false\n    private var isPcsReady = false\n    private val pendingJSMessages = ArrayList<String>()\n    private val pendingEvals = HashMap<String, ValueCallback<String>>()\n\n    fun interface JSEventListener {\n        fun onMessage(messageType: String, messagePayload: JsonObject?)\n    }\n\n    interface CommunicationBridgeListener {\n        val webView: WebView\n        val model: PageViewModel\n        val isPreview: Boolean\n        val toolbarMargin: Int\n        val messageCardHeight: Float\n    }\n\n    init {\n        communicationBridgeListener.webView.settings.javaScriptEnabled = true\n        communicationBridgeListener.webView.settings.allowUniversalAccessFromFileURLs = true\n        communicationBridgeListener.webView.settings.mediaPlaybackRequiresUserGesture = false\n        communicationBridgeListener.webView.webChromeClient = CommunicatingChrome()\n        communicationBridgeListener.webView.addJavascriptInterface(PcsClientJavascriptInterface(), \"pcsClient\")\n    }\n\n    fun onPcsReady() {\n        isPcsReady = true\n        flushMessages()\n    }\n\n    fun loadBlankPage() {\n        communicationBridgeListener.webView.loadUrl(\"about:blank\")\n    }\n\n    fun onMetadataReady() {\n        isMetadataReady = true\n        flushMessages()\n    }\n\n    val isLoading: Boolean\n        get() = !(isMetadataReady && isPcsReady)\n\n    fun resetHtml(pageTitle: PageTitle) {\n        isPcsReady = false\n        isMetadataReady = false\n        pendingJSMessages.clear()\n        pendingEvals.clear()\n        if (communicationBridgeListener.model.shouldLoadAsMobileWeb) {\n            communicationBridgeListener.webView.loadUrl(pageTitle.uri)\n        } else {\n            communicationBridgeListener.webView.loadUrl(ServiceFactory.getRestBasePath(pageTitle.wikiSite) +\n                    RestService.PAGE_HTML_ENDPOINT + UriUtil.encodeURL(pageTitle.prefixedText))\n        }\n    }\n\n    fun cleanup() {\n        pendingJSMessages.clear()\n        pendingEvals.clear()\n        eventListeners.clear()\n        incomingMessageHandler?.removeCallbacksAndMessages(null)\n        incomingMessageHandler = null\n        communicationBridgeListener.webView.webViewClient = WebViewClient()\n        communicationBridgeListener.webView.removeJavascriptInterface(\"pcsClient\")\n        // Explicitly load a blank page into the WebView, to stop playback of any media.\n        loadBlankPage()\n    }\n\n    fun addListener(type: String, listener: JSEventListener) {\n        eventListeners.getOrPut(type) { ArrayList() }.add(listener)\n    }\n\n    fun execute(js: String) {\n        pendingJSMessages.add(js)\n        flushMessages()\n    }\n\n    fun evaluate(js: String, callback: ValueCallback<String>) {\n        pendingEvals[js] = callback\n        flushMessages()\n    }\n\n    fun evaluateImmediate(js: String, callback: ValueCallback<String?>?) {\n        communicationBridgeListener.webView.evaluateJavascript(js, callback)\n    }\n\n    private fun flushMessages() {\n        if (!isPcsReady || !isMetadataReady) {\n            return\n        }\n        for (jsString in pendingJSMessages) {\n            communicationBridgeListener.webView.evaluateJavascript(jsString, null)\n        }\n        pendingJSMessages.clear()\n        for ((key, callback) in pendingEvals) {\n            communicationBridgeListener.webView.evaluateJavascript(key, callback)\n        }\n        pendingEvals.clear()\n    }\n\n    private var incomingMessageHandler: Handler? = Handler(Looper.getMainLooper(), Handler.Callback { msg ->\n        val message = msg.obj as BridgeMessage\n        if (!eventListeners.containsKey(message.action)) {\n            L.e(\"No such message type registered: \" + message.action)\n            return@Callback false\n        }\n        try {\n            val listeners: List<JSEventListener> = eventListeners[message.action]!!\n            for (listener in listeners) {\n                listener.onMessage(message.action, message.data)\n            }\n        } catch (e: Exception) {\n            e.printStackTrace()\n            L.logRemoteError(e)\n        }\n        false\n    })\n\n    private class CommunicatingChrome : WebChromeClient() {\n        override fun onConsoleMessage(consoleMessage: ConsoleMessage): Boolean {\n            L.d(consoleMessage.sourceId() + \":\" + consoleMessage.lineNumber() + \" - \" + consoleMessage.message())\n            return true\n        }\n    }\n\n    private inner class PcsClientJavascriptInterface {\n        /**\n         * Called from Javascript to send a message packet to the Java layer. The message must be\n         * formatted in JSON, and URL-encoded.\n         *\n         * @param message JSON structured message received from the WebView.\n         */\n        @JavascriptInterface\n        @Synchronized\n        fun onReceiveMessage(message: String?) {\n            if (incomingMessageHandler != null) {\n                val bridgeMessage: BridgeMessage? = JsonUtil.decodeFromString(message.orEmpty())\n                if (bridgeMessage != null) {\n                    val msg = Message.obtain(incomingMessageHandler, MESSAGE_HANDLE_MESSAGE_FROM_JS, bridgeMessage)\n                    incomingMessageHandler!!.sendMessage(msg)\n                } else {\n                    L.w(\"Received malformed message: $message\")\n                }\n            }\n        }\n\n        @get:Synchronized\n        @get:JavascriptInterface\n        val setupSettings: String\n            get() = setUp(communicationBridgeListener.webView.context,\n                    communicationBridgeListener.model.title!!, communicationBridgeListener.isPreview,\n                    communicationBridgeListener.toolbarMargin, communicationBridgeListener.messageCardHeight)\n    }\n\n    @Serializable\n    private class BridgeMessage {\n        val action: String = \"\"\n        val data: JsonObject? = null\n    }\n\n    companion object {\n        private const val MESSAGE_HANDLE_MESSAGE_FROM_JS = 1\n    }\n}","file":"app/src/main/java/org/wikipedia/bridge/CommunicationBridge.kt","kind":"class","line":31,"members":{"BridgeMessage":[187,191],"CommunicatingChrome":[151,156],"CommunicationBridgeListener":[43,49],"JSEventListener":[39,41],"MESSAGE_HANDLE_MESSAGE_FROM_JS":[194,194],"PcsClientJavascriptInterface":[158,185],"addListener":[101,103],"cleanup":[89,99],"communicationBridgeListener":[32,32],"evaluate":[110,113],"evaluateImmediate":[115,117],"eventListeners":[33,33],"execute":[105,108],"flushMessages":[119,131],"incomingMessageHandler":[133,149],"isLoading":[73,73],"isMetadataReady":[34,34],"isPcsReady":[35,35],"loadBlankPage":[64,66],"onMetadataReady":[68,71],"onPcsReady":[59,62],"pendingEvals":[37,37],"pendingJSMessages":[36,36],"resetHtml":[76,87]},"supers":[]},"HistoryFragment":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["search","h-classes","Logic \u00b7 class diagram"]],"code":"class HistoryFragment : Fragment(), BackPressedHandler {\n    interface Callback {\n        fun onLoadPage(entry: HistoryEntry)\n    }\n\n    private var _binding: FragmentHistoryBinding? = null\n    private val binding get() = _binding!!\n    private val viewModel: HistoryViewModel by viewModels()\n\n    private val adapter = HistoryEntryItemAdapter()\n    private val itemCallback = ItemCallback()\n    private var actionMode: ActionMode? = null\n    private val searchActionModeCallback = HistorySearchCallback()\n    private val selectedEntries = mutableSetOf<HistoryEntry>()\n\n    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {\n        _binding = FragmentHistoryBinding.inflate(inflater, container, false)\n\n        binding.searchEmptyView.setEmptyText(R.string.search_history_no_results)\n        val touchCallback = SwipeableItemTouchHelperCallback(requireContext())\n        touchCallback.swipeableEnabled = true\n        val itemTouchHelper = ItemTouchHelper(touchCallback)\n        itemTouchHelper.attachToRecyclerView(binding.historyList)\n        binding.historyList.layoutManager = LinearLayoutManager(context)\n        binding.historyList.adapter = adapter\n        binding.historyEmptyContainer.visibility = View.GONE\n        setUpScrollListener()\n        return binding.root\n    }\n\n    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {\n        super.onViewCreated(view, savedInstanceState)\n\n        viewModel.historyItems.observe(viewLifecycleOwner) {\n            if (it is Resource.Success) {\n                onLoadItemsFinished(it.data)\n            } else if (it is Resource.Error) {\n                onError(it.throwable)\n            }\n        }\n\n        viewModel.deleteHistoryItemsAction.observe(viewLifecycleOwner) {\n            if (it is Resource.Success) {\n                onPagesDeleted()\n            }\n        }\n    }\n\n    private fun setUpScrollListener() {\n        binding.historyList.addOnScrollListener(object : RecyclerView.OnScrollListener() {\n            override fun onScrolled(recyclerView: RecyclerView, dx: Int, dy: Int) {\n                super.onScrolled(recyclerView, dx, dy)\n                (requireActivity() as MainActivity).updateToolbarElevation(binding.historyList.computeVerticalScrollOffset() != 0)\n            }\n        })\n    }\n\n    override fun onResume() {\n        super.onResume()\n        viewModel.reloadHistoryItems()\n    }\n\n    override fun onPause() {\n        super.onPause()\n        actionMode?.finish()\n    }\n\n    override fun onDestroyView() {\n        binding.historyList.adapter = null\n        binding.historyList.clearOnScrollListeners()\n        adapter.clearList()\n        _binding = null\n        super.onDestroyView()\n    }\n\n    override fun onBackPressed(): Boolean {\n        actionMode?.run {\n            finish()\n            return@onBackPressed true\n        }\n        if (selectedEntries.size > 0) {\n            unselectAllPages()\n            return true\n        }\n        return false\n    }\n\n    private fun updateEmptyState(searchQuery: String?) {\n        if (searchQuery.isNullOrEmpty()) {\n            binding.searchEmptyView.visibility = View.GONE\n            binding.historyEmptyContainer.visibility = if (adapter.isEmpty) View.VISIBLE else View.GONE\n        } else {\n            binding.searchEmptyView.visibility = if (adapter.isEmpty) View.VISIBLE else View.GONE\n            binding.historyEmptyContainer.visibility = View.GONE\n        }\n    }\n\n    private fun onPageClick(entry: HistoryEntry) {\n        callback()?.onLoadPage(entry)\n    }\n\n    private fun finishActionMode() {\n        actionMode?.finish()\n    }\n\n    private fun beginMultiSelect() {\n        if (SearchActionModeCallback.matches(actionMode)) {\n            finishActionMode()\n        }\n    }\n\n    private fun toggleSelectPage(entry: HistoryEntry?) {\n        if (entry == null) {\n            return\n        }\n        if (selectedEntries.contains(entry)) {\n            selectedEntries.remove(entry)\n        } else {\n            selectedEntries.add(entry)\n        }\n        val selectedCount = selectedEntries.size\n        if (selectedCount == 0) {\n            finishActionMode()\n        } else {\n            actionMode?.title = resources.getQuantityString(R.plurals.multi_items_selected, selectedCount, selectedCount)\n        }\n        val position = adapter.getPosition(entry)\n        adapter.notifyItemChanged(position)\n    }\n\n    fun refresh() {\n        adapter.notifyItemRangeChanged(0, adapter.itemCount)\n        if (!WikipediaApp.instance.isOnline && Prefs.showHistoryOfflineArticlesToast) {\n            Toast.makeText(requireContext(), R.string.history_offline_articles_toast, Toast.LENGTH_SHORT).show()\n            Prefs.showHistoryOfflineArticlesToast = false\n        }\n    }\n\n    private fun unselectAllPages() {\n        selectedEntries.clear()\n        adapter.notifyItemRangeChanged(0, adapter.itemCount)\n    }\n\n    private fun deleteSelectedPages() {\n        viewModel.deleteHistoryItems(selectedEntries.toList())\n    }\n\n    private fun onPagesDeleted() {\n        showDeleteItemsUndoSnackbar(selectedEntries.toList())\n        selectedEntries.clear()\n        viewModel.reloadHistoryItems()\n    }\n\n    private fun showDeleteItemsUndoSnackbar(entries: List<HistoryEntry>) {\n        val message = if (entries.size == 1) getString(R.string.history_item_deleted, entries[0].title.displayText) else getString(R.string.history_items_deleted, entries.size)\n        val snackbar = FeedbackUtil.makeSnackbar(requireActivity(), message)\n        snackbar.setAction(R.string.history_item_delete_undo) {\n            viewModel.insertHistoryItem(entries)\n        }\n        snackbar.show()\n    }\n\n    private fun onLoadItemsFinished(items: List<Any>) {\n        val list = mutableListOf<Any>()\n        if (!SearchActionModeCallback.matches(actionMode)) {\n            list.add(SearchBar())\n        }\n        list.addAll(items)\n        adapter.setList(list)\n        updateEmptyState(viewModel.searchQuery)\n        requireActivity().invalidateOptionsMenu()\n    }\n\n    private fun onError(throwable: Throwable) {\n        L.e(throwable)\n        onLoadItemsFinished(emptyList())\n    }\n\n    private class HeaderViewHolder(itemView: View) : DefaultViewHolder<View>(itemView) {\n        var headerText = itemView.findViewById<TextView>(R.id.section_header_text)!!\n\n        fun bindItem(date: String) {\n            headerText.text = date\n        }\n    }\n\n    private inner class SearchCardViewHolder(itemView: View) : DefaultViewHolder<View>(itemView) {\n        private val historyFilterButton: ImageView\n        private val clearHistoryButton: ImageView\n\n        fun bindItem() {\n            clearHistoryButton.visibility = if (adapter.isEmpty) View.GONE else View.VISIBLE\n            historyFilterButton.visibility = if (adapter.isEmpty) View.GONE else View.VISIBLE\n        }\n\n        private fun adjustSearchCardView(searchCardView: WikiCardView) {\n            searchCardView.post {\n                if (!isAdded) {\n                    return@post\n                }\n                searchCardView.updateLayoutParams<LinearLayout.LayoutParams> {\n                    val horizontalMargin = if (DimenUtil.isLandscape(requireContext())) {\n                        searchCardView.width / 6 + DimenUtil.roundedDpToPx(30f)\n                    } else {\n                        DimenUtil.roundedDpToPx(16f)\n                    }\n                    updateMarginsRelative(start = horizontalMargin, end = horizontalMargin,\n                        top = DimenUtil.roundedDpToPx(3f))\n                }\n            }\n            searchCardView.setCardBackgroundColor(ResourceUtil.getThemedColor(requireContext(), R.attr.background_color))\n        }\n\n        init {\n            val searchCardView = itemView.findViewById<WikiCardView>(R.id.search_card)\n            val voiceSearchButton = itemView.findViewById<View>(R.id.voice_search_button)\n            historyFilterButton = itemView.findViewById(R.id.history_filter)\n            clearHistoryButton = itemView.findViewById(R.id.history_delete)\n            searchCardView.setOnClickListener { (requireParentFragment() as MainFragment).openSearchActivity(Constants.InvokeSource.NAV_MENU, null, it) }\n            voiceSearchButton.isVisible = WikipediaApp.instance.voiceRecognitionAvailable\n            voiceSearchButton.setOnClickListener { (requireParentFragment() as MainFragment).onFeedVoiceSearchRequested() }\n            historyFilterButton.setOnClickListener {\n                if (actionMode == null) {\n                    actionMode = (requireActivity() as AppCompatActivity)\n                            .startSupportActionMode(searchActionModeCallback)\n                }\n            }\n            clearHistoryButton.setOnClickListener {\n                if (selectedEntries.isEmpty()) {\n                    clearAllHistory(requireContext(), lifecycleScope) {\n                        viewModel.afterDeleteAllHistoryItems()\n                    }\n                } else {\n                    deleteSelectedPages()\n                }\n            }\n            FeedbackUtil.setButtonTooltip(historyFilterButton, clearHistoryButton)\n            adjustSearchCardView(searchCardView)\n            updateSearchHint(searchCardView.findViewById(R.id.search_icon), searchCardView.findViewById(R.id.search_text_view))\n        }\n\n        private fun updateSearchHint(searchIcon: ImageView, searchTextView: TextView) {\n            searchIcon.contentDescription = getString(R.string.search_hint)\n            searchTextView.text = getString(R.string.search_hint)\n        }\n    }\n\n    private inner class HistoryEntryItemHolder(itemView: PageItemView<HistoryEntry>) : DefaultViewHolder<PageItemView<HistoryEntry>>(itemView), SwipeableItemTouchHelperCallback.Callback {\n        private lateinit var entry: HistoryEntry\n\n        fun bindItem(entry: HistoryEntry) {\n            this.entry = entry\n            view.item = entry\n            view.setTitle(entry.title.displayText)\n            view.setTitleTypeface(Typeface.NORMAL)\n            view.setDescription(entry.title.description)\n            view.setImageUrl(entry.title.thumbUrl)\n            view.setSearchQuery(viewModel.searchQuery)\n            view.isSelected = selectedEntries.contains(entry)\n            PageAvailableOfflineHandler.check(lifecycleScope, entry.title) { view.setViewsGreyedOut(!it) }\n        }\n\n        override fun onSwipe() {\n            selectedEntries.add(entry)\n            deleteSelectedPages()\n        }\n\n        override fun isSwipeable(): Boolean { return true }\n    }\n\n    private inner class HistoryEntryItemAdapter : RecyclerView.Adapter<DefaultViewHolder<*>>() {\n        private var historyEntries = mutableListOf<Any>()\n        override fun getItemCount(): Int {\n            return historyEntries.size\n        }\n\n        val isEmpty\n            get() = (itemCount == 0 || itemCount == 1 && historyEntries[0] is SearchBar)\n\n        override fun getItemViewType(position: Int): Int {\n            return when {\n                historyEntries[position] is SearchBar -> VIEW_TYPE_SEARCH_CARD\n                historyEntries[position] is String -> VIEW_TYPE_HEADER\n                else -> VIEW_TYPE_ITEM\n            }\n        }\n\n        fun setList(list: MutableList<Any>) {\n            historyEntries = list\n            adapter.notifyDataSetChanged()\n        }\n\n        fun clearList() {\n            historyEntries.clear()\n        }\n\n        fun getPosition(entry: HistoryEntry): Int {\n            return historyEntries.indexOf(entry)\n        }\n\n        override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): DefaultViewHolder<*> {\n            return when (viewType) {\n                VIEW_TYPE_SEARCH_CARD -> {\n                    val view = LayoutInflater.from(requireContext()).inflate(R.layout.view_history_header_with_search, parent, false)\n                    SearchCardViewHolder(view)\n                }\n                VIEW_TYPE_HEADER -> {\n                    val view = LayoutInflater.from(requireContext()).inflate(R.layout.view_section_header, parent, false)\n                    HeaderViewHolder(view)\n                }\n                else -> HistoryEntryItemHolder(PageItemView(requireContext()))\n            }\n        }\n\n        override fun onBindViewHolder(holder: DefaultViewHolder<*>, pos: Int) {\n            when (holder) {\n                is SearchCardViewHolder -> holder.bindItem()\n                is HistoryEntryItemHolder -> holder.bindItem(historyEntries[pos] as HistoryEntry)\n                else -> (holder as HeaderViewHolder).bindItem(historyEntries[pos] as String)\n            }\n        }\n\n        override fun onViewAttachedToWindow(holder: DefaultViewHolder<*>) {\n            super.onViewAttachedToWindow(holder)\n            if (holder is HistoryEntryItemHolder) {\n                holder.view.callback = itemCallback\n            }\n        }\n\n        override fun onViewDetachedFromWindow(holder: DefaultViewHolder<*>) {\n            if (holder is HistoryEntryItemHolder) {\n                holder.view.callback = null\n            }\n            super.onViewDetachedFromWindow(holder)\n        }\n\n        fun hideHeader() {\n            if (historyEntries.isNotEmpty() && historyEntries[0] is SearchBar) {\n                historyEntries.removeAt(0)\n                adapter.notifyItemRemoved(0)\n            }\n        }\n    }\n\n    private inner class ItemCallback : PageItemView.Callback<HistoryEntry?> {\n        override fun onClick(item: HistoryEntry?) {\n            if (selectedEntries.isNotEmpty()) {\n                toggleSelectPage(item)\n            } else if (item != null) {\n                onPageClick(HistoryEntry(item.title, HistoryEntry.SOURCE_HISTORY))\n            }\n        }\n\n        override fun onLongClick(item: HistoryEntry?): Boolean {\n            if (actionMode != null) {\n                return false\n            }\n            beginMultiSelect()\n            toggleSelectPage(item)\n            return true\n        }\n\n        override fun onActionClick(item: HistoryEntry?, view: View) {}\n        override fun onListChipClick(readingList: ReadingList) {}\n    }\n\n    private inner class HistorySearchCallback : SearchActionModeCallback() {\n        override fun onCreateActionMode(mode: ActionMode, menu: Menu): Boolean {\n            actionMode = mode\n            (requireParentFragment() as MainFragment).setBottomNavVisible(false)\n            (binding.historyList.adapter as HistoryEntryItemAdapter).hideHeader()\n            return super.onCreateActionMode(mode, menu)\n        }\n\n        override fun onQueryChange(s: String) {\n            viewModel.searchQuery = s.trim()\n        }\n\n        override fun onDestroyActionMode(mode: ActionMode) {\n            super.onDestroyActionMode(mode)\n            viewModel.searchQuery = \"\"\n            actionMode = null\n            (requireParentFragment() as MainFragment).setBottomNavVisible(true)\n        }\n\n        override fun getSearchHintString(): String {\n            return requireContext().resources.getString(R.string.history_filter_list_hint)\n        }\n\n        override fun getParentContext(): Context {\n            return requireContext()\n        }\n    }\n\n    private fun callback(): Callback? {\n        return FragmentUtil.getCallback(this, Callback::class.java)\n    }\n\n    private class SearchBar\n\n    companion object {\n        private const val VIEW_TYPE_SEARCH_CARD = 0\n        private const val VIEW_TYPE_HEADER = 1\n        private const val VIEW_TYPE_ITEM = 2\n\n        fun clearAllHistory(context: Context, coroutineScope: CoroutineScope, action: () -> Unit) {\n            MaterialAlertDialogBuilder(context)\n                .setTitle(R.string.dialog_title_clear_history)\n                .setMessage(R.string.dialog_message_clear_history)\n                .setPositiveButton(R.string.dialog_message_clear_history_yes) { _, _ ->\n                    coroutineScope.launch(\n                        CoroutineExceptionHandler { _, t -> L.e(t) }\n                    ) {\n                        AppDatabase.instance.historyEntryDao().deleteAll()\n                        AppDatabase.instance.pageImagesDao().deleteAll()\n                        AppDatabase.instance.categoryDao().deleteAll()\n                        AppDatabase.instance.pageTopicDao().deleteAll()\n                        PrefsYearInReviewStore.onReadingHistoryCleared()\n                        action()\n                    }\n                }\n                .setNegativeButton(R.string.dialog_message_clear_history_no, null).show()\n        }\n\n        fun newInstance(): HistoryFragment {\n            return HistoryFragment()\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/history/HistoryFragment.kt","kind":"class","line":52,"members":{"Callback":[53,55],"HeaderViewHolder":[230,236],"HistoryEntryItemAdapter":[322,394],"HistoryEntryItemHolder":[299,320],"HistorySearchCallback":[418,444],"ItemCallback":[396,416],"SearchBar":[450,450],"SearchCardViewHolder":[238,297],"VIEW_TYPE_HEADER":[454,454],"VIEW_TYPE_ITEM":[455,455],"VIEW_TYPE_SEARCH_CARD":[453,453],"_binding":[57,57],"actionMode":[63,63],"adapter":[61,61],"beginMultiSelect":[157,161],"binding":[58,58],"callback":[446,448],"clearAllHistory":[457,474],"deleteSelectedPages":[195,197],"finishActionMode":[153,155],"itemCallback":[62,62],"newInstance":[476,478],"onBackPressed":[127,137],"onCreateView":[67,80],"onDestroyView":[119,125],"onError":[225,228],"onLoadItemsFinished":[214,223],"onPageClick":[149,151],"onPagesDeleted":[199,203],"onPause":[114,117],"onResume":[109,112],"onViewCreated":[82,98],"refresh":[182,188],"searchActionModeCallback":[64,64],"selectedEntries":[65,65],"setUpScrollListener":[100,107],"showDeleteItemsUndoSnackbar":[205,212],"toggleSelectPage":[163,180],"unselectAllPages":[190,193],"updateEmptyState":[139,147],"viewModel":[59,59]},"shot":"shots/code/HistoryFragment.jpg","supers":["Fragment()","BackPressedHandler"]},"HomeFragment":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"],["home","h-sequence","Load more of the Community feed \u00b7 sequence"],["index","h-screens","Screens \u00b7 how the user moves"],["launch","h-sequence","First launch \u00b7 sequence"]],"code":"class HomeFragment : Fragment(), LinkPreviewDialog.LoadPageCallback {\n    private val viewModel: HomeViewModel by viewModels()\n    private val pageOverflowMenuViewModel: PageOverflowMenuViewModel by viewModels()\n    private val cardImpressions = mutableSetOf<String>()\n    private val instrument = TestKitchenAdapter.client.getInstrument(\"apps-home-feed\")\n        .startFunnel(\"home_feed\").also {\n            if (ReadAloudLeadSectionABTest().isTestActive()) {\n                it.setExperiment(TestKitchenAdapter.getExperiment(ReadAloudLeadSectionABTest()))\n            }\n        }\n\n    private val personalizationResultLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == RESULT_OK) {\n            val tab = if (Prefs.homePreferenceSelection == HomePreferenceType.PERSONALIZED) HomeTab.FOR_YOU else HomeTab.COMMUNITY\n            selectTab(tab)\n        }\n    }\n\n    private val customizeInterestsLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == RESULT_INTERESTS_UPDATED) {\n            Prefs.homeForYouModulesToday = \"\"\n            viewModel.refreshForYouContent()\n        }\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n\n        lifecycleScope.launch {\n            repeatOnLifecycle(Lifecycle.State.CREATED) {\n                viewModel.forYouNetworkLatency.collectLatest {\n                    if (it > 0) {\n                        instrument.submitInteraction(\"timing\", actionSource = \"for_you_latency\", actionContext = mapOf(\"latency\" to it))\n                    }\n                }\n            }\n        }\n\n        if (savedInstanceState == null) {\n            maybeShowExploreFeedUpdatePrompt()\n        }\n    }\n\n    override fun onCreateView(\n        inflater: LayoutInflater,\n        container: ViewGroup?,\n        savedInstanceState: Bundle?\n    ): View {\n        return ComposeView(requireActivity()).apply {\n            setContent {\n                val selectedTab by viewModel.selectedTab.collectAsState()\n                val wikiSite by viewModel.wikiSite.collectAsState()\n                val tabsState by viewModel.tabsState.collectAsState()\n                val notificationState by viewModel.unreadCount.collectAsState()\n                val forYouContentState by viewModel.forYouState.collectAsState()\n                val communityContentState by viewModel.communityState.collectAsState()\n                var swipeToExplorePromptShown by remember { mutableStateOf(Prefs.isHomeSwipeToExplorePromptShown) }\n                var showReadAloudSurveyDialog by remember { mutableStateOf(false) }\n\n                BaseTheme(currentTheme = if (selectedTab == HomeTab.FOR_YOU) Theme.BLACK else WikipediaApp.instance.currentTheme) {\n                    HomeScreen(\n                        wikiSite = wikiSite,\n                        languageState = WikipediaApp.instance.languageState,\n                        selectedTab = selectedTab,\n                        communityContentState = communityContentState,\n                        forYouContentState = forYouContentState,\n                        overflowMenuState = pageOverflowMenuViewModel.pageOverflowMenuState,\n                        savedInReadingListTitles = viewModel.savedInReadingListTitles.collectAsState().value,\n                        resolveForYouSavedState = { title ->\n                            AppDatabase.instance.readingListPageDao().findPageInAnyList(title) != null\n                        },\n                        tabsState = tabsState,\n                        notificationBellState = notificationState,\n                        onAction = {\n                            if (it is HomeAction.ReadAloudShowSurvey) {\n                                showReadAloudSurveyDialog = true\n                            } else {\n                                handleHomeAction(it, wikiSite, selectedTab)\n                            }\n                        }\n                    )\n\n                    if (selectedTab == HomeTab.FOR_YOU && !swipeToExplorePromptShown && forYouContentState.modules.isNotEmpty()) {\n                        val dismissSwipePrompt = {\n                            swipeToExplorePromptShown = true\n                            Prefs.isHomeSwipeToExplorePromptShown = true\n                        }\n                        WikipediaAlertDialog(\n                            title = stringResource(R.string.explore_feed_swipe_to_explore_prompt_title),\n                            titleModifier = Modifier.fillMaxWidth(),\n                            message = stringResource(R.string.explore_feed_swipe_to_explore_prompt_message),\n                            image = {\n                                Image(\n                                    painter = painterResource(R.drawable.swipe_gesture_illustration),\n                                    contentDescription = null,\n                                    modifier = Modifier.fillMaxWidth()\n                                )\n                            },\n                            confirmButtonText = stringResource(R.string.onboarding_got_it),\n                            onDismissRequest = dismissSwipePrompt,\n                            onConfirmButtonClick = dismissSwipePrompt\n                        )\n                    }\n\n                    if (showReadAloudSurveyDialog) {\n                        ReadAloudSurveyDialog(onDismissRequest = { showReadAloudSurveyDialog = false }, instrument)\n                    } else {\n                        if (ReadAloudSurveyDialog.shouldShow(byDate = true)) {\n                            showReadAloudSurveyDialog = true\n                        }\n                    }\n                }\n            }\n        }\n    }\n\n    override fun onResume() {\n        super.onResume()\n        val mainActivity = requireActivity() as? MainActivity\n        if (mainActivity?.isCurrentFragmentSelected(this) == true) {\n            mainActivity.onTabChanged(NavTab.HOME)\n        }\n        viewModel.updateTabCount()\n        viewModel.updateSelectedLanguageIfNeeded()\n        instrument.stopFunnel()\n        instrument.startFunnel(\"home_feed\")\n        refreshNotification()\n        maybeShowSurveyDialog()\n    }\n\n    fun getCurrentTab(): HomeTab {\n        return viewModel.selectedTab.value\n    }\n\n    override fun onPause() {\n        super.onPause()\n        cardImpressions.clear()\n    }\n\n    fun refreshNotification() {\n        viewModel.refreshUnreadNotificationCount()\n    }\n\n    fun updateLanguage(languageCode: String) {\n        viewModel.updateLanguage(languageCode)\n    }\n\n    fun selectTab(tab: HomeTab) {\n        viewModel.selectTab(tab)\n        (requireActivity() as? MainActivity)?.onTabChanged(NavTab.HOME)\n    }\n\n    private fun maybeShowExploreFeedUpdatePrompt() {\n        if (!Prefs.isInitialOnboardingEnabled && Prefs.isExploreFeedUpdatePromptShown.not()) {\n            personalizationResultLauncher.launch(ExploreFeedUpdatePromptActivity.newIntent(requireContext()))\n        }\n    }\n\n    private fun handleHomeAction(action: HomeAction, wikiSite: WikiSite, selectedTab: HomeTab) {\n        when (action) {\n            is HomeAction.SelectTab -> {\n                val card = action.card\n                if (card is EmptyCommunityCard || card is EmptyForYouCard) {\n                    instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"community_feed\")\n                }\n                selectTab(action.tab)\n            }\n            is HomeAction.RefreshTab -> {\n                Prefs.homeForYouModulesToday = \"\"\n                if (action.tab == HomeTab.COMMUNITY) {\n                    viewModel.refreshCommunityContent()\n                } else {\n                    viewModel.refreshForYouContent()\n                }\n            }\n            HomeAction.LoadMoreCommunityContent -> viewModel.loadCommunityContent()\n            HomeAction.LoadMoreForYouContent -> viewModel.loadForYouContent()\n            is HomeAction.HideCommunityCard -> {\n                val card = action.card\n                instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, actionSubtype = \"feed_overflow\", elementId = \"card_hide\")\n                viewModel.hideCommunityCard(card)\n                FeedbackUtil.makeSnackbar(requireActivity(), getString(R.string.menu_feed_card_dismissed))\n                    .setAction(getString(R.string.explore_feed_header_overflow_hide_module_message_action)) {\n                        instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, actionSubtype = \"feed_overflow\", elementId = \"undo_card_hide\")\n                        viewModel.restoreCommunityCard(card)\n                    }.show()\n            }\n            is HomeAction.HideForYouCard -> {\n                val card = action.card\n                instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, actionSubtype = \"feed_overflow\", elementId = \"card_hide\")\n                viewModel.hideForYouCard(card)\n                FeedbackUtil.makeSnackbar(requireActivity(), getString(R.string.menu_feed_card_dismissed))\n                    .setAction(getString(R.string.explore_feed_header_overflow_hide_module_message_action)) {\n                        instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, actionSubtype = \"feed_overflow\", elementId = \"undo_card_hide\")\n                        viewModel.restoreForYouCard(card)\n                    }.show()\n            }\n            is HomeAction.HideModule -> {\n                val moduleKey = action.moduleKey\n                instrument.submitInteraction(\"click\", actionSource = moduleKey, actionSubtype = \"feed_overflow\", elementId = \"module_hide\")\n                viewModel.hideModule(moduleKey)\n                FeedbackUtil.makeSnackbar(requireActivity(), getString(R.string.explore_feed_header_overflow_hide_module_message))\n                    .setAction(getString(R.string.explore_feed_header_overflow_hide_module_message_action)) {\n                        instrument.submitInteraction(\"click\", actionSource = moduleKey, actionSubtype = \"feed_overflow\", elementId = \"undo_module_hide\")\n                        viewModel.restoreModule(moduleKey)\n                    }.show()\n            }\n            is HomeAction.PageClick -> {\n                instrument.submitInteraction(\"click\", actionSource = action.card.javaClass.simpleName, elementId = \"article_open\", pageData = TestKitchenAdapter.getPageData(pageTitle = action.historyEntry.title))\n                (parentFragment as? MainFragment)?.onFeedSelectPage(action.historyEntry, false)\n            }\n            is HomeAction.PageBookmarkClick -> {\n                instrument.submitInteraction(\"click\", actionSource = action.card.javaClass.simpleName, elementId = \"article_save\", pageData = TestKitchenAdapter.getPageData(pageTitle = action.historyEntry.title))\n                SaveArticleSheetDialog.show(childFragmentManager, action.historyEntry.title)\n            }\n            is HomeAction.PageShareClick -> {\n                instrument.submitInteraction(\"click\", actionSource = action.card.javaClass.simpleName, elementId = \"article_share\", pageData = TestKitchenAdapter.getPageData(pageTitle = action.historyEntry.title))\n                ShareUtil.shareText(requireContext(), action.historyEntry.title)\n            }\n            is HomeAction.PageOverflowClick -> {\n                pageOverflowMenuViewModel.onPageOverflowClick(\n                    wikiSite = wikiSite,\n                    pageSummary = action.pageSummary,\n                    source = action.source,\n                    menuKey = action.menuKey\n                )\n            }\n            is HomeAction.PageOverflowItemClick -> {\n                val entry = action.historyEntry\n                val elementId = when (action.item) {\n                    PageOverflowMenuItem.OPEN_PAGE -> \"article_open\"\n                    PageOverflowMenuItem.OPEN_IN_NEW_TAB -> \"article_open_new_tab\"\n                    PageOverflowMenuItem.SAVE -> \"article_save\"\n                    PageOverflowMenuItem.SHARE -> \"article_share\"\n                    PageOverflowMenuItem.COPY_LINK -> \"article_copy_link\"\n                }\n                instrument.submitInteraction(\"click\", actionSource = action.card.javaClass.simpleName, actionSubtype = \"feed_item_overflow\", elementId = elementId, pageData = TestKitchenAdapter.getPageData(pageTitle = entry.title))\n                val mainFragment = parentFragment as? MainFragment\n                when (action.item) {\n                    PageOverflowMenuItem.OPEN_PAGE -> mainFragment?.onFeedSelectPage(entry, false)\n                    PageOverflowMenuItem.OPEN_IN_NEW_TAB -> {\n                        mainFragment?.onFeedSelectPage(entry, true)\n                        viewModel.updateTabCount(true)\n                    }\n                    PageOverflowMenuItem.SAVE -> mainFragment?.onFeedSavePage(entry)\n                    PageOverflowMenuItem.SHARE -> mainFragment?.onFeedSharePage(entry)\n                    PageOverflowMenuItem.COPY_LINK -> mainFragment?.onFeedCopyLink(entry)\n                }\n            }\n            HomeAction.PageOverflowDismiss -> {\n                pageOverflowMenuViewModel.dismissPageOverflowMenu()\n            }\n            is HomeAction.NewsClick -> {\n                val card = action.card\n                instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = card.javaClass.simpleName, actionContext = mapOf(\"index\" to card.news.indexOf(action.newsItem)))\n                (parentFragment as? MainFragment)?.onFeedNewsItemSelected(action.newsItem, wikiSite)\n            }\n            is HomeAction.ImageClick -> {\n                val card = action.card\n                instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"article_open\", pageData = TestKitchenAdapter.getPageData(pageTitle = card.featuredImage.toPageTitle()))\n                (parentFragment as? MainFragment)?.onFeaturedImageSelected(card.featuredImage)\n            }\n            is HomeAction.ImageShareClick -> {\n                val card = action.card\n                instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"share\", pageData = TestKitchenAdapter.getPageData(pageTitle = card.featuredImage.toPageTitle()))\n                (parentFragment as? MainFragment)?.onFeedShareImage(card.featuredImage, card.age)\n            }\n            is HomeAction.ImageDownloadClick -> {\n                val card = action.card\n                instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"download\", pageData = TestKitchenAdapter.getPageData(pageTitle = card.featuredImage.toPageTitle()))\n                (parentFragment as? MainFragment)?.onFeedDownloadImage(card.featuredImage)\n            }\n            is HomeAction.LanguageSelected -> {\n                instrument.submitInteraction(\"click\", \"language_menu\", elementId = \"language_change\", actionContext = mapOf(\"selected_tab\" to selectedTab.name, \"language_code\" to action.languageCode))\n                updateLanguage(action.languageCode)\n            }\n            HomeAction.ManageLanguagesClick -> {\n                instrument.submitInteraction(\"click\", \"language_menu\", elementId = \"manage_languages\", actionContext = mapOf(\"selected_tab\" to selectedTab.name))\n                requireActivity().startActivity(WikipediaLanguagesActivity.newIntent(requireContext(), invokeSource = InvokeSource.FEED))\n            }\n            is HomeAction.CustomizeClick -> {\n                val card = action.card\n                if (card != null) {\n                    instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName,\n                        actionSubtype = if (card !is EmptyForYouCard) \"feed_overflow\" else null,\n                        elementId = \"feed_customize\")\n                }\n                if (card is DiscoverCard) {\n                    requireActivity().startActivity(RecommendedReadingListSettingsActivity.newIntent(requireContext()))\n                } else {\n                    customizeInterestsLauncher.launch(PersonalizationActivity.newIntent(requireContext(), showInterestsOnly = true))\n                }\n            }\n            HomeAction.TabClick -> {\n                requireActivity().startActivity(TabActivity.newIntent(requireActivity()))\n            }\n            HomeAction.UpdateTabCount -> {\n                viewModel.updateTabCount(false)\n            }\n            is HomeAction.CardImpression -> {\n                onCardImpression(action.card, action.index)\n            }\n            is HomeAction.CardFooterClick -> {\n                when (val card = action.card) {\n                    is TopReadCard -> {\n                        instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"more_top_read\")\n                        startActivity(TopReadArticlesActivity.newIntent(requireActivity(),\n                            TopReadCard(card.articles, card.age, wikiSite)\n                        ))\n                    }\n                    is OnThisDayCard -> {\n                        instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"more_on_this_day\")\n                        startActivity(OnThisDayActivity.newIntent(requireActivity(), card.age, -1, wikiSite, InvokeSource.ON_THIS_DAY_CARD_FOOTER))\n                    }\n                    is DidYouKnowCard -> {\n                        instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"more_did_you_know\")\n                        startActivity(DidYouKnowActivity.newIntent(requireActivity(), card.site, card.items))\n                    }\n                }\n            }\n            HomeAction.NotificationClick -> {\n                requireActivity().startActivity(NotificationActivity.newIntent(requireActivity()))\n            }\n            HomeAction.ManageModulesClick -> {\n                instrument.submitInteraction(\"click\", actionSource = \"feed_empty\", elementId = \"customize_feed\")\n                val intent = HomeFeedSettingsActivity.newIntent(\n                    context = requireContext(),\n                    startDestination = when (selectedTab) {\n                        HomeTab.COMMUNITY -> HomeFeedSettingsStartDestination.COMMUNITY_MODULES\n                        HomeTab.FOR_YOU -> HomeFeedSettingsStartDestination.FOR_YOU_MODULES\n                    }\n                )\n                requireActivity().startActivity(intent)\n            }\n            HomeAction.ShuffleClick -> {\n                instrument.submitInteraction(\"click\", actionSource = RandomCard::class.java.simpleName, elementId = \"random_card_shuffle_button\")\n                startActivity(RandomActivity.newIntent(requireActivity(), wikiSite, InvokeSource.FEED))\n            }\n            HomeAction.PlacesTeaserClick -> {\n                instrument.submitInteraction(\"click\", actionSource = PlacesOfInterestLocationPromptCard::class.java.simpleName, elementId = \"go_to_places\")\n                requireActivity().startActivity(PlacesActivity.newIntent(requireContext()))\n            }\n            HomeAction.DiscoverTeaserClick -> {\n                instrument.submitInteraction(\"click\", actionSource = DiscoverEnablePromptCard::class.java.simpleName, elementId = \"enable_discover_reading_list_button\")\n                requireActivity().startActivity(RecommendedReadingListOnboardingActivity.newIntent(requireContext()))\n            }\n            HomeAction.SeeAllRecommendationsClick -> {\n                instrument.submitInteraction(\"click\", actionSource = SeeAllRecommendationCard::class.java.simpleName, elementId = \"explore_all_recommendations_button\")\n                startActivity(ReadingListActivity.newIntent(requireContext(), readingListMode = ReadingListMode.RECOMMENDED))\n            }\n            is HomeAction.GameActionClick -> {\n                when (val wikiGame = action.wikiGame) {\n                    is WikiGame.OnThisDayGame -> {\n                        val gameStatus = when (wikiGame.state) {\n                            is OnThisDayCardGameState.Completed -> DailyGameHistory.GAME_COMPLETED\n                            is OnThisDayCardGameState.InProgress,\n                            is OnThisDayCardGameState.Preview -> DailyGameHistory.GAME_IN_PROGRESS\n                        }\n                        val elementId = when (wikiGame.state) {\n                            is OnThisDayCardGameState.Preview -> \"play_click\"\n                            is OnThisDayCardGameState.InProgress -> \"continue_click\"\n                            is OnThisDayCardGameState.Completed -> \"review_click\"\n                        }\n                        instrument.submitInteraction(\"click\", actionSource = WikiGameCard::class.java.simpleName, elementId = elementId, actionContext = mapOf(\"game\" to wikiGame.game.name))\n                        requireActivity().startActivity(OnThisDayGameActivity.newIntent(\n                            context = requireContext(),\n                            invokeSource = InvokeSource.FEED,\n                            wikiSite = wikiSite,\n                            gameStatus = gameStatus\n                        ))\n                    }\n                }\n            }\n            HomeAction.GoToGamesHubClick -> {\n                instrument.submitInteraction(\"click\", actionSource = GamesModulePromptCard::class.java.simpleName, elementId = \"go_to_games_hub\")\n                requireActivity().startActivity(GamesHubActivity.newIntent(requireContext(), InvokeSource.FEED))\n            }\n            HomeAction.ReadAloudPlayClick -> {\n                instrument.submitInteraction(\"click\", actionSource = ReadAloudLeadSectionCard::class.java.simpleName, elementId = \"play_pause\")\n            }\n            HomeAction.ReadAloudShowInfo -> {\n                instrument.submitInteraction(\"click\", actionSource = ReadAloudLeadSectionCard::class.java.simpleName, elementId = \"menu_about\")\n                UriUtil.visitInExternalBrowser(requireContext(), getString(R.string.read_aloud_lead_section_info_link).toUri())\n            }\n            HomeAction.ReadAloudReportIssue -> {\n                instrument.submitInteraction(\"click\", actionSource = ReadAloudLeadSectionCard::class.java.simpleName, elementId = \"menu_report_issue\")\n                FeedbackUtil.composeEmail(requireContext(),\n                    subject = getString(R.string.read_aloud_lead_section_report_subject),\n                    body = getString(R.string.read_aloud_lead_section_report_body))\n            }\n            else -> {\n            }\n        }\n    }\n\n    private fun onCardImpression(card: Card, index: Int) {\n        if (cardImpressions.add(card.hideKey)) {\n            instrument.submitInteraction(\n                \"impression\",\n                actionSource = card.javaClass.simpleName,\n                actionContext = mapOf(\"card_index\" to index)\n            )\n        }\n    }\n\n    private fun maybeShowSurveyDialog() {\n        val endDate = LocalDate.of(2026, 8, 14)\n        val minVisits = 4\n\n        // don't show the survey if the user has not seen other dialogs or prompts that can be shown on the feed\n        if (!Prefs.isExploreFeedUpdatePromptShown) {\n            return\n        }\n\n        if (Prefs.homeFeedSurveyShown || LocalDate.now().isAfter(endDate)) {\n            return\n        }\n\n        if (Prefs.exploreFeedVisitCount < minVisits) {\n            return\n        }\n\n        Prefs.homeFeedSurveyShown = true\n        SurveyDialog.showHomeFeedFeedbackDialog(\n            activity = requireActivity(),\n            onImpression = {\n                instrument.submitInteraction(\n                    action = \"impression\",\n                    actionSource = \"home_feed_feedback\"\n                )\n            },\n            onCancel = {\n                instrument.submitInteraction(\n                    action = \"click\",\n                    actionSource = \"home_feed_feedback\",\n                    elementId = \"feedback_cancel\"\n                )\n            },\n            onSubmit = { feedbackOption, feedbackText ->\n                instrument.submitInteraction(\n                    action = \"click\",\n                    actionSource = \"home_feed_feedback\",\n                    elementId = \"feedback_submit\",\n                    actionContext = buildMap {\n                        feedbackOption?.let { put(\"score\", it) }\n                        put(\"text\", feedbackText)\n                    }\n                )\n            }\n        )\n    }\n\n    override fun onLinkPreviewLoadPage(title: PageTitle, entry: HistoryEntry, inNewTab: Boolean) {\n        if (inNewTab) {\n            (parentFragment as? MainFragment)?.onFeedSelectPage(entry, true)\n            viewModel.updateTabCount(true)\n        } else {\n            (parentFragment as? MainFragment)?.onFeedSelectPage(entry, false)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/HomeFragment.kt","kind":"class","line":92,"members":{"cardImpressions":[95,95],"customizeInterestsLauncher":[110,115],"getCurrentTab":[222,224],"handleHomeAction":[250,485],"instrument":[96,101],"maybeShowExploreFeedUpdatePrompt":[244,248],"maybeShowSurveyDialog":[497,542],"onCardImpression":[487,495],"onCreate":[117,133],"onCreateView":[135,206],"onLinkPreviewLoadPage":[544,551],"onPause":[226,229],"onResume":[208,220],"pageOverflowMenuViewModel":[94,94],"personalizationResultLauncher":[103,108],"refreshNotification":[231,233],"selectTab":[239,242],"updateLanguage":[235,237],"viewModel":[93,93]},"shot":"shots/code/HomeFragment.jpg","supers":["Fragment()","LinkPreviewDialog.LoadPageCallback"]},"InitialOnboardingActivity":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["launch","h-classes","Logic \u00b7 class diagram"],["launch","h-widgets","Screen \u00b7 composition"],["launch","h-sequence","First launch \u00b7 sequence"]],"code":"class InitialOnboardingActivity : BaseActivity() {\n\n    private val appLanguageCodesState = mutableStateOf(WikipediaApp.instance.languageState.appLanguageCodes.toList())\n\n    private val languagesLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        appLanguageCodesState.value = WikipediaApp.instance.languageState.appLanguageCodes.toList()\n        Prefs.homeLanguageCode = WikipediaApp.instance.languageState.appLanguageCode\n        setResult(RESULT_LANGUAGE_CHANGED)\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        DeviceUtil.setEdgeToEdge(this)\n\n        _instrument = TestKitchenAdapter.client.getInstrument(\"apps-onboarding\")\n            .setDefaultActionSource(\"initial_onboarding\")\n            .startFunnel(\"initial_onboarding\")\n\n        setContent {\n            var currentTheme by rememberSaveable { mutableStateOf(Theme.BLACK) }\n            var currentNavigationBarColor by rememberSaveable { mutableIntStateOf(ContextCompat.getColor(window.context, android.R.color.black)) }\n            DeviceUtil.setLightSystemUiVisibility(this, !currentTheme.isDark)\n            setNavigationBarColor(currentNavigationBarColor)\n            BaseTheme(\n                currentTheme = currentTheme\n            ) {\n                AppOnboardingScreen(\n                    languageState = WikipediaApp.instance.languageState,\n                    appLanguageCodes = appLanguageCodesState.value,\n                    isNewUser = Prefs.isInitialOnboardingEnabled,\n                    onAddLanguageClick = {\n                        languagesLauncher.launch(WikipediaLanguagesActivity.newIntent(this, Constants.InvokeSource.ONBOARDING_DIALOG))\n                    },\n                    onUpdateTheme = {\n                        currentTheme = WikipediaApp.instance.currentTheme\n                        currentNavigationBarColor = ResourceUtil.getThemedColor(this, R.attr.paper_color)\n                    },\n                    onFinish = {\n                        Prefs.isInitialOnboardingEnabled = false\n                        Prefs.isExploreFeedUpdatePromptShown = true\n                        startActivity(PersonalizationActivity.newIntent(this))\n                        finish()\n                    }\n                )\n            }\n        }\n    }\n\n    companion object {\n        // TODO: need to refresh the language state at the final screen\n        const val RESULT_LANGUAGE_CHANGED = 1\n        fun newIntent(context: Context): Intent {\n            return Intent(context, InitialOnboardingActivity::class.java)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/onboarding/InitialOnboardingActivity.kt","kind":"class","line":31,"members":{"RESULT_LANGUAGE_CHANGED":[80,81],"appLanguageCodesState":[33,33],"languagesLauncher":[35,39],"newIntent":[82,84],"onCreate":[41,77]},"shot":"shots/code/InitialOnboardingActivity.jpg","supers":["BaseActivity()"]},"MainFragment":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["launch","h-classes","Logic \u00b7 class diagram"],["settings","h-classes","Logic \u00b7 class diagram"],["settings","h-sequence","Open Settings from More \u00b7 sequence"]],"code":"class MainFragment : Fragment(), BackPressedHandler, MenuProvider, HistoryFragment.Callback, MenuNavTabDialog.Callback, ActivityTabFragment.Callback {\n    interface Callback {\n        fun onTabChanged(tab: NavTab)\n        fun updateToolbarElevation(elevate: Boolean)\n    }\n\n    private var _binding: FragmentMainBinding? = null\n    val binding get() = _binding!!\n\n    private lateinit var notificationButtonView: NotificationButtonView\n    private var tabCountsView: TabCountsView? = null\n    private var showTabCountsAnimation = false\n    private val downloadReceiver = MediaDownloadReceiver()\n    private val downloadReceiverCallback = MediaDownloadReceiverCallback()\n    private val pageChangeCallback = PageChangeCallback()\n\n    // The permissions request API doesn't take a callback, so in the event we have to\n    // ask for permission to download a featured image from the feed, we'll have to hold\n    // the image we're waiting for permission to download as a bit of state here. :(\n    private var pendingDownloadImage: FeaturedImage? = null\n\n    private val requestPermissionLauncher = registerForActivityResult(ActivityResultContracts.RequestPermission()) { isGranted: Boolean ->\n        if (isGranted) {\n            pendingDownloadImage?.let { download(it) }\n        } else {\n            FeedbackUtil.showMessage(this, R.string.gallery_save_image_write_permission_rationale)\n        }\n    }\n\n    private val activityTabOnboardingLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->\n        if (result.resultCode == Activity.RESULT_OK) {\n            binding.root.post {\n                if (isAdded) {\n                    onNavigateTo(NavTab.EDITS)\n                }\n            }\n        }\n    }\n\n    private val shouldShowYearInReviewDot get() =\n        YearInReviewViewModel.canShowEntryPoint && Prefs.yearInReviewActivityTabDotSeenYear != YearInReviewViewModel.YIR_YEAR\n\n    var navTabBackStack = mutableListOf<NavTab>()\n    val currentFragment get() = (binding.mainViewPager.adapter as NavTabFragmentPagerAdapter).getFragmentAt(binding.mainViewPager.currentItem)\n\n    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {\n        super.onCreateView(inflater, container, savedInstanceState)\n        _binding = FragmentMainBinding.inflate(inflater, container, false)\n        requireActivity().addMenuProvider(this, viewLifecycleOwner, Lifecycle.State.RESUMED)\n\n        lifecycleScope.launch {\n            repeatOnLifecycle(Lifecycle.State.CREATED) {\n                FlowEventBus.events.collectLatest { event ->\n                    when (event) {\n                        is LoggedInEvent -> {\n                            refreshContents()\n                            FeedbackUtil.showMessage(this@MainFragment, R.string.login_success_toast)\n                        }\n                        is LoggedOutEvent,\n                        is LoggedOutInBackgroundEvent -> {\n                            requireActivity().invalidateOptionsMenu()\n                            (currentFragment as? HomeFragment)?.refreshNotification()\n                            ExclusiveBottomSheetPresenter.dismiss(childFragmentManager)\n                            refreshContents()\n                        }\n                        is ImportReadingListsEvent -> {\n                            maybeShowImportReadingListsNewInstallDialog()\n                        }\n                        is NewRecommendedReadingListEvent -> {\n                            binding.mainNavTabLayout.setOverlayDot(NavTab.READING_LISTS, Prefs.isRecommendedReadingListEnabled && Prefs.isNewRecommendedReadingListGenerated)\n                        }\n                    }\n                }\n            }\n        }\n\n        binding.mainViewPager.isUserInputEnabled = false\n        binding.mainViewPager.adapter = NavTabFragmentPagerAdapter(this)\n        binding.mainViewPager.registerOnPageChangeCallback(pageChangeCallback)\n        binding.mainNavTabLayout.descendants.filterIsInstance<TextView>().forEach {\n            it.maxLines = 2\n            it.textAlignment = View.TEXT_ALIGNMENT_CENTER\n        }\n        val shouldShowRedDotForRecommendedReadingList = (!Prefs.isRecommendedReadingListOnboardingShown) || (Prefs.isRecommendedReadingListEnabled && Prefs.isNewRecommendedReadingListGenerated)\n        binding.mainNavTabLayout.setOverlayDot(NavTab.READING_LISTS, shouldShowRedDotForRecommendedReadingList)\n        binding.mainNavTabLayout.setOnItemSelectedListener { item ->\n            navTabBackStack.clear()\n            if (item.order == NavTab.EDITS.code()) {\n                binding.mainNavTabLayout.setOverlayDot(NavTab.EDITS, false)\n                if (YearInReviewViewModel.canShowEntryPoint) {\n                    Prefs.yearInReviewActivityTabDotSeenYear = YearInReviewViewModel.YIR_YEAR\n                }\n\n                if (!Prefs.isActivityTabOnboardingShown) {\n                    activityTabOnboardingLauncher.launch(ActivityTabOnboardingActivity.newIntent(requireContext()))\n                    return@setOnItemSelectedListener false\n                }\n            }\n            if (item.order == NavTab.MORE.code()) {\n                ExclusiveBottomSheetPresenter.show(childFragmentManager, MenuNavTabDialog.newInstance())\n                return@setOnItemSelectedListener false\n            }\n            val fragment = currentFragment\n            if (fragment is HistoryFragment && item.order == NavTab.SEARCH.code()) {\n                openSearchActivity(InvokeSource.NAV_MENU, null, null)\n                return@setOnItemSelectedListener true\n            }\n            binding.mainViewPager.setCurrentItem(item.order, false)\n            requireActivity().invalidateOptionsMenu()\n            if (item.order == NavTab.SEARCH.code()) {\n                maybeShowSearchWidgetInstallPrompt()\n            }\n            true\n        }\n\n        maybeShowFeedNewModulesTooltip()\n        Prefs.incrementExploreFeedVisitCount()\n\n        notificationButtonView = NotificationButtonView(requireActivity())\n\n        if (savedInstanceState == null) {\n            handleIntent(requireActivity().intent)\n        }\n        return binding.root\n    }\n\n    override fun onPause() {\n        super.onPause()\n        downloadReceiver.unregister(requireContext())\n    }\n\n    override fun onResume() {\n        super.onResume()\n        downloadReceiver.register(requireContext(), downloadReceiverCallback)\n        // reset the last-page-viewed timer\n        Prefs.pageLastShown = 0\n        binding.mainNavTabLayout.setOverlayDot(NavTab.EDITS, !Prefs.isActivityTabOnboardingShown || shouldShowYearInReviewDot)\n    }\n\n    override fun onDestroyView() {\n        Prefs.isSuggestedEditsHighestPriorityEnabled = false\n        binding.mainViewPager.adapter = null\n        binding.mainViewPager.unregisterOnPageChangeCallback(pageChangeCallback)\n        _binding = null\n        super.onDestroyView()\n    }\n\n    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {\n        if (requestCode == Constants.ACTIVITY_REQUEST_VOICE_SEARCH && resultCode == Activity.RESULT_OK && data != null && data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS) != null) {\n            val searchQuery = data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS)!![0]\n            openSearchActivity(InvokeSource.VOICE, searchQuery, null)\n        } else if (requestCode == Constants.ACTIVITY_REQUEST_GALLERY &&\n                resultCode == GalleryActivity.ACTIVITY_RESULT_PAGE_SELECTED && data != null) {\n            startActivity(data)\n        } else if (requestCode == Constants.ACTIVITY_REQUEST_BROWSE_TABS) {\n            if (WikipediaApp.instance.tabCount == 0) {\n                // They browsed the tabs and cleared all of them, without wanting to open a new tab.\n                return\n            }\n            if (resultCode == TabActivity.RESULT_NEW_TAB) {\n                val entry = HistoryEntry(PageTitle(\n                    MainPageNameData.valueFor(WikipediaApp.instance.appOrSystemLanguageCode),\n                        WikipediaApp.instance.wikiSite), HistoryEntry.SOURCE_MAIN_PAGE)\n                startActivity(PageActivity.newIntentForNewTab(requireContext(), entry, entry.title))\n            } else if (resultCode == TabActivity.RESULT_LOAD_FROM_BACKSTACK) {\n                startActivity(PageActivity.newIntent(requireContext()))\n            }\n        } else if (requestCode == Constants.ACTIVITY_REQUEST_OPEN_SEARCH_ACTIVITY && resultCode == SearchFragment.RESULT_LANG_CHANGED ||\n                (requestCode == Constants.ACTIVITY_REQUEST_SETTINGS &&\n                        (resultCode == SettingsActivity.ACTIVITY_RESULT_LANGUAGE_CHANGED ||\n                                resultCode == SettingsActivity.ACTIVITY_RESULT_FEED_CONFIGURATION_CHANGED ||\n                                resultCode == SettingsActivity.ACTIVITY_RESULT_LOG_OUT))) {\n            refreshContents()\n            if (resultCode == SettingsActivity.ACTIVITY_RESULT_LOG_OUT) {\n                FeedbackUtil.showMessage(requireActivity(), R.string.toast_logout_complete)\n            }\n        } else {\n            super.onActivityResult(requestCode, resultCode, data)\n        }\n    }\n\n    override fun onCreateMenu(menu: Menu, inflater: MenuInflater) {\n        inflater.inflate(R.menu.menu_main, menu)\n    }\n\n    override fun onMenuItemSelected(menuItem: MenuItem): Boolean {\n        val fragment = currentFragment\n        return when (menuItem.itemId) {\n            R.id.menu_filter_reading_lists_articles -> {\n                if (fragment is ReadingListsFragment) {\n                    fragment.showReadingListsFilterMenu()\n                }\n                true\n            }\n            R.id.menu_search_lists -> {\n                if (fragment is ReadingListsFragment) {\n                    fragment.startSearchActionMode()\n                }\n                true\n            }\n            R.id.menu_overflow_button -> {\n                if (fragment is ReadingListsFragment) {\n                    fragment.showReadingListsOverflowMenu()\n                }\n                true\n            }\n            else -> false\n        }\n    }\n\n    override fun onPrepareMenu(menu: Menu) {\n        val readingListsFragment = currentFragment as? ReadingListsFragment\n        menu.findItem(R.id.menu_filter_reading_lists_articles).isVisible =\n            readingListsFragment?.isAllArticlesSelected() == true\n        menu.findItem(R.id.menu_search_lists).isVisible = readingListsFragment != null\n        menu.findItem(R.id.menu_overflow_button).isVisible = readingListsFragment != null\n\n        val tabsItem = menu.findItem(R.id.menu_tabs)\n        if (WikipediaApp.instance.tabCount < 1 || currentFragment is SuggestedEditsTasksFragment) {\n            tabsItem.isVisible = false\n            tabCountsView = null\n        } else {\n            tabsItem.isVisible = true\n            tabCountsView = TabCountsView(requireActivity(), null)\n            tabCountsView!!.setOnClickListener {\n                if (WikipediaApp.instance.tabCount == 1) {\n                    startActivity(PageActivity.newIntent(requireActivity()))\n                } else {\n                    startActivityForResult(TabActivity.newIntent(requireActivity()), Constants.ACTIVITY_REQUEST_BROWSE_TABS)\n                }\n            }\n            tabCountsView!!.updateTabCount(showTabCountsAnimation)\n            tabCountsView!!.contentDescription = getString(R.string.menu_page_show_tabs)\n            tabsItem.actionView = tabCountsView\n            tabsItem.expandActionView()\n            FeedbackUtil.setButtonTooltip(tabCountsView!!)\n            showTabCountsAnimation = false\n        }\n        val notificationMenuItem = menu.findItem(R.id.menu_notifications)\n        if (AccountUtil.isLoggedIn) {\n            notificationMenuItem.isVisible = true\n            notificationButtonView.setUnreadCount(Prefs.notificationUnreadCount)\n            notificationButtonView.setOnClickListener {\n                if (AccountUtil.isLoggedIn) {\n                    startActivity(NotificationActivity.newIntent(requireActivity()))\n                }\n            }\n            notificationButtonView.contentDescription = getString(R.string.notifications_activity_title)\n            notificationMenuItem.actionView = notificationButtonView\n            notificationMenuItem.expandActionView()\n            FeedbackUtil.setButtonTooltip(notificationButtonView)\n        } else {\n            notificationMenuItem.isVisible = false\n        }\n        updateNotificationDot(false)\n    }\n\n    fun handleIntent(intent: Intent) {\n        if (intent.hasExtra(Constants.INTENT_APP_SHORTCUT_RANDOMIZER)) {\n            startActivity(RandomActivity.newIntent(requireActivity(), WikipediaApp.instance.wikiSite, InvokeSource.APP_SHORTCUTS))\n        } else if (intent.hasExtra(Constants.INTENT_APP_SHORTCUT_SEARCH)) {\n            openSearchActivity(InvokeSource.APP_SHORTCUTS, null, null)\n        } else if (intent.hasExtra(Constants.INTENT_APP_SHORTCUT_CONTINUE_READING)) {\n            startActivity(PageActivity.newIntent(requireActivity()))\n        } else if (intent.hasExtra(Constants.INTENT_APP_SHORTCUT_PLACES)) {\n            startActivity(PlacesActivity.newIntent(requireActivity()))\n        } else if (intent.hasExtra(Constants.INTENT_EXTRA_DELETE_READING_LIST)) {\n            onNavigateTo(NavTab.READING_LISTS)\n        } else if (intent.hasExtra(Constants.INTENT_EXTRA_GO_TO_MAIN_TAB) &&\n                !(binding.mainNavTabLayout.selectedItemId == NavTab.HOME.code() &&\n                        intent.getIntExtra(Constants.INTENT_EXTRA_GO_TO_MAIN_TAB, NavTab.HOME.code()) == NavTab.HOME.code())) {\n            onNavigateTo(NavTab.of(intent.getIntExtra(Constants.INTENT_EXTRA_GO_TO_MAIN_TAB, NavTab.HOME.code())))\n        } else if (intent.hasExtra(Constants.INTENT_EXTRA_GO_TO_SE_TAB)) {\n            onNavigateTo(NavTab.of(intent.getIntExtra(Constants.INTENT_EXTRA_GO_TO_SE_TAB, NavTab.EDITS.code())))\n        } else if (intent.hasExtra(Constants.INTENT_EXTRA_PREVIEW_SAVED_READING_LISTS)) {\n            onNavigateTo(NavTab.READING_LISTS)\n        } else if (lastPageViewedWithin(1) && !intent.hasExtra(Constants.INTENT_RETURN_TO_MAIN) && WikipediaApp.instance.tabCount > 0) {\n            startActivity(PageActivity.newIntent(requireContext()))\n        }\n    }\n\n    fun onFeedVoiceSearchRequested() {\n        val intent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH)\n                .putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)\n        try {\n            startActivityForResult(intent, Constants.ACTIVITY_REQUEST_VOICE_SEARCH)\n        } catch (a: ActivityNotFoundException) {\n            FeedbackUtil.showMessage(this, R.string.error_voice_search_not_available)\n        }\n    }\n\n    fun onFeedSelectPage(entry: HistoryEntry, openInNewBackgroundTab: Boolean) {\n        if (openInNewBackgroundTab) {\n            TabUtil.openInNewBackgroundTab(entry)\n            showTabCountsAnimation = true\n            requireActivity().invalidateOptionsMenu()\n        } else {\n            startActivity(PageActivity.newIntentForNewTab(requireContext(), entry, entry.title))\n        }\n    }\n\n    fun onFeedSavePage(entry: HistoryEntry) {\n        SaveArticleSheetDialog.show(childFragmentManager, entry.title)\n    }\n\n    fun onFeedSharePage(entry: HistoryEntry) {\n        ShareUtil.shareText(requireContext(), entry.title.displayText, entry.title.uri)\n    }\n\n    fun onFeedCopyLink(entry: HistoryEntry) {\n        ClipboardUtil.setPlainText(requireContext(), text = entry.title.uri)\n        FeedbackUtil.showMessage(requireActivity(), R.string.address_copied)\n    }\n\n    fun onFeedNewsItemSelected(newsItem: NewsItem, wikiSite: WikiSite) {\n        startActivity(NewsActivity.newIntent(requireActivity(), newsItem, wikiSite))\n    }\n\n    fun onFeedShareImage(image: FeaturedImage, age: Int) {\n        val thumbUrl = image.thumbnailUrl\n        val fullSizeUrl = image.original.source\n        ImageService.loadImage(requireContext(), thumbUrl, onSuccess = { bitmap ->\n            if (!isAdded) {\n                return@loadImage\n            }\n            ShareUtil.shareImage(lifecycleScope, requireContext(), bitmap, File(thumbUrl).name,\n                ShareUtil.getFeaturedImageShareSubject(requireContext(), age), fullSizeUrl)\n        })\n    }\n\n    fun onFeedDownloadImage(image: FeaturedImage) {\n        pendingDownloadImage = image\n        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU ||\n            ContextCompat.checkSelfPermission(requireContext(), Manifest.permission.WRITE_EXTERNAL_STORAGE) == PackageManager.PERMISSION_GRANTED) {\n            download(image)\n        } else {\n            requestPermissionLauncher.launch(Manifest.permission.WRITE_EXTERNAL_STORAGE)\n        }\n    }\n\n    fun onFeaturedImageSelected(image: FeaturedImage) {\n        startActivity(FilePageActivity.newIntent(requireActivity(), image.toPageTitle()))\n    }\n\n    fun onLoginRequested() {\n        startActivity(LoginActivity.newIntent(requireContext(), LoginActivity.SOURCE_NAV))\n    }\n\n    override fun onLoadPage(entry: HistoryEntry) {\n        startActivity(PageActivity.newIntentForCurrentTab(requireContext(), entry, entry.title))\n    }\n\n    override fun onBackPressed(): Boolean {\n        if ((currentFragment as? BackPressedHandler)?.onBackPressed() == true) {\n            return true\n        } else if (navTabBackStack.isNotEmpty()) {\n            onNavigateTo(navTabBackStack.removeLastOrNull()!!)\n            return true\n        }\n        return false\n    }\n\n    override fun usernameClick() {\n        val pageTitle = PageTitle(UserAliasData.valueFor(WikipediaApp.instance.languageState.appLanguageCode), AccountUtil.userName, WikipediaApp.instance.wikiSite)\n        val entry = HistoryEntry(pageTitle, HistoryEntry.SOURCE_MAIN_PAGE)\n        startActivity(PageActivity.newIntentForNewTab(requireContext(), entry, pageTitle))\n    }\n\n    override fun loginClick() {\n        onLoginRequested()\n    }\n\n    override fun talkClick() {\n        if (AccountUtil.isLoggedIn) {\n            startActivity(TalkTopicsActivity.newIntent(requireActivity(),\n                PageTitle(UserTalkAliasData.valueFor(WikipediaApp.instance.languageState.appLanguageCode), AccountUtil.userName,\n                    WikiSite.forLanguageCode(WikipediaApp.instance.appOrSystemLanguageCode)), InvokeSource.NAV_MENU))\n        }\n    }\n\n    override fun settingsClick() {\n        startActivityForResult(SettingsActivity.newIntent(requireActivity()), Constants.ACTIVITY_REQUEST_SETTINGS)\n    }\n\n    override fun watchlistClick() {\n        if (AccountUtil.isLoggedIn) {\n            startActivity(WatchlistActivity.newIntent(requireActivity()))\n        }\n    }\n\n    override fun contribsClick() {\n        if (AccountUtil.isLoggedIn) {\n            startActivity(UserContribListActivity.newIntent(requireActivity(), AccountUtil.userName))\n        }\n    }\n\n    override fun donateClick(campaignId: String?) {\n        (requireActivity() as? BaseActivity)?.launchDonateDialog(campaignId = campaignId)\n    }\n\n    fun setBottomNavVisible(visible: Boolean) {\n        binding.mainNavTabBorder.isVisible = visible\n        binding.mainNavTabLayout.isVisible = visible\n    }\n\n    fun onGoOffline() {\n        val fragment = currentFragment\n        if (fragment is HistoryFragment) {\n            fragment.refresh()\n        }\n    }\n\n    fun onGoOnline() {\n        val fragment = currentFragment\n        if (fragment is HistoryFragment) {\n            fragment.refresh()\n        }\n    }\n\n    fun updateNotificationDot(animate: Boolean) {\n        if (AccountUtil.isLoggedIn && Prefs.notificationUnreadCount > 0) {\n            notificationButtonView.setUnreadCount(Prefs.notificationUnreadCount)\n            if (animate) {\n                notificationButtonView.runAnimation()\n            }\n        } else {\n            notificationButtonView.setUnreadCount(0)\n        }\n    }\n\n    @Suppress(\"SameParameterValue\")\n    private fun lastPageViewedWithin(days: Int): Boolean {\n        return TimeUnit.MILLISECONDS.toDays(System.currentTimeMillis() - Prefs.pageLastShown) < days\n    }\n\n    private fun download(image: FeaturedImage) {\n        pendingDownloadImage = null\n        downloadReceiver.download(requireContext(), image)\n        FeedbackUtil.showMessage(this, R.string.gallery_save_progress)\n    }\n\n    fun openSearchActivity(source: InvokeSource, query: String?, transitionView: View?) {\n        val intent = SearchActivity.newIntent(requireActivity(), source, query)\n        val options = transitionView?.let {\n            if (intent.component?.className == SearchActivity::class.java.name) {\n                ActivityOptions.makeSceneTransitionAnimation(requireActivity(), it, getString(R.string.transition_search_bar))\n            } else null\n        }\n        startActivityForResult(intent, Constants.ACTIVITY_REQUEST_OPEN_SEARCH_ACTIVITY, options?.toBundle())\n    }\n\n    private fun refreshContents() {\n        when (val fragment = currentFragment) {\n            is HistoryFragment -> fragment.refresh()\n            is SuggestedEditsTasksFragment -> fragment.refreshContents()\n        }\n    }\n\n    private fun maybeShowImportReadingListsNewInstallDialog() {\n        if (!Prefs.importReadingListsNewInstallDialogShown) {\n            ReadingListsAnalyticsHelper.logReceiveStart(requireActivity())\n            MaterialAlertDialogBuilder(requireContext())\n                .setTitle(R.string.shareable_reading_lists_new_install_dialog_title)\n                .setMessage(R.string.shareable_reading_lists_new_install_dialog_content)\n                .setNegativeButton(R.string.shareable_reading_lists_new_install_dialog_got_it, null)\n                .show()\n            Prefs.importReadingListsNewInstallDialogShown = true\n        }\n    }\n\n    private fun maybeShowSearchWidgetInstallPrompt() {\n        if (DeviceUtil.areWidgetsSupported && !Prefs.searchWidgetInstallPromptShown && !SearchWidgetInstallDialog.isWidgetInstalled()) {\n            ExclusiveBottomSheetPresenter.show(childFragmentManager, SearchWidgetInstallDialog())\n        }\n    }\n\n    private fun maybeShowFeedNewModulesTooltip() {\n        lifecycleScope.launch {\n            if (ReadAloudLeadSectionABTest().shouldShowToolTip()) {\n                Prefs.readAloudLeadSectionTooltipShown = true\n                binding.root.post {\n                    if (isAdded) {\n                        FeedbackUtil.showTooltip(requireActivity(), binding.mainNavTabLayout.findViewById(NavTab.HOME.id),\n                            getString(R.string.read_aloud_lead_section_tooltip_text), aboveOrBelow = true, autoDismiss = false, showDismissButton = true)\n                        // For the purposes of this experiment, explicitly clear today's cache of For You content,\n                        // so that the Audio content can be loaded when the user goes to For You.\n                        Prefs.homeForYouModulesToday = \"\"\n                    }\n                }\n            }\n        }\n    }\n\n    private inner class PageChangeCallback : OnPageChangeCallback() {\n        override fun onPageSelected(position: Int) {\n            callback()?.onTabChanged(NavTab.of(position))\n        }\n    }\n\n    private inner class MediaDownloadReceiverCallback : MediaDownloadReceiver.Callback {\n        override fun onSuccess() {\n            FeedbackUtil.showMessage(requireActivity(), R.string.gallery_save_success)\n        }\n    }\n\n    private fun callback(): Callback? {\n        return getCallback(this, Callback::class.java)\n    }\n\n    override fun onNavigateTo(navTab: NavTab) {\n        val lastNavTab = NavTab.entries.find { binding.mainNavTabLayout.selectedItemId == binding.mainNavTabLayout.menu[it.code()].itemId }\n        binding.mainNavTabLayout.selectedItemId = binding.mainNavTabLayout.menu[navTab.code()].itemId\n        if (lastNavTab == NavTab.EDITS && navTab != NavTab.EDITS) {\n            navTabBackStack.add(NavTab.EDITS)\n        }\n    }\n\n    companion object {\n        fun newInstance(): MainFragment {\n            return MainFragment().apply {\n                retainInstance = true\n            }\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/main/MainFragment.kt","kind":"class","line":99,"members":{"Callback":[100,103],"MediaDownloadReceiverCallback":[598,602],"PageChangeCallback":[592,596],"_binding":[105,105],"activityTabOnboardingLauncher":[128,136],"binding":[106,106],"callback":[604,606],"contribsClick":[489,493],"currentFragment":[142,142],"donateClick":[495,497],"download":[534,538],"downloadReceiver":[111,111],"downloadReceiverCallback":[112,112],"handleIntent":[356,378],"lastPageViewedWithin":[529,532],"loginClick":[467,469],"maybeShowFeedNewModulesTooltip":[575,590],"maybeShowImportReadingListsNewInstallDialog":[557,567],"maybeShowSearchWidgetInstallPrompt":[569,573],"navTabBackStack":[141,141],"newInstance":[617,621],"notificationButtonView":[108,108],"onActivityResult":[246,278],"onBackPressed":[451,459],"onCreateMenu":[280,282],"onCreateView":[144,223],"onDestroyView":[238,244],"onFeaturedImageSelected":[439,441],"onFeedCopyLink":[408,411],"onFeedDownloadImage":[429,437],"onFeedNewsItemSelected":[413,415],"onFeedSavePage":[400,402],"onFeedSelectPage":[390,398],"onFeedShareImage":[417,427],"onFeedSharePage":[404,406],"onFeedVoiceSearchRequested":[380,388],"onGoOffline":[504,509],"onGoOnline":[511,516],"onLoadPage":[447,449],"onLoginRequested":[443,445],"onMenuItemSelected":[284,307],"onNavigateTo":[608,614],"onPause":[225,228],"onPrepareMenu":[309,354],"onResume":[230,236],"openSearchActivity":[540,548],"pageChangeCallback":[113,113],"pendingDownloadImage":[115,118],"refreshContents":[550,555],"requestPermissionLauncher":[120,126],"setBottomNavVisible":[499,502],"settingsClick":[479,481],"shouldShowYearInReviewDot":[138,139],"showTabCountsAnimation":[110,110],"tabCountsView":[109,109],"talkClick":[471,477],"updateNotificationDot":[518,527],"usernameClick":[461,465],"watchlistClick":[483,487]},"shot":"shots/code/MainFragment.jpg","supers":["Fragment()","BackPressedHandler","MenuProvider","HistoryFragment.Callback","MenuNavTabDialog.Callback","ActivityTabFragment.Callback"]},"MenuNavTabDialog":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["launch","h-classes","Logic \u00b7 class diagram"],["settings","h-classes","Logic \u00b7 class diagram"],["settings","h-sequence","Open Settings from More \u00b7 sequence"]],"code":"class MenuNavTabDialog : ExtendedBottomSheetDialogFragment() {\n    interface Callback {\n        fun usernameClick()\n        fun loginClick()\n        fun talkClick()\n        fun settingsClick()\n        fun watchlistClick()\n        fun contribsClick()\n        fun donateClick(campaignId: String? = null)\n    }\n\n    private var _binding: ViewMainDrawerBinding? = null\n    private val binding get() = _binding!!\n\n    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {\n        _binding = ViewMainDrawerBinding.inflate(inflater, container, false)\n\n        binding.mainDrawerAccountContainer.setOnClickListener {\n            BreadCrumbLogEvent.logClick(requireActivity(), binding.mainDrawerAccountContainer)\n            if (AccountUtil.isLoggedIn && !AccountUtil.isTemporaryAccount) {\n                callback()?.usernameClick()\n            } else {\n                callback()?.loginClick()\n            }\n            dismiss()\n        }\n\n        binding.mainDrawerTalkContainer.setOnClickListener {\n            BreadCrumbLogEvent.logClick(requireActivity(), binding.mainDrawerTalkContainer)\n            callback()?.talkClick()\n            dismiss()\n        }\n\n        binding.mainDrawerWatchlistContainer.setOnClickListener {\n            BreadCrumbLogEvent.logClick(requireActivity(), binding.mainDrawerWatchlistContainer)\n            callback()?.watchlistClick()\n            dismiss()\n        }\n\n        binding.mainDrawerGamesHubContainer.setOnClickListener {\n            WikiGamesEvent.submit(action = \"games_click\", activeInterface = \"more_menu\")\n            requireActivity().startActivity(GamesHubActivity.newIntent(requireActivity()))\n            dismiss()\n        }\n\n        binding.mainDrawerPlacesContainer.setOnClickListener {\n            PlacesEvent.logAction(\"places_click\", \"main_nav_tab\")\n            requireActivity().startActivity(PlacesActivity.newIntent(requireActivity()))\n            dismiss()\n        }\n\n        binding.mainDrawerSettingsContainer.setOnClickListener {\n            BreadCrumbLogEvent.logClick(requireActivity(), binding.mainDrawerSettingsContainer)\n            callback()?.settingsClick()\n            dismiss()\n        }\n\n        binding.mainDrawerContribsContainer.setOnClickListener {\n            BreadCrumbLogEvent.logClick(requireActivity(), binding.mainDrawerContribsContainer)\n            callback()?.contribsClick()\n            dismiss()\n        }\n\n        binding.mainDrawerDonateContainer.setOnClickListener {\n            BreadCrumbLogEvent.logClick(requireActivity(), binding.mainDrawerDonateContainer)\n            DonorExperienceEvent.logAction(\"donate_start_click\", \"more_menu\")\n            callback()?.donateClick()\n            dismiss()\n        }\n\n        binding.mainDrawerEditContainer.setOnClickListener {\n            BreadCrumbLogEvent.logClick(requireActivity(), binding.mainDrawerEditContainer)\n            ActivityTabEvent.submit(activeInterface = \"more_menu\", action = \"edit_click\")\n            startActivity(SuggestedEditsTasksActivity.newIntent(requireContext()))\n            dismiss()\n        }\n\n        updateState()\n        return binding.root\n    }\n\n    override fun onDestroyView() {\n        super.onDestroyView()\n        _binding = null\n    }\n\n    override fun onStart() {\n        super.onStart()\n        BottomSheetBehavior.from(binding.root.parent as View).peekHeight = DimenUtil.displayHeightPx\n    }\n\n    private fun updateState() {\n        if (AccountUtil.isLoggedIn) {\n            if (AccountUtil.isTemporaryAccount) {\n                binding.mainDrawerAccountAvatar.setImageResource(R.drawable.ic_login_24px)\n                ImageViewCompat.setImageTintList(binding.mainDrawerAccountAvatar, getThemedColorStateList(requireContext(), R.attr.progressive_color))\n                binding.tempAccountName.text = AccountUtil.userName\n                binding.mainDrawerAccountName.isVisible = false\n                binding.mainDrawerLoginButton.textAlignment = View.TEXT_ALIGNMENT_TEXT_START\n                binding.mainDrawerLoginButton.text = getString(R.string.main_drawer_login)\n                binding.mainDrawerLoginButton.setTextColor(getThemedColorStateList(requireContext(), R.attr.progressive_color))\n                binding.mainDrawerLoginButton.isVisible = true\n            } else {\n                binding.mainDrawerAccountAvatar.setImageResource(R.drawable.ic_baseline_person_24)\n                ImageViewCompat.setImageTintList(binding.mainDrawerAccountAvatar, getThemedColorStateList(requireContext(), R.attr.secondary_color))\n                binding.mainDrawerAccountName.text = AccountUtil.userName\n                binding.mainDrawerAccountName.isVisible = true\n                binding.mainDrawerLoginButton.isVisible = false\n            }\n            binding.mainDrawerTalkContainer.isVisible = true\n            binding.mainDrawerTempAccountContainer.isVisible = AccountUtil.isTemporaryAccount\n            binding.mainDrawerWatchlistContainer.isVisible = !AccountUtil.isTemporaryAccount\n            binding.mainDrawerContribsContainer.isVisible = true\n            binding.mainDrawerEditContainer.isVisible = true\n        } else {\n            binding.mainDrawerAccountAvatar.setImageResource(R.drawable.ic_login_24px)\n            ImageViewCompat.setImageTintList(binding.mainDrawerAccountAvatar, getThemedColorStateList(requireContext(), R.attr.progressive_color))\n            binding.mainDrawerAccountName.isVisible = false\n            binding.mainDrawerTempAccountContainer.isVisible = false\n            binding.mainDrawerLoginButton.textAlignment = View.TEXT_ALIGNMENT_TEXT_START\n            binding.mainDrawerLoginButton.text = getString(R.string.main_drawer_login)\n            binding.mainDrawerLoginButton.setTextColor(getThemedColorStateList(requireContext(), R.attr.progressive_color))\n            binding.mainDrawerTalkContainer.isVisible = false\n            binding.mainDrawerWatchlistContainer.isVisible = false\n            binding.mainDrawerContribsContainer.isVisible = false\n            binding.mainDrawerEditContainer.isVisible = false\n        }\n        binding.mainDrawerGamesHubContainer.isVisible = WikiGames.WHICH_CAME_FIRST.isLangSupported(*WikipediaApp.instance.languageState.appLanguageCodes.toTypedArray())\n    }\n\n    private fun callback(): Callback? {\n        return FragmentUtil.getCallback(this, Callback::class.java)\n    }\n\n    companion object {\n        fun newInstance(): MenuNavTabDialog {\n            return MenuNavTabDialog()\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/navtab/MenuNavTabDialog.kt","kind":"class","line":28,"members":{"Callback":[29,37],"_binding":[39,39],"binding":[40,40],"callback":[158,160],"newInstance":[163,165],"onCreateView":[42,107],"onDestroyView":[109,112],"onStart":[114,117],"updateState":[119,156]},"shot":"shots/code/MenuNavTabDialog.jpg","supers":["ExtendedBottomSheetDialogFragment()"]},"PageActivity":{"appearsIn":[["article","h-classes","Logic \u00b7 class diagram"],["article","h-widgets","Screen \u00b7 view composition"],["index","h-screens","Screens \u00b7 how the user moves"]],"code":"class PageActivity : BaseActivity(), PageFragment.Callback, LinkPreviewDialog.LoadPageCallback, FrameLayoutNavMenuTriggerer.Callback {\n\n    enum class TabPosition {\n        CURRENT_TAB, CURRENT_TAB_SQUASH, NEW_TAB_BACKGROUND, NEW_TAB_FOREGROUND, EXISTING_TAB\n    }\n\n    lateinit var binding: ActivityPageBinding\n    private lateinit var toolbarHideHandler: ViewHideHandler\n    private lateinit var pageFragment: PageFragment\n    private lateinit var app: WikipediaApp\n    private var hasTransitionAnimation = false\n    private var wasTransitionShown = false\n    private val currentActionModes = mutableSetOf<ActionMode>()\n    private val isCabOpen get() = currentActionModes.isNotEmpty()\n    private var exclusiveTooltipRunnable: Runnable? = null\n    private var isTooltipShowing = false\n    private val semanticSearchFeedbackViewModel: SemanticSearchArticleFeedbackViewModel by viewModels()\n    private var semanticSearchFeedbackJob: Job? = null\n\n    private val requestEditSectionLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == EditHandler.RESULT_REFRESH_PAGE) {\n            FeedbackUtil.makeSnackbar(this, getString(R.string.edit_saved_successfully))\n                .addCallback(object : Snackbar.Callback() {\n                    override fun onDismissed(transientBottomBar: Snackbar, @DismissEvent event: Int) {\n                        if (!isDestroyed) {\n                            AccountUtil.maybeShowTempAccountWelcome(this@PageActivity)\n                        }\n                    }\n                }).show()\n\n            // and reload the page...\n            pageFragment.refreshPage()\n        }\n    }\n\n    private val requestHandleIntentLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == LangLinksActivity.ACTIVITY_RESULT_LANGLINK_SELECT || it.resultCode == GalleryActivity.ACTIVITY_RESULT_PAGE_SELECTED) {\n            it.data?.let {\n                binding.pageToolbarContainer.post { handleIntent(it) }\n            }\n        }\n    }\n\n    private val requestGalleryEditLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == GalleryActivity.ACTIVITY_RESULT_IMAGE_CAPTION_ADDED || it.resultCode == GalleryActivity.ACTIVITY_RESULT_IMAGE_TAGS_ADDED) {\n            pageFragment.reloadFromBackstack()\n        }\n    }\n\n    private val requestBrowseTabLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (app.tabCount == 0 && it.resultCode != TabActivity.RESULT_NEW_TAB) {\n            // They browsed the tabs and cleared all of them, without wanting to open a new tab.\n            finish()\n            return@registerForActivityResult\n        }\n        if (it.resultCode == TabActivity.RESULT_NEW_TAB) {\n            loadMainPage(TabPosition.NEW_TAB_FOREGROUND)\n            animateTabsButton()\n        } else if (it.resultCode == TabActivity.RESULT_LOAD_FROM_BACKSTACK) {\n            pageFragment.reloadFromBackstack(false)\n        }\n    }\n\n    private val requestSuggestedEditsLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == RESULT_OK || it.resultCode == DescriptionEditSuccessActivity.RESULT_OK_FROM_EDIT_SUCCESS) {\n            pageFragment.refreshPage()\n            val data = it.data\n            val editLanguage = pageFragment.leadImageEditLang.orEmpty().ifEmpty { app.languageState.appLanguageCode }\n            val action = if (data != null && data.hasExtra(Constants.INTENT_EXTRA_ACTION))\n                data.getSerializableExtra(Constants.INTENT_EXTRA_ACTION) as DescriptionEditActivity.Action?\n            else null\n\n            SuggestedEditsSnackbars.show(this, action, it.resultCode != DescriptionEditSuccessActivity.RESULT_OK_FROM_EDIT_SUCCESS,\n                editLanguage, action !== DescriptionEditActivity.Action.ADD_DESCRIPTION && action !== DescriptionEditActivity.Action.TRANSLATE_DESCRIPTION) {\n                pageFragment.page?.leadImageName?.let { imageName ->\n                    val wikiSite = WikiSite.forLanguageCode(pageFragment.leadImageEditLang.orEmpty().ifEmpty { app.appOrSystemLanguageCode })\n                    val imageTitle = PageTitle(\"File:${StringUtil.removeNamespace(imageName)}\", wikiSite)\n                    if (action === DescriptionEditActivity.Action.ADD_IMAGE_TAGS) {\n                        startActivity(FilePageActivity.newIntent(this, imageTitle))\n                    } else if (action === DescriptionEditActivity.Action.ADD_CAPTION || action === DescriptionEditActivity.Action.TRANSLATE_CAPTION) {\n                        pageFragment.title?.let { pageTitle ->\n                            startActivity(GalleryActivity.newIntent(this, pageTitle, imageTitle.prefixedText, wikiSite))\n                        }\n                    }\n                }\n            }\n        }\n    }\n\n    public override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        if (!DeviceUtil.assertAppContext(this)) {\n            return\n        }\n\n        app = WikipediaApp.instance\n\n        PreferenceManager.setDefaultValues(this, R.xml.preferences, false)\n        binding = ActivityPageBinding.inflate(layoutInflater)\n        setContentView(binding.root)\n\n        onBackPressedDispatcher.addCallback(this, onBackPressedCallback)\n\n        lifecycleScope.launch {\n            repeatOnLifecycle(Lifecycle.State.CREATED) {\n                FlowEventBus.events.collectLatest { event ->\n                    when (event) {\n                        is ChangeTextSizeEvent -> {\n                            pageFragment.updateFontSize()\n                        }\n                        is ArticleSavedOrDeletedEvent -> {\n                            pageFragment.title?.run {\n                                if (event.pages.any { it.apiTitle == prefixedText && it.lang == wikiSite.languageCode }) {\n                                    pageFragment.updateBookmarkAndMenuOptionsFromDao()\n                                }\n                            }\n                        }\n                        is LoggedInEvent -> {\n                            updateForLoginState()\n                            FeedbackUtil.showMessage(this@PageActivity, R.string.login_success_toast)\n                        }\n                        is LoggedOutEvent -> {\n                            updateForLoginState()\n                        }\n                    }\n                }\n            }\n        }\n\n        updateProgressBar(false)\n        pageFragment = supportFragmentManager.findFragmentById(R.id.page_fragment) as PageFragment\n\n        // Toolbar setup\n        setSupportActionBar(binding.pageToolbar)\n        clearActionBarTitle()\n        supportActionBar?.setDisplayHomeAsUpEnabled(true)\n\n        binding.pageToolbarButtonSearch.setOnClickListener {\n            pageFragment.articleInteractionEvent?.logSearchWikipediaClick()\n            val articleTitle = if (pageFragment.title?.namespace() == Namespace.MAIN) pageFragment.title?.displayText else null\n            startActivity(SearchActivity.newIntent(\n                context = this@PageActivity,\n                source = InvokeSource.TOOLBAR,\n                query = null,\n                title = articleTitle))\n        }\n        binding.pageToolbarButtonTabs.updateTabCount(false)\n        binding.pageToolbarButtonTabs.setOnClickListener {\n            pageFragment.articleInteractionEvent?.logTabsClick()\n            requestBrowseTabLauncher.launch(TabActivity.newIntentFromPageActivity(this))\n        }\n        toolbarHideHandler = ViewHideHandler(binding.pageToolbarContainer, null, Gravity.TOP) { isTooltipShowing }\n        FeedbackUtil.setButtonTooltip(binding.pageToolbarButtonNotifications, binding.pageToolbarButtonTabs, binding.pageToolbarButtonShowOverflowMenu)\n        binding.pageToolbarButtonShowOverflowMenu.setOnClickListener {\n            pageFragment.showOverflowMenu(it)\n            pageFragment.articleInteractionEvent?.logMoreClick()\n            Prefs.showOneTimeCustomizeToolbarTooltip = false\n        }\n\n        binding.pageToolbarButtonNotifications.setOnClickListener {\n            pageFragment.articleInteractionEvent?.logNotificationClick()\n            if (AccountUtil.isLoggedIn) {\n                startActivity(NotificationActivity.newIntent(this@PageActivity))\n            } else if (AnonymousNotificationHelper.isWithinAnonNotificationTime() && !Prefs.lastAnonNotificationLang.isNullOrEmpty()) {\n                val wikiSite = WikiSite.forLanguageCode(Prefs.lastAnonNotificationLang!!)\n                startActivity(TalkTopicsActivity.newIntent(this@PageActivity,\n                PageTitle(UserTalkAliasData.valueFor(wikiSite.languageCode) + \":\" + Prefs.lastAnonUserWithMessages, wikiSite), InvokeSource.PAGE_ACTIVITY))\n            }\n        }\n\n        // Navigation setup\n        binding.navigationDrawer.setScrimColor(Color.TRANSPARENT)\n        binding.containerWithNavTrigger.callback = this\n        ViewCompat.setOnApplyWindowInsetsListener(binding.navigationDrawer) { view, insets ->\n            val insets = insets.getInsets(WindowInsetsCompat.Type.systemBars())\n            view.updateLayoutParams<MarginLayoutParams> {\n                topMargin = insets.top\n                leftMargin = insets.left\n                bottomMargin = insets.bottom\n                rightMargin = insets.right\n            }\n            WindowInsetsCompat.CONSUMED\n        }\n\n        // WikiArticleCard setup\n        hasTransitionAnimation = intent.getBooleanExtra(Constants.INTENT_EXTRA_HAS_TRANSITION_ANIM, false)\n        binding.wikiArticleCardView.visibility = if (hasTransitionAnimation) View.VISIBLE else View.GONE\n\n        val languageChanged = savedInstanceState?.let {\n            app.appOrSystemLanguageCode != savedInstanceState.getString(LANGUAGE_CODE_BUNDLE_KEY).orEmpty()\n        } ?: false\n\n        if (languageChanged) {\n            app.resetWikiSite()\n            loadMainPage(TabPosition.EXISTING_TAB)\n        }\n\n        if (savedInstanceState == null) {\n            // if there's no savedInstanceState, and we're not coming back from a Theme change,\n            // then we must have been launched with an Intent, so... handle it!\n            handleIntent(intent)\n        }\n        updateForLoginState()\n    }\n\n    override fun onStart() {\n        try {\n            super.onStart()\n        } catch (e: Exception) {\n            if (e.message.orEmpty().contains(EXCEPTION_MESSAGE_WEBVIEW, true) ||\n                ThrowableUtil.getInnermostThrowable(e).message.orEmpty().contains(EXCEPTION_MESSAGE_WEBVIEW, true)) {\n                // If the system failed to inflate our activity because of the WebView (which could\n                // be one of several types of exceptions), it likely means that the system WebView\n                // is in the process of being updated. In this case, show the user a message and\n                // bail immediately.\n                Toast.makeText(app, R.string.error_webview_updating, Toast.LENGTH_LONG).show()\n                finish()\n                return\n            }\n            throw e\n        }\n    }\n\n    override fun onPrepareOptionsMenu(menu: Menu): Boolean {\n        if (!isDestroyed) {\n            binding.pageToolbarButtonTabs.updateTabCount(false)\n        }\n        return false\n    }\n\n    override fun onOptionsItemSelected(item: MenuItem): Boolean {\n        return when (item.itemId) {\n            android.R.id.home -> {\n                if (app.haveMainActivity) {\n                    onBackPressedDispatcher.onBackPressed()\n                } else {\n                    pageFragment.goToMainActivity(tab = NavTab.HOME, tabExtra = Constants.INTENT_EXTRA_GO_TO_MAIN_TAB)\n                }\n                true\n            } else -> super.onOptionsItemSelected(item)\n        }\n    }\n\n    override fun onResume() {\n        super.onResume()\n        app.resetWikiSite()\n        updateNotificationsButton(false)\n        Prefs.temporaryWikitext = null\n    }\n\n    override fun onPause() {\n        if (isCabOpen) {\n            onPageCloseActionMode()\n        }\n        super.onPause()\n    }\n\n    override fun onSaveInstanceState(outState: Bundle) {\n        super.onSaveInstanceState(outState)\n        outState.putString(LANGUAGE_CODE_BUNDLE_KEY, app.appOrSystemLanguageCode)\n    }\n\n    override fun onActionModeStarted(mode: ActionMode) {\n        super.onActionModeStarted(mode)\n        if (!isCabOpen && mode.tag == null) {\n            modifyMenu(mode)\n            ViewUtil.setCloseButtonInActionMode(pageFragment.requireContext(), mode)\n            pageFragment.onActionModeShown(mode)\n        }\n        currentActionModes.add(mode)\n    }\n\n    override fun onActionModeFinished(mode: ActionMode) {\n        super.onActionModeFinished(mode)\n        currentActionModes.remove(mode)\n    }\n\n    override fun onDestroy() {\n        Prefs.hasVisitedArticlePage = true\n        if (isFinishing) {\n            cancelSemanticSearchFeedback(FeedbackSuppression.LEFT_ARTICLE)\n        } else if (!isChangingConfigurations) {\n            // The view model is discarded along with this activity, so the pending prompt can't be resumed.\n            cancelSemanticSearchFeedback(FeedbackSuppression.SCREEN_COVERED)\n        }\n        super.onDestroy()\n    }\n\n    override fun onNewIntent(intent: Intent) {\n        super.onNewIntent(intent)\n        setIntent(intent)\n        handleIntent(intent)\n    }\n\n    private fun updateForLoginState() {\n        binding.pageToolbarButtonNotifications.isVisible = AccountUtil.isLoggedIn\n    }\n\n    private val onBackPressedCallback = object : OnBackPressedCallback(true) {\n        override fun handleOnBackPressed() {\n            if (isCabOpen) {\n                onPageCloseActionMode()\n                return\n            }\n            app.appSessionEvent.backPressed()\n            if (pageFragment.onBackPressed()) {\n                return\n            }\n\n            // If user enter PageActivity in portrait and leave in landscape,\n            // we should hide the transition animation view to prevent bad animation.\n            if (DimenUtil.isLandscape(this@PageActivity) || !hasTransitionAnimation) {\n                binding.wikiArticleCardView.visibility = View.GONE\n            } else {\n                binding.wikiArticleCardView.visibility = View.VISIBLE\n                binding.pageFragment.visibility = View.GONE\n            }\n            this.isEnabled = false\n            onBackPressedDispatcher.onBackPressed()\n        }\n    }\n\n    override fun onKeyDown(keyCode: Int, event: KeyEvent): Boolean {\n        if (event.isCtrlPressed && keyCode == KeyEvent.KEYCODE_F || !event.isCtrlPressed && keyCode == KeyEvent.KEYCODE_F3) {\n            pageFragment.showFindInPage()\n            return true\n        }\n        return super.onKeyDown(keyCode, event)\n    }\n\n    override fun onNavMenuSwipeRequest(gravity: Int) {\n        if (!isCabOpen && gravity == Gravity.END) {\n            pageFragment.articleInteractionEvent?.logTocSwipe()\n            pageFragment.sidePanelHandler.showToC()\n        }\n    }\n\n    override fun onPageLoadComplete() {\n        removeTransitionAnimState()\n        maybeShowThemeTooltip()\n        updateSearchHint()\n        lifecycleScope.launch {\n            ReadingChallengeWidgetRepository(this@PageActivity).updateOnArticleRead(LocalDate.now())\n        }\n        scheduleSemanticSearchFeedback()\n    }\n\n    private fun scheduleSemanticSearchFeedback() {\n        val pendingFeedback = semanticSearchFeedbackViewModel.semanticSearchFeedback ?: return\n        if (pageFragment.title != pendingFeedback.title) {\n            cancelSemanticSearchFeedback(FeedbackSuppression.LEFT_ARTICLE)\n            return\n        }\n        if (semanticSearchFeedbackJob != null) {\n            return\n        }\n        val delayMillis = semanticSearchFeedbackViewModel.startCountdown()\n        semanticSearchFeedbackJob = lifecycleScope.launch {\n            delay(delayMillis.milliseconds)\n            val suppression = when {\n                pageFragment.title != pendingFeedback.title -> FeedbackSuppression.LEFT_ARTICLE\n                !lifecycle.currentState.isAtLeast(Lifecycle.State.RESUMED) ||\n                        ExclusiveBottomSheetPresenter.getCurrentBottomSheet(supportFragmentManager) != null ||\n                        ExclusiveBottomSheetPresenter.getCurrentBottomSheet(pageFragment.childFragmentManager) != null -> FeedbackSuppression.SCREEN_COVERED\n                isCabOpen || pageFragment.sidePanelHandler.isVisible -> FeedbackSuppression.STARTED_ACTIVITY\n                else -> null\n            }\n            if (suppression == null) {\n                ExclusiveBottomSheetPresenter.show(supportFragmentManager,\n                    SemanticSearchFeedbackDialog.newInstance(pendingFeedback.title.wikiSite.languageCode,\n                        pendingFeedback.searchId, pendingFeedback.funnel))\n            } else {\n                submitSemanticSearchFeedbackSuppressed(pendingFeedback, suppression)\n            }\n            semanticSearchFeedbackViewModel.clear()\n            semanticSearchFeedbackJob = null\n        }\n    }\n\n    private fun cancelSemanticSearchFeedback(suppression: FeedbackSuppression? = null) {\n        val pendingFeedback = semanticSearchFeedbackViewModel.semanticSearchFeedback\n        if (pendingFeedback != null && suppression != null) {\n            submitSemanticSearchFeedbackSuppressed(pendingFeedback, suppression)\n        }\n        semanticSearchFeedbackJob?.cancel()\n        semanticSearchFeedbackJob = null\n        semanticSearchFeedbackViewModel.clear()\n    }\n\n    private fun submitSemanticSearchFeedbackSuppressed(pendingFeedback: SemanticSearchFeedback, suppression: FeedbackSuppression) {\n        SemanticSearchFeedbackDialog.submitSuppressedEvent(\n            instrument = SemanticSearchFeedbackDialog.newInstrument(pendingFeedback.funnel, pendingFeedback.title.wikiSite),\n            actionSubtype = \"article_result\", suppression\n        )\n    }\n\n    override fun onPageDismissBottomSheet() {\n        ExclusiveBottomSheetPresenter.dismiss(supportFragmentManager)\n    }\n\n    override fun onPageInitWebView(v: ObservableWebView) {\n        toolbarHideHandler.setScrollView(v)\n    }\n\n    override fun onPageLoadPage(title: PageTitle, entry: HistoryEntry) {\n        loadPage(title, entry, TabPosition.CURRENT_TAB)\n    }\n\n    override fun onPageShowLinkPreview(entry: HistoryEntry) {\n        ExclusiveBottomSheetPresenter.show(supportFragmentManager, LinkPreviewDialog.newInstance(entry))\n    }\n\n    override fun onPageLoadMainPageInForegroundTab() {\n        loadMainPage(TabPosition.EXISTING_TAB)\n    }\n\n    override fun onPageUpdateProgressBar(visible: Boolean) {\n        updateProgressBar(visible)\n    }\n\n    override fun onPageStartSupportActionMode(callback: ActionMode.Callback) {\n        startActionMode(callback)\n    }\n\n    override fun onPageHideSoftKeyboard() {\n        DeviceUtil.hideSoftKeyboard(this)\n    }\n\n    override fun onPageWatchlistExpirySelect(expiry: WatchlistExpiry) {\n        pageFragment.updateWatchlistExpiry(expiry)\n    }\n\n    override fun onPageLoadError(title: PageTitle) {\n        supportActionBar?.title = title.displayText\n        removeTransitionAnimState()\n        cancelSemanticSearchFeedback()\n    }\n\n    override fun onPageLoadErrorBackPressed() {\n        finish()\n    }\n\n    override fun onPageSetToolbarElevationEnabled(enabled: Boolean) {\n        binding.pageToolbarContainer.elevation = DimenUtil.dpToPx(if (enabled) DimenUtil.getDimension(R.dimen.toolbar_default_elevation) else 0F)\n    }\n\n    override fun onPageCloseActionMode() {\n        val actionModesToFinish = HashSet(currentActionModes)\n        for (mode in actionModesToFinish) {\n            mode.finish()\n        }\n        currentActionModes.clear()\n    }\n\n    override fun onPageRequestEditSection(sectionId: Int, sectionAnchor: String?, title: PageTitle, highlightText: String?) {\n        val isVisualEditorEnabled = RemoteConfig.config.androidv1?.visualEditorEnabled ?: false\n        val launchEditor = {\n            if (Prefs.editorModeChoice == EDITOR_CHOICE_VE && isVisualEditorEnabled) {\n                openVisualEditorInExternalBrowser(title, sectionId)\n            } else {\n                requestEditSectionLauncher.launch(EditSectionActivity.newIntent(this, sectionId, sectionAnchor, title, InvokeSource.PAGE_ACTIVITY, highlightText))\n            }\n        }\n        if (Prefs.editorModeChoiceShowDialog && isVisualEditorEnabled) {\n            showEditorChoiceDialog(this) { editorChoice, dontShowAgain ->\n                Prefs.editorModeChoice = editorChoice\n                Prefs.editorModeChoiceShowDialog = !dontShowAgain\n                launchEditor()\n            }\n        } else {\n            launchEditor()\n        }\n    }\n\n    private fun openVisualEditorInExternalBrowser(title: PageTitle, sectionId: Int) {\n        val appInstallId = WikipediaApp.instance.appInstallID\n        UriUtil.visitInExternalBrowser(this, title.getWebApiUrl(\"veaction=edit&section=$sectionId&returntoapp=1&appinstallid=$appInstallId\").toUri())\n    }\n\n    override fun onPageRequestLangLinks(title: PageTitle, historyEntryId: Long) {\n        requestHandleIntentLauncher.launch(LangLinksActivity.newIntent(this, title, historyEntryId))\n    }\n\n    override fun onPageRequestGallery(title: PageTitle, fileName: String, wikiSite: WikiSite, revision: Long, isLeadImage: Boolean, options: ActivityOptionsCompat?) {\n        if (isLeadImage) {\n            requestGalleryEditLauncher.launch(GalleryActivity.newIntent(this, title, fileName, title.wikiSite, revision), options)\n        } else {\n            requestHandleIntentLauncher.launch(GalleryActivity.newIntent(this, title, fileName, title.wikiSite, revision), options)\n        }\n    }\n\n    override fun onPageRequestEditDescription(text: String?, title: PageTitle, sourceSummary: PageSummaryForEdit?,\n                                              targetSummary: PageSummaryForEdit?, action: DescriptionEditActivity.Action, invokeSource: InvokeSource) {\n        requestSuggestedEditsLauncher.launch(DescriptionEditActivity.newIntent(this, title, text, sourceSummary, targetSummary, action, invokeSource))\n    }\n\n    override fun onPageRequestAddImageTags(mwQueryPage: MwQueryPage, invokeSource: InvokeSource) {\n        requestSuggestedEditsLauncher.launch(SuggestedEditsImageTagEditActivity.newIntent(this, mwQueryPage, invokeSource))\n    }\n\n    override fun onLinkPreviewLoadPage(title: PageTitle, entry: HistoryEntry, inNewTab: Boolean) {\n        loadPage(title, entry, if (inNewTab) TabPosition.NEW_TAB_BACKGROUND else TabPosition.CURRENT_TAB)\n    }\n\n    private fun handleIntent(intent: Intent) {\n        if (intent.action == Intent.ACTION_MAIN && intent.categories?.contains(Intent.CATEGORY_LAUNCHER) == true) {\n            TestKitchenAdapter.client.getInstrument(\"apps-open\")\n                .submitInteraction(action = \"app_open\", actionSource = \"app_icon\")\n        }\n        if (Intent.ACTION_VIEW == intent.action && intent.data != null) {\n            var uri = intent.data!!\n\n            // Push back if the user is still in the Visual Editor flow.\n            uri.getQueryParameter(\"veaction\")?.let {\n                if (it == \"edit\") {\n                    val title = PageTitle.titleForUri(uri, WikiSite(uri))\n                    val sectionId = uri.getQueryParameter(\"section\")?.toIntOrNull() ?: 0\n                    // If the link is a VisualEditor edit link, then we should open it in an external browser.\n                    openVisualEditorInExternalBrowser(title, sectionId)\n                    return\n                }\n            }\n\n            TestKitchenAdapter.client.getInstrument(\"apps-open\")\n                .submitInteraction(action = \"app_open\", actionSource = \"external_link\")\n\n            if (uri.scheme == \"wikipedia\") {\n                uri = uri.buildUpon().scheme(WikiSite.DEFAULT_SCHEME).build()\n                uri.getQueryParameter(\"saved\")?.let {\n                    if (it == \"true\") {\n                        val revision = uri.getQueryParameter(\"revision\")?.toLongOrNull()\n                        if (revision != null && pageFragment.title != null) {\n                            lifecycleScope.launch(CoroutineExceptionHandler { _, t ->\n                                L.e(t)\n                            }) {\n                                EditSectionViewModel.retryUntilNewRevision(pageFragment.title!!, revision)\n                                pageFragment.refreshPage()\n                                FeedbackUtil.showMessage(this@PageActivity, R.string.edit_saved_successfully)\n                            }\n                        } else {\n                            binding.root.post {\n                                if (!isDestroyed) {\n                                    FeedbackUtil.showMessage(this, R.string.edit_saved_successfully)\n                                }\n                            }\n                        }\n                    } else {\n                        L.d(\"Edit abandoned.\")\n                    }\n                }\n            }\n\n            if (!ReleaseUtil.isPreBetaRelease && uri.scheme != null && uri.scheme == \"http\") {\n                // For external links, ensure that they're using https.\n                uri = uri.buildUpon().scheme(WikiSite.DEFAULT_SCHEME).build()\n            }\n            if (!Service.isWikimediaAuthority(uri.authority)) {\n                UriUtil.visitInExternalBrowser(this, uri)\n                finish()\n                return\n            }\n            val wiki = WikiSite(uri)\n            val title = PageTitle.titleForUri(uri, wiki)\n            val historyEntry = HistoryEntry(title, if (intent.hasExtra(Constants.INTENT_EXTRA_NOTIFICATION_ID))\n                HistoryEntry.SOURCE_NOTIFICATION_SYSTEM else HistoryEntry.SOURCE_EXTERNAL_LINK)\n            // Populate the referrer with the externally-referring URL, e.g. an external Browser URL, if present.\n            ActivityCompat.getReferrer(this)?.let { uri ->\n                historyEntry.referrer = uri.toString()\n            }\n            if (title.namespace() == Namespace.SPECIAL && title.prefixedText.startsWith(\"Special:ReadingLists\")) {\n                L.d(\"Received shareable reading lists\")\n                val encodedListFromParameter = uri.getQueryParameter(\"limport\")\n                Prefs.importReadingListsDialogShown = false\n                Prefs.receiveReadingListsData = encodedListFromParameter\n                startActivity(ReadingListActivity.newIntent(this, ReadingListMode.PREVIEW).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP))\n                finish()\n                return\n            }\n            // Special cases:\n            // If the subdomain of the URL is not a \"language\" subdomain as we expect, then\n            // bounce it out to an external browser. This can be links to the \"donate.\" or\n            // \"thankyou.\" subdomains, or the Wikiquote \"quote.\" subdomain, and possibly others.\n            val language = wiki.languageCode.lowercase(Locale.getDefault())\n            if (Constants.NON_LANGUAGE_SUBDOMAINS.contains(language) || (title.isSpecial && !title.isContributions)) {\n                // ...Except if the URL came as a result of a successful donation, in which case\n                // treat it differently:\n                if (language == \"thankyou\" && uri.getQueryParameter(\"order_id\") != null) {\n                    CampaignCollection.addDonationResult(fromWeb = true,\n                        amount = (uri.getQueryParameter(\"amount\"))?.toFloat() ?: 0f,\n                        currency = uri.getQueryParameter(\"currency\") ?: \"\",\n                        recurring = uri.getQueryParameter(\"recurring\") == \"1\")\n                    // Check if the donation started from the app, but completed via web, in which case\n                    // show it in a SingleWebViewActivity.\n                    val campaign = uri.getQueryParameter(\"wmf_campaign\")\n\n                    if (campaign != null && campaign == \"Android\") {\n                        var pageContentInfo = SingleWebViewActivity.PAGE_CONTENT_SOURCE_DONOR_EXPERIENCE\n                        YearInReviewViewModel.currentCampaignId?.let { campaignId ->\n                            TestKitchenAdapter.client.getInstrument(\"apps-year-in-review\")\n                                .submitInteraction(action = \"impression\", actionSource = \"webpay_processed\", actionContext = mapOf(\"campaign_id\" to campaignId))\n                            pageContentInfo = SingleWebViewActivity.PAGE_CONTENT_SOURCE_YIR\n                        } ?: run {\n                            DonorExperienceEvent.logAction(\"impression\", \"webpay_processed\", wiki.languageCode)\n                        }\n                        startActivity(SingleWebViewActivity.newIntent(this@PageActivity, uri.toString(),\n                            true, pageFragment.title, pageContentInfo))\n                        finish()\n                        return\n                    }\n                }\n                UriUtil.visitInExternalBrowser(this, uri)\n                finish()\n                return\n            }\n            loadPage(title, historyEntry, TabPosition.NEW_TAB_FOREGROUND)\n        } else if ((ACTION_LOAD_IN_NEW_TAB == intent.action || ACTION_LOAD_IN_CURRENT_TAB == intent.action ||\n                    ACTION_LOAD_IN_CURRENT_TAB_SQUASH == intent.action) && intent.hasExtra(EXTRA_HISTORYENTRY)) {\n            val title = intent.parcelableExtra<PageTitle>(Constants.ARG_TITLE)\n            val historyEntry = intent.parcelableExtra<HistoryEntry>(EXTRA_HISTORYENTRY)\n            cancelSemanticSearchFeedback(FeedbackSuppression.LEFT_ARTICLE)\n            if (title != null && intent.getBooleanExtra(EXTRA_SHOW_SEMANTIC_SEARCH_FEEDBACK, false)) {\n                semanticSearchFeedbackViewModel.setup(title,\n                    intent.getStringExtra(EXTRA_SEMANTIC_SEARCH_ID),\n                    intent.getSerializableExtra(EXTRA_SEMANTIC_SEARCH_FUNNEL) as Funnel?)\n            }\n            val highlightText = intent.getStringExtra(EXTRA_HIGHLIGHT_TEXT)\n            when (intent.action) {\n                ACTION_LOAD_IN_NEW_TAB -> loadPage(title, historyEntry, TabPosition.NEW_TAB_FOREGROUND)\n                ACTION_LOAD_IN_CURRENT_TAB -> loadPage(title, historyEntry, TabPosition.CURRENT_TAB, highlightText)\n                ACTION_LOAD_IN_CURRENT_TAB_SQUASH -> loadPage(title, historyEntry, TabPosition.CURRENT_TAB_SQUASH, highlightText)\n            }\n            intent.getStringExtra(Constants.INTENT_EXTRA_REVERT_QNUMBER)?.let {\n                showDescriptionEditRevertDialog(it)\n            }\n        } else if (ACTION_LOAD_FROM_EXISTING_TAB == intent.action && intent.hasExtra(EXTRA_HISTORYENTRY)) {\n            val title = intent.parcelableExtra<PageTitle>(Constants.ARG_TITLE)\n            val historyEntry = intent.parcelableExtra<HistoryEntry>(EXTRA_HISTORYENTRY)\n            loadPage(title, historyEntry, TabPosition.EXISTING_TAB)\n        } else if (ACTION_RESUME_READING == intent.action || intent.hasExtra(Constants.INTENT_APP_SHORTCUT_CONTINUE_READING)) {\n            loadFilePageFromBackStackIfNeeded()\n        } else if (Intent.ACTION_SEARCH == intent.action) {\n            val query = intent.getStringExtra(SearchManager.QUERY)\n            val title = PageTitle(query, app.wikiSite)\n            val historyEntry = HistoryEntry(title, HistoryEntry.SOURCE_SEARCH)\n            loadPage(title, historyEntry, TabPosition.EXISTING_TAB)\n        } else if (ACTION_CREATE_NEW_TAB == intent.action) {\n            loadMainPage(TabPosition.NEW_TAB_FOREGROUND)\n        } else {\n            loadMainPage(TabPosition.CURRENT_TAB)\n        }\n    }\n\n    /**\n     * Load a new page, and put it on top of the backstack, optionally allowing state loss of the\n     * fragment manager. Useful for when this function is called from an AsyncTask result.\n     * @param pageTitle Title of the page to load.\n     * @param entry HistoryEntry associated with this page.\n     * @param position Whether to open this page in the current tab, a new background tab, or new\n     * foreground tab.\n     * @param highlightText Text to highlight and scroll to once the page loads, only for the current tab.\n     */\n    private fun loadPage(pageTitle: PageTitle?, entry: HistoryEntry?, position: TabPosition, highlightText: String? = null) {\n        if (isDestroyed || pageTitle == null || entry == null) {\n            return\n        }\n        if (hasTransitionAnimation && !wasTransitionShown) {\n            binding.pageFragment.visibility = View.GONE\n            binding.wikiArticleCardView.prepareForTransition(pageTitle)\n            wasTransitionShown = true\n        }\n        if (loadNonArticlePageIfNeeded(pageTitle)) {\n            return\n        }\n\n        // Accessibility\n        title = getString(R.string.page_content_description, pageTitle.displayText)\n\n        binding.pageToolbarContainer.post {\n            if (!pageFragment.isAdded) {\n                return@post\n            }\n\n            // Close the link preview, if one is open.\n            hideLinkPreview()\n            onPageCloseActionMode()\n            when (position) {\n                TabPosition.CURRENT_TAB -> pageFragment.loadPage(pageTitle, entry, pushBackStack = true, squashBackstack = false, highlightText = highlightText)\n                TabPosition.CURRENT_TAB_SQUASH -> pageFragment.loadPage(pageTitle, entry, pushBackStack = true, squashBackstack = true, highlightText = highlightText)\n                TabPosition.NEW_TAB_BACKGROUND -> pageFragment.openInNewBackgroundTab(pageTitle, entry)\n                TabPosition.NEW_TAB_FOREGROUND -> pageFragment.openInNewForegroundTab(pageTitle, entry)\n                else -> pageFragment.openFromExistingTab(pageTitle, entry)\n            }\n            // Reusing an already-loaded page does not trigger onPageLoadComplete().\n            if (pageFragment.page != null && !pageFragment.isLoading) {\n                scheduleSemanticSearchFeedback()\n            }\n        }\n    }\n\n    private fun loadMainPage(position: TabPosition) {\n        val title = PageTitle(MainPageNameData.valueFor(app.appOrSystemLanguageCode), app.wikiSite)\n        val historyEntry = HistoryEntry(title, HistoryEntry.SOURCE_MAIN_PAGE)\n        loadPage(title, historyEntry, position)\n    }\n\n    private fun loadFilePageFromBackStackIfNeeded() {\n        if (pageFragment.currentTab.backStack.isNotEmpty()) {\n            val item = pageFragment.currentTab.backStack[pageFragment.currentTab.backStackPosition]\n            loadNonArticlePageIfNeeded(item.title)\n        }\n    }\n\n    private fun loadNonArticlePageIfNeeded(title: PageTitle?): Boolean {\n        if (title != null) {\n            if (title.isFilePage) {\n                startActivity(FilePageActivity.newIntent(this, title))\n                finish()\n                return true\n            } else if (title.namespace() === Namespace.USER_TALK || title.namespace() === Namespace.TALK) {\n                startActivity(TalkTopicsActivity.newIntent(this, title, InvokeSource.PAGE_ACTIVITY))\n                finish()\n                return true\n            } else if (title.isSpecial) {\n                if (title.isContributions) {\n                    title.displayText.split('/').lastOrNull()?.let {\n                        startActivity(UserContribListActivity.newIntent(this, it))\n                        finish()\n                        return true\n                    }\n                }\n                UriUtil.visitInExternalBrowser(this, title.uri.toUri())\n                finish()\n                return true\n            }\n        }\n        return false\n    }\n\n    private fun updateProgressBar(visible: Boolean) {\n        binding.pageProgressBar.visibility = if (visible) View.VISIBLE else View.GONE\n    }\n\n    private fun hideLinkPreview() {\n        ExclusiveBottomSheetPresenter.dismiss(supportFragmentManager)\n    }\n\n    private fun removeTransitionAnimState() {\n        if (binding.pageFragment.visibility != View.VISIBLE) {\n            binding.pageFragment.visibility = View.VISIBLE\n        }\n        if (binding.wikiArticleCardView.visibility != View.GONE) {\n            binding.wikiArticleCardView.postDelayed({ binding.wikiArticleCardView.visibility = View.GONE }, 250L)\n        }\n    }\n\n    private fun modifyMenu(mode: ActionMode) {\n        val menu = mode.menu\n\n        // Hide context items that are intended for showing in external apps.\n        menu.children.forEach {\n            if (it.title.toString().contains(getString(R.string.search_hint)) ||\n                (it.title.toString().contains(getString(R.string.menu_text_select_define)) && pageFragment.shareHandler.shouldEnableWiktionaryDialog())) {\n                it.isVisible = false\n            }\n        }\n        // Append our custom items to the context menu.\n        mode.menuInflater.inflate(R.menu.menu_text_select, menu)\n    }\n\n    private fun showDescriptionEditRevertDialog(qNumber: String) {\n        MaterialAlertDialogBuilder(this)\n            .setTitle(R.string.notification_reverted_title)\n            .setView(DescriptionEditRevertHelpView(this, qNumber))\n            .setPositiveButton(R.string.reverted_edit_dialog_ok_button_text, null)\n            .show()\n    }\n\n    private fun maybeShowThemeTooltip() {\n        if (!Prefs.showOneTimeCustomizeToolbarTooltip) {\n            return\n        }\n        enqueueTooltip {\n            FeedbackUtil.getTooltip(\n                this,\n                getString(R.string.theme_chooser_menu_item_short_tooltip),\n                arrowAnchorPadding = -DimenUtil.roundedDpToPx(7f),\n                topOrBottomMargin = 0,\n                aboveOrBelow = true,\n                autoDismiss = false,\n                showDismissButton = true\n            ).apply {\n                setOnBalloonDismissListener {\n                    Prefs.showOneTimeCustomizeToolbarTooltip = false\n                    isTooltipShowing = false\n                }\n                BreadCrumbLogEvent.logTooltipShown(this@PageActivity, binding.pageToolbarButtonShowOverflowMenu)\n                showAlignBottom(binding.pageToolbarButtonShowOverflowMenu)\n                setCurrentTooltip(this)\n                isTooltipShowing = true\n            }\n        }\n    }\n\n    private fun enqueueTooltip(runnable: Runnable) {\n        if (exclusiveTooltipRunnable != null) {\n            return\n        }\n        exclusiveTooltipRunnable = runnable\n        binding.pageToolbar.postDelayed({\n            exclusiveTooltipRunnable = null\n            if (isDestroyed) {\n                return@postDelayed\n            }\n            runnable.run()\n        }, 500)\n    }\n\n    fun animateTabsButton() {\n        toolbarHideHandler.ensureDisplayed()\n        binding.pageToolbarButtonTabs.updateTabCount(true)\n    }\n\n    private fun updateNotificationsButton(animate: Boolean) {\n        if (AccountUtil.isLoggedIn) {\n            binding.pageToolbarButtonNotifications.isVisible = true\n            if (Prefs.notificationUnreadCount > 0) {\n                binding.pageToolbarButtonNotifications.setUnreadCount(Prefs.notificationUnreadCount)\n                if (animate) {\n                    toolbarHideHandler.ensureDisplayed()\n                    binding.pageToolbarButtonNotifications.runAnimation()\n                }\n            } else {\n                binding.pageToolbarButtonNotifications.setUnreadCount(0)\n            }\n        } else if (!AccountUtil.isLoggedIn && AnonymousNotificationHelper.isWithinAnonNotificationTime()) {\n            binding.pageToolbarButtonNotifications.isVisible = true\n            if (Prefs.hasAnonymousNotification) {\n                binding.pageToolbarButtonNotifications.setUnreadCount(1)\n                if (animate) {\n                    toolbarHideHandler.ensureDisplayed()\n                    binding.pageToolbarButtonNotifications.runAnimation()\n                }\n            } else {\n                binding.pageToolbarButtonNotifications.setUnreadCount(0)\n            }\n        } else {\n            binding.pageToolbarButtonNotifications.isVisible = false\n        }\n    }\n\n    fun clearActionBarTitle() {\n        supportActionBar?.title = \"\"\n    }\n\n    fun getToolbarMargin(): Int {\n        return binding.pageToolbarContainer.height\n    }\n\n    fun getOverflowMenu(): View {\n        return binding.pageToolbarButtonShowOverflowMenu\n    }\n\n    override fun onUnreadNotification() {\n        updateNotificationsButton(true)\n    }\n\n    fun onAnonNotification() {\n        updateNotificationsButton(true)\n    }\n\n    fun updateSearchHint() {\n        binding.pageToolbarButtonSearch.text = getString(R.string.search_hint)\n    }\n\n    override fun onProvideAssistContent(outContent: AssistContent) {\n        super.onProvideAssistContent(outContent)\n        pageFragment.model.title?.let {\n            outContent.webUri = it.uri.toUri()\n        }\n    }\n\n    companion object {\n        private const val LANGUAGE_CODE_BUNDLE_KEY = \"language\"\n        private const val EXCEPTION_MESSAGE_WEBVIEW = \"webview\"\n        const val ACTION_LOAD_IN_NEW_TAB = \"org.wikipedia.load_in_new_tab\"\n        const val ACTION_LOAD_IN_CURRENT_TAB = \"org.wikipedia.load_in_current_tab\"\n        const val ACTION_LOAD_IN_CURRENT_TAB_SQUASH = \"org.wikipedia.load_in_current_tab_squash\"\n        const val ACTION_LOAD_FROM_EXISTING_TAB = \"org.wikipedia.load_from_existing_tab\"\n        const val ACTION_CREATE_NEW_TAB = \"org.wikipedia.create_new_tab\"\n        const val ACTION_RESUME_READING = \"org.wikipedia.resume_reading\"\n        const val EXTRA_HISTORYENTRY = \"org.wikipedia.history.historyentry\"\n        const val EXTRA_SHOW_SEMANTIC_SEARCH_FEEDBACK = \"org.wikipedia.search.semantic.show_feedback\"\n        const val EXTRA_SEMANTIC_SEARCH_ID = \"org.wikipedia.search.semantic.search_id\"\n        const val EXTRA_SEMANTIC_SEARCH_FUNNEL = \"org.wikipedia.search.semantic.funnel\"\n        const val EXTRA_HIGHLIGHT_TEXT = \"org.wikipedia.page.highlight_text\"\n\n        fun newIntent(context: Context): Intent {\n            return Intent(ACTION_RESUME_READING).setClass(context, PageActivity::class.java)\n        }\n\n        fun newIntentForNewTab(context: Context): Intent {\n            return Intent(ACTION_CREATE_NEW_TAB).setClass(context, PageActivity::class.java)\n        }\n\n        fun newIntentForNewTab(context: Context, entry: HistoryEntry, title: PageTitle): Intent {\n            return Intent(ACTION_LOAD_IN_NEW_TAB)\n                .setClass(context, PageActivity::class.java)\n                .putExtra(EXTRA_HISTORYENTRY, entry)\n                .putExtra(Constants.ARG_TITLE, title)\n        }\n\n        fun newIntentForCurrentTab(context: Context, entry: HistoryEntry, title: PageTitle, squashBackstack: Boolean = true): Intent {\n            return Intent(if (squashBackstack) ACTION_LOAD_IN_CURRENT_TAB_SQUASH else ACTION_LOAD_IN_CURRENT_TAB)\n                .setClass(context, PageActivity::class.java)\n                .putExtra(EXTRA_HISTORYENTRY, entry)\n                .putExtra(Constants.ARG_TITLE, title)\n        }\n\n        fun newIntentForExistingTab(context: Context, entry: HistoryEntry, title: PageTitle): Intent {\n            return Intent(ACTION_LOAD_FROM_EXISTING_TAB)\n                .setClass(context, PageActivity::class.java)\n                .putExtra(EXTRA_HISTORYENTRY, entry)\n                .putExtra(Constants.ARG_TITLE, title)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/page/PageActivity.kt","kind":"class","line":112,"members":{"ACTION_CREATE_NEW_TAB":[1000,1000],"ACTION_LOAD_FROM_EXISTING_TAB":[999,999],"ACTION_LOAD_IN_CURRENT_TAB":[997,997],"ACTION_LOAD_IN_CURRENT_TAB_SQUASH":[998,998],"ACTION_LOAD_IN_NEW_TAB":[996,996],"ACTION_RESUME_READING":[1001,1001],"EXCEPTION_MESSAGE_WEBVIEW":[995,995],"EXTRA_HIGHLIGHT_TEXT":[1006,1006],"EXTRA_HISTORYENTRY":[1002,1002],"EXTRA_SEMANTIC_SEARCH_FUNNEL":[1005,1005],"EXTRA_SEMANTIC_SEARCH_ID":[1004,1004],"EXTRA_SHOW_SEMANTIC_SEARCH_FEEDBACK":[1003,1003],"LANGUAGE_CODE_BUNDLE_KEY":[994,994],"TabPosition":[114,116],"animateTabsButton":[929,932],"app":[121,121],"binding":[118,118],"cancelSemanticSearchFeedback":[491,499],"clearActionBarTitle":[962,964],"currentActionModes":[124,124],"enqueueTooltip":[915,927],"exclusiveTooltipRunnable":[126,126],"getOverflowMenu":[970,972],"getToolbarMargin":[966,968],"handleIntent":[616,762],"hasTransitionAnimation":[122,122],"hideLinkPreview":[854,856],"isCabOpen":[125,125],"isTooltipShowing":[127,127],"loadFilePageFromBackStackIfNeeded":[817,822],"loadMainPage":[811,815],"loadNonArticlePageIfNeeded":[824,848],"loadPage":[764,809],"maybeShowThemeTooltip":[889,913],"modifyMenu":[867,879],"newIntent":[1008,1010],"newIntentForCurrentTab":[1023,1028],"newIntentForExistingTab":[1030,1035],"newIntentForNewTab":[1012,1014],"onActionModeFinished":[384,387],"onActionModeStarted":[374,382],"onAnonNotification":[978,980],"onBackPressedCallback":[410,432],"onCreate":[201,315],"onDestroy":[389,398],"onKeyDown":[434,440],"onLinkPreviewLoadPage":[612,614],"onNavMenuSwipeRequest":[442,447],"onNewIntent":[400,404],"onOptionsItemSelected":[342,353],"onPageCloseActionMode":[558,564],"onPageDismissBottomSheet":[508,510],"onPageHideSoftKeyboard":[536,538],"onPageInitWebView":[512,514],"onPageLoadComplete":[449,457],"onPageLoadError":[544,548],"onPageLoadErrorBackPressed":[550,552],"onPageLoadMainPageInForegroundTab":[524,526],"onPageLoadPage":[516,518],"onPageRequestAddImageTags":[608,610],"onPageRequestEditDescription":[603,606],"onPageRequestEditSection":[566,584],"onPageRequestGallery":[595,601],"onPageRequestLangLinks":[591,593],"onPageSetToolbarElevationEnabled":[554,556],"onPageShowLinkPreview":[520,522],"onPageStartSupportActionMode":[532,534],"onPageUpdateProgressBar":[528,530],"onPageWatchlistExpirySelect":[540,542],"onPause":[362,367],"onPrepareOptionsMenu":[335,340],"onProvideAssistContent":[986,991],"onResume":[355,360],"onSaveInstanceState":[369,372],"onStart":[317,333],"onUnreadNotification":[974,976],"openVisualEditorInExternalBrowser":[586,589],"pageFragment":[120,120],"removeTransitionAnimState":[858,865],"requestBrowseTabLauncher":[161,173],"requestEditSectionLauncher":[131,145],"requestGalleryEditLauncher":[155,159],"requestHandleIntentLauncher":[147,153],"requestSuggestedEditsLauncher":[175,199],"scheduleSemanticSearchFeedback":[459,489],"semanticSearchFeedbackJob":[129,129],"semanticSearchFeedbackViewModel":[128,128],"showDescriptionEditRevertDialog":[881,887],"submitSemanticSearchFeedbackSuppressed":[501,506],"toolbarHideHandler":[119,119],"updateForLoginState":[406,408],"updateNotificationsButton":[934,960],"updateProgressBar":[850,852],"updateSearchHint":[982,984],"wasTransitionShown":[123,123]},"shot":"shots/code/PageActivity.jpg","supers":["BaseActivity()","PageFragment.Callback","LinkPreviewDialog.LoadPageCallback","FrameLayoutNavMenuTriggerer.Callback"]},"PersonalizationActivity":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["launch","h-classes","Logic \u00b7 class diagram"],["launch","h-sequence","First launch \u00b7 sequence"]],"code":"class PersonalizationActivity : BaseActivity() {\n\n    private val viewModel: PersonalizationViewModel by viewModels { PersonalizationViewModel.Factory }\n\n    private val searchLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == SearchActivity.RESULT_LINK_SUCCESS) {\n            val pageTitle = it.data?.parcelableExtra<PageTitle>(SearchActivity.EXTRA_RETURN_LINK_TITLE) ?: return@registerForActivityResult\n            viewModel.addArticleFromSearch(pageTitle)\n        }\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n\n        _instrument = TestKitchenAdapter.client.getInstrument(\"apps-home-feed\")\n            .setDefaultActionSource(\"feed_customize\")\n            .startFunnel(\"feed_customize\")\n\n        val showInterestsOnly = intent?.getBooleanExtra(EXTRA_SHOW_INTERESTS_ONLY, false) ?: false\n\n        val pages = if (showInterestsOnly) {\n            listOf(\n                PersonalizationPage.INTERESTS\n            )\n        } else {\n            listOf(\n                PersonalizationPage.CURIOSITY,\n                PersonalizationPage.INTERESTS,\n                PersonalizationPage.HOME_PREFERENCE\n            )\n        }\n\n        setContent {\n            BaseTheme {\n                PersonalizationScreen(\n                    viewModel = viewModel,\n                    screens = pages,\n                    onSkipClick = { finish() },\n                    onSearchClick = {\n                        val intent = SearchActivity.newIntent(this, Constants.InvokeSource.FEED_INTEREST_SELECTION, null, returnLink = true)\n                        searchLauncher.launch(intent)\n                    },\n                    onCompleteOnboardingClick = {\n                        if (showInterestsOnly) {\n                            onFinish()\n                            return@PersonalizationScreen\n                        }\n\n                        startActivity(ExploreFeedBuildingActivity.newIntent(this))\n                        setResult(RESULT_OK)\n                        finish()\n                    },\n                    onBackButtonClick = if (showInterestsOnly) ({\n                        onFinish()\n                    }) else null\n                )\n            }\n        }\n    }\n\n    private fun onFinish() {\n        setResult(if (viewModel.interestsUpdated) RESULT_INTERESTS_UPDATED else RESULT_OK)\n        finish()\n    }\n\n    companion object {\n        const val EXTRA_SHOW_INTERESTS_ONLY = \"show_interests_only\"\n        const val RESULT_INTERESTS_UPDATED = 100\n\n        fun newIntent(context: Context, showInterestsOnly: Boolean = false): Intent {\n            return Intent(context, PersonalizationActivity::class.java)\n                .putExtra(EXTRA_SHOW_INTERESTS_ONLY, showInterestsOnly)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/personalization/PersonalizationActivity.kt","kind":"class","line":18,"members":{"EXTRA_SHOW_INTERESTS_ONLY":[84,84],"RESULT_INTERESTS_UPDATED":[85,85],"newIntent":[87,90],"onCreate":[29,76],"onFinish":[78,81],"searchLauncher":[22,27],"viewModel":[20,20]},"shot":"shots/code/PersonalizationActivity.jpg","supers":["BaseActivity()"]},"PlacesActivity":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["places","h-classes","Logic \u00b7 class diagram"]],"code":"class PlacesActivity : SingleFragmentActivity<PlacesFragment>() {\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        disableFitsSystemWindows()\n    }\n\n    public override fun createFragment(): PlacesFragment {\n        return PlacesFragment.newInstance(intent.parcelableExtra(Constants.ARG_TITLE), intent.parcelableExtra(EXTRA_LOCATION))\n    }\n\n    companion object {\n        const val EXTRA_LOCATION = \"location\"\n        fun newIntent(context: Context, pageTitle: PageTitle? = null, location: Location? = null): Intent {\n            return Intent(context, PlacesActivity::class.java)\n                .putExtra(Constants.ARG_TITLE, pageTitle)\n                .putExtra(EXTRA_LOCATION, location)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/places/PlacesActivity.kt","kind":"class","line":12,"members":{"EXTRA_LOCATION":[24,24],"createFragment":[19,21],"newIntent":[25,29],"onCreate":[14,17]},"shot":"shots/code/PlacesActivity.jpg","supers":["SingleFragmentActivity<PlacesFragment>()"]},"ReadingListActivity":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"]],"code":"class ReadingListActivity : SingleFragmentActivity<ReadingListFragment>(), BaseActivity.Callback {\n\n    private var readingListMode: ReadingListMode = ReadingListMode.DEFAULT\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        updateStatusBarColor(false)\n        val listTitle = intent.getStringExtra(EXTRA_READING_LIST_TITLE)\n        title = getString(R.string.reading_list_activity_title, listTitle)\n        onBackPressedDispatcher.addCallback(this, onBackPressedCallback)\n        callback = this\n    }\n\n    public override fun createFragment(): ReadingListFragment {\n        readingListMode = (intent.getSerializableExtra(EXTRA_READING_LIST_MODE) as ReadingListMode?) ?: ReadingListMode.DEFAULT\n        return if (readingListMode != ReadingListMode.DEFAULT) {\n            val invokeSource = intent.getSerializableExtra(Constants.INTENT_EXTRA_INVOKE_SOURCE) as InvokeSource?\n            ReadingListFragment.newInstance(readingListMode, invokeSource)\n        } else {\n            ReadingListFragment.newInstance(intent.getLongExtra(EXTRA_READING_LIST_ID, 0))\n        }\n    }\n\n    fun updateStatusBarColor(inActionMode: Boolean) {\n        setStatusBarColor(if (!inActionMode) Color.TRANSPARENT else ResourceUtil.getThemedColor(this, R.attr.paper_color))\n    }\n\n    fun updateNavigationBarColor() {\n        setNavigationBarColor(ResourceUtil.getThemedColor(this, R.attr.paper_color))\n    }\n\n    private val onBackPressedCallback = object : OnBackPressedCallback(true) {\n        override fun handleOnBackPressed() {\n            if (readingListMode == ReadingListMode.DEFAULT) {\n                ReadingListsAnalyticsHelper.logReceiveCancel(this@ReadingListActivity, fragment.readingList)\n            }\n            if (!WikipediaApp.instance.haveMainActivity) {\n                startActivity(MainActivity.newIntent(this@ReadingListActivity)\n                    .addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP)\n                    .putExtra(Constants.INTENT_RETURN_TO_MAIN, true)\n                    .putExtra(Constants.INTENT_EXTRA_GO_TO_MAIN_TAB, NavTab.READING_LISTS.code())\n                )\n            }\n            finish()\n        }\n    }\n\n    override fun onPermissionResult(activity: BaseActivity, isGranted: Boolean) {\n        if (isGranted) {\n            Prefs.isRecommendedReadingListNotificationEnabled = true\n            RecommendedReadingListNotificationManager.scheduleRecommendedReadingListNotification(this)\n        } else {\n            Prefs.isRecommendedReadingListNotificationEnabled = false\n        }\n        fragment.updateNotificationIcon()\n    }\n\n    companion object {\n        private const val EXTRA_READING_LIST_TITLE = \"readingListTitle\"\n        const val EXTRA_READING_LIST_ID = \"readingListId\"\n        const val EXTRA_READING_LIST_MODE = \"readingListMode\"\n\n        fun newIntent(context: Context, list: ReadingList): Intent {\n            return Intent(context, ReadingListActivity::class.java)\n                    .putExtra(EXTRA_READING_LIST_TITLE, list.title)\n                    .putExtra(EXTRA_READING_LIST_ID, list.id)\n        }\n\n        fun newIntent(context: Context, readingListMode: ReadingListMode, invokeSource: InvokeSource? = null, notificationCategory: NotificationCategory? = null): Intent {\n            return Intent(context, ReadingListActivity::class.java)\n                .putExtra(EXTRA_READING_LIST_MODE, readingListMode)\n                .putExtra(Constants.INTENT_EXTRA_INVOKE_SOURCE, invokeSource)\n                .putExtra(Constants.INTENT_EXTRA_NOTIFICATION_CATEGORY, notificationCategory)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/ReadingListActivity.kt","kind":"class","line":23,"members":{"EXTRA_READING_LIST_ID":[82,82],"EXTRA_READING_LIST_MODE":[83,83],"EXTRA_READING_LIST_TITLE":[81,81],"createFragment":[36,44],"newIntent":[85,89],"onBackPressedCallback":[54,68],"onCreate":[27,34],"onPermissionResult":[70,78],"readingListMode":[25,25],"updateNavigationBarColor":[50,52],"updateStatusBarColor":[46,48]},"supers":["SingleFragmentActivity<ReadingListFragment>()","BaseActivity.Callback"]},"ReadingListSyncAdapter":{"appearsIn":[["index","h-services","Services \u00b7 what the screens share"],["saved","h-classes","Logic \u00b7 class diagram"],["saved","h-sequence","Save an article and sync it \u00b7 sequence"]],"code":"class ReadingListSyncAdapter(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {\n\n    override suspend fun doWork(): Result {\n        return withContext(Dispatchers.IO) {\n            val extras = getBooleanExtraFromData(inputData)\n            if (RemoteConfig.config.disableReadingListSync || !AccountUtil.isLoggedIn || AccountUtil.isTemporaryAccount ||\n                !(Prefs.isReadingListSyncEnabled || Prefs.isReadingListsRemoteDeletePending)) {\n                L.d(\"Skipping sync of reading lists.\")\n                if (extras.containsKey(SYNC_EXTRAS_REFRESHING)) {\n                    SavedPageSyncService.sendSyncEvent()\n                }\n                return@withContext Result.success()\n            }\n            L.d(\"Begin sync of reading lists...\")\n            val listIdsDeleted = Prefs.readingListsDeletedIds.toMutableSet()\n            val pageIdsDeleted = Prefs.readingListPagesDeletedIds.toMutableSet()\n            var allLocalLists: MutableList<ReadingList>? = null\n            val wiki = WikipediaApp.instance.wikiSite\n            val client = ReadingListClient(wiki)\n            val readingListSyncNotification = ReadingListSyncNotification.instance\n            val lastSyncTime = Prefs.readingListsLastSyncTime.orEmpty()\n            var shouldSendSyncEvent = extras.containsKey(SYNC_EXTRAS_REFRESHING)\n            var shouldRetry = false\n            var shouldRetryWithForce = false\n            try {\n                IN_PROGRESS = true\n                var syncEverything = false\n                if (extras.containsKey(SYNC_EXTRAS_FORCE_FULL_SYNC) ||\n                    Prefs.isReadingListsRemoteDeletePending ||\n                    Prefs.isReadingListsRemoteSetupPending) {\n                    // reset the remote ID on all lists, since they will need to be recreated next time.\n                    L.d(\"Resetting all lists to un-synced.\")\n                    syncEverything = true\n                    AppDatabase.instance.readingListDao().markAllListsUnsynced()\n                    AppDatabase.instance.readingListPageDao().markAllPagesUnsynced()\n                    allLocalLists = AppDatabase.instance.readingListDao().getAllLists().toMutableList()\n                }\n\n                val csrfToken = CsrfTokenClient.getToken(wiki)\n\n                if (Prefs.isReadingListsRemoteDeletePending) {\n                    // Are we scheduled for a teardown? If so, delete everything and bail.\n                    L.d(\"Tearing down remote lists...\")\n                    client.tearDown(csrfToken)\n                    Prefs.isReadingListsRemoteDeletePending = false\n                    return@withContext Result.success()\n                } else if (Prefs.isReadingListsRemoteSetupPending) {\n                    // ...Or are we scheduled for setup?\n                    client.setup(csrfToken)\n                    Prefs.isReadingListsRemoteSetupPending = false\n                }\n\n                // -----------------------------------------------\n                // PHASE 1: Sync from remote to local.\n                // -----------------------------------------------\n                var remoteListsModified = mutableListOf<RemoteReadingList>()\n                var remoteEntriesModified = mutableListOf<RemoteReadingListEntry>()\n                if (lastSyncTime.isEmpty()) {\n                    syncEverything = true\n                }\n\n                if (!syncEverything) {\n                    try {\n                        L.d(\"Fetching changes from server, since $lastSyncTime\")\n                        val allChanges = client.getChangesSince(lastSyncTime)\n                        allChanges.lists?.let {\n                            remoteListsModified = it as MutableList<RemoteReadingList>\n                        }\n                        allChanges.entries?.let {\n                            remoteEntriesModified = it as MutableList<RemoteReadingListEntry>\n                        }\n                    } catch (t: Throwable) {\n                        if (client.isErrorType(t, \"too-old\")) {\n                            // If too much time has elapsed between syncs, then perform a full sync.\n                            syncEverything = true\n                        } else {\n                            throw t\n                        }\n                    }\n                }\n\n                if (allLocalLists == null) {\n                    allLocalLists = if (syncEverything) {\n                        AppDatabase.instance.readingListDao().getAllLists().toMutableList()\n                    } else {\n                        AppDatabase.instance.readingListDao().getAllListsWithUnsyncedPages().toMutableList()\n                    }\n                }\n\n                        // Perform a quick check for whether we'll need to sync all lists\n                for (remoteEntry in remoteEntriesModified) {\n                    // find the list to which this entry belongs...\n                    val eigenLocalList = allLocalLists.find { it.remoteId == remoteEntry.listId }\n                    val eigenRemoteList = remoteListsModified.find { it.id == remoteEntry.listId }\n\n                    if (eigenLocalList == null && eigenRemoteList == null) {\n                        L.w(\"Remote entry belongs to an unknown local list. Falling back to full sync.\")\n                        syncEverything = true\n                        break\n                    }\n                }\n                if (syncEverything) {\n                    allLocalLists = AppDatabase.instance.readingListDao().getAllLists().toMutableList()\n                    L.d(\"Fetching all lists from server...\")\n                    remoteListsModified = client.allLists as MutableList<RemoteReadingList>\n                }\n\n                // Notify any event consumers that reading lists are, in fact, enabled.\n                FlowEventBus.post(ReadingListsEnabledStatusEvent())\n\n                // setup syncing indicator for remote to local\n                val remoteItemsTotal = remoteListsModified.size\n\n                // First, update our list hierarchy to match the remote hierarchy.\n                for ((remoteItemsSynced, remoteList) in remoteListsModified.withIndex()) {\n                    readingListSyncNotification.setNotificationProgress(applicationContext, remoteItemsTotal, remoteItemsSynced)\n                    // Find the remote list in our local lists...\n                    var localList: ReadingList? = null\n                    var upsertNeeded = false\n                    for (list in allLocalLists) {\n                        if (list.isDefault && remoteList.isDefault) {\n                            localList = list\n                            if (list.remoteId != remoteList.id) {\n                                list.remoteId = remoteList.id\n                                upsertNeeded = true\n                            }\n                            break\n                        }\n                        if (list.remoteId == remoteList.id) {\n                            localList = list\n                            break\n                        } else if (StringUtil.normalizedEquals(list.title, remoteList.name())) {\n                            localList = list\n                            localList.remoteId = remoteList.id\n                            upsertNeeded = true\n                            break\n                        }\n                    }\n                    if (remoteList.isDefault && localList != null && !localList.isDefault) {\n                        L.logRemoteError(RuntimeException(\"Unexpected: remote default list corresponds to local non-default list.\"))\n                        localList = AppDatabase.instance.readingListDao().getDefaultList()\n                    }\n                    if (remoteList.isDeleted) {\n                        if (localList != null && !localList.isDefault) {\n                            L.d(\"Deleting local list \" + localList.title)\n                            AppDatabase.instance.readingListDao().deleteList(localList, false)\n                            AppDatabase.instance.readingListPageDao().markPagesForDeletion(localList, localList.pages, false)\n                            allLocalLists.remove(localList)\n                            shouldSendSyncEvent = true\n                        }\n                        continue\n                    }\n                    if (localList == null) {\n                        // A new list needs to be created locally.\n                        L.d(\"Creating local list \" + remoteList.name())\n                        localList = if (remoteList.isDefault) {\n                            L.logRemoteError(RuntimeException(\"Unexpected: local default list no longer matches remote.\"))\n                            AppDatabase.instance.readingListDao().getDefaultList()\n                        } else {\n                            AppDatabase.instance.readingListDao().createList(remoteList.name(), remoteList.description())\n                        }\n                        localList.remoteId = remoteList.id\n                        localList.atime = remoteList.created.toInstant(ZoneOffset.UTC).toEpochMilli()\n                        localList.mtime = remoteList.updated.toInstant(ZoneOffset.UTC).toEpochMilli()\n                        allLocalLists.add(localList)\n                        upsertNeeded = true\n                    } else {\n                        if (!localList.isDefault && !StringUtil.normalizedEquals(localList.title, remoteList.name())) {\n                            localList.title = remoteList.name()\n                            upsertNeeded = true\n                        }\n                        if (!localList.isDefault && !StringUtil.normalizedEquals(localList.description, remoteList.description())) {\n                            localList.description = remoteList.description()\n                            upsertNeeded = true\n                        }\n                    }\n                    if (upsertNeeded) {\n                        L.d(\"Updating info for local list \" + localList.title)\n                        localList.dirty = false\n                        AppDatabase.instance.readingListDao().updateList(localList, false)\n                        shouldSendSyncEvent = true\n                    }\n                    if (syncEverything) {\n                        L.d(\"Fetching all pages in remote list \" + remoteList.name())\n                        client.getListEntries(remoteList.id).forEach {\n                            // TODO: optimization opportunity -- create/update local pages in bulk.\n                            createOrUpdatePage(localList, it)\n                        }\n                        shouldSendSyncEvent = true\n                    }\n                }\n                if (!syncEverything) {\n                    for (remoteEntry in remoteEntriesModified) {\n                        // find the list to which this entry belongs...\n                        val eigenList = allLocalLists.find { it.remoteId == remoteEntry.listId }\n                        if (eigenList == null) {\n                            L.w(\"Remote entry belongs to an unknown local list.\")\n                            continue\n                        }\n                        shouldSendSyncEvent = true\n                        if (remoteEntry.isDeleted) {\n                            deletePageByTitle(eigenList, pageTitleFromRemoteEntry(remoteEntry))\n                        } else {\n                            createOrUpdatePage(eigenList, remoteEntry)\n                        }\n                    }\n                }\n\n                // -----------------------------------------------\n                // PHASE 2: Sync from local to remote.\n                // -----------------------------------------------\n\n                // Do any remote lists need to be deleted?\n                val listIdsToDelete = mutableListOf<Long>()\n                listIdsToDelete.addAll(listIdsDeleted)\n                for (id in listIdsToDelete) {\n                    L.d(\"Deleting remote list id $id\")\n                    try {\n                        client.deleteList(csrfToken, id)\n                    } catch (t: Throwable) {\n                        L.w(t)\n                        if (!client.isServiceError(t) && !client.isUnavailableError(t)) {\n                            throw t\n                        }\n                    }\n                    listIdsDeleted.remove(id)\n                }\n\n                // Do any remote pages need to be deleted?\n                val pageIdsToDelete = pageIdsDeleted.toMutableSet()\n\n                // Determine if any articles need to be de-duplicated (because of bugs in previous sync inconsistencies)\n                if (syncEverything) {\n                    allLocalLists.forEach { list ->\n                        val distinct = list.pages.distinctBy { pageTitleFromRemoteEntry(remoteEntryFromLocalPage(it)) }\n                        val toRemove = list.pages.toMutableSet()\n                        toRemove.removeAll(distinct.toSet())\n                        if (toRemove.isNotEmpty()) {\n                            toRemove.forEach {\n                                AppDatabase.instance.readingListPageDao().deleteReadingListPage(it)\n                            }\n                            pageIdsToDelete.addAll(createIdsForDeletion(list, toRemove))\n                        }\n                    }\n                }\n\n                for (id in pageIdsToDelete) {\n                    L.d(\"Deleting remote page id $id\")\n                    val listAndPageId = id.split(\":\").toTypedArray()\n                    try {\n                        // TODO: optimization opportunity once server starts supporting batch deletes.\n                        client.deletePageFromList(csrfToken, listAndPageId[0].toLong(), listAndPageId[1].toLong())\n                    } catch (t: Throwable) {\n                        L.w(t)\n                        if (!client.isServiceError(t) && !client.isUnavailableError(t)) {\n                            throw t\n                        }\n                    }\n                    pageIdsDeleted.remove(id)\n                }\n\n                // setup syncing indicator for local to remote\n                val localItemsTotal = allLocalLists.size\n\n                // Determine whether any remote lists need to be created or updated\n                for ((localItemsSynced, localList) in allLocalLists.withIndex()) {\n                    readingListSyncNotification.setNotificationProgress(applicationContext, localItemsTotal, localItemsSynced)\n                    val remoteList = RemoteReadingList(name = localList.title, description = localList.description)\n                    var upsertNeeded = false\n                    if (localList.remoteId > 0) {\n                        if (!localList.isDefault && localList.dirty) {\n                            // Update remote metadata for this list.\n                            L.d(\"Updating info for remote list \" + remoteList.name())\n                            client.updateList(csrfToken, localList.remoteId, remoteList)\n                            upsertNeeded = true\n                        }\n                    } else if (!localList.isDefault) {\n                        // This list needs to be created remotely.\n                        L.d(\"Creating remote list \" + remoteList.name())\n                        val id = client.createList(csrfToken, remoteList)\n                        localList.remoteId = id\n                        upsertNeeded = true\n                    }\n                    if (upsertNeeded) {\n                        localList.dirty = false\n                        AppDatabase.instance.readingListDao().updateList(localList, false)\n                    }\n                }\n                for (localList in allLocalLists) {\n                    val localPages = localList.pages.filter { it.remoteId < 1 }\n                    val newEntries = localPages.map { remoteEntryFromLocalPage(it) }\n                    // Note: newEntries.size() is guaranteed to be equal to localPages.size()\n                    if (newEntries.isEmpty()) {\n                        continue\n                    }\n                    var tryOneAtATime = false\n                    try {\n                        if (localPages.size == 1) {\n                            L.d(\"Creating new remote page \" + localPages[0].displayTitle)\n                            localPages[0].remoteId = client.addPageToList(csrfToken, localList.remoteId, newEntries[0])\n                            AppDatabase.instance.readingListPageDao().updateReadingListPage(localPages[0])\n                        } else {\n                            L.d(\"Creating \" + newEntries.size + \" new remote pages\")\n                            val ids = client.addPagesToList(csrfToken, localList.remoteId, newEntries)\n                            for (i in ids.indices) {\n                                localPages[i].remoteId = ids[i]\n                            }\n                            AppDatabase.instance.readingListPageDao().updateReadingListPages(localPages)\n                        }\n                    } catch (t: Throwable) {\n                        // TODO: optimization opportunity -- if the server can return the ID\n                        // of the existing page(s), then we wouldn't need to do a hard sync.\n\n                        // If the page already exists in the remote list, this means that\n                        // the contents of this list have diverged from the remote list,\n                        // so let's force a full sync.\n                        if (client.isErrorType(t, \"duplicate-page\")) {\n                            shouldRetryWithForce = true\n                            break\n                        } else if (client.isErrorType(t, \"entry-limit\")) {\n                            // TODO: handle more meaningfully than ignoring, for now.\n                        } else if (client.isErrorType(t, \"no-such-project\")) {\n                            // Something is malformed in the page domain, but we don't know which page\n                            // in the batch caused the error. Therefore, let's retry uploading the pages\n                            // one at a time, and single out the one that fails.\n                            tryOneAtATime = true\n                        } else {\n                            throw t\n                        }\n                    }\n                    if (tryOneAtATime) {\n                        for (i in localPages.indices) {\n                            val localPage = localPages[i]\n                            try {\n                                L.d(\"Creating new remote page \" + localPage.displayTitle)\n                                localPage.remoteId = client.addPageToList(csrfToken, localList.remoteId, newEntries[i])\n                            } catch (t: Throwable) {\n                                if (client.isErrorType(t, \"duplicate-page\")) {\n                                    shouldRetryWithForce = true\n                                    break\n                                } else if (client.isErrorType(t, \"entry-limit\")) {\n                                    // TODO: handle more meaningfully than ignoring, for now.\n                                } else if (client.isErrorType(t, \"no-such-project\")) {\n                                    // Ignore the error, and give this malformed page a bogus remoteID,\n                                    // so that we won't try syncing it again.\n                                    localPage.remoteId = Int.MAX_VALUE.toLong()\n                                    // ...and also log it:\n                                    L.logRemoteError(RuntimeException(\"Attempted to sync malformed page: ${localPage.wiki}, ${localPage.displayTitle}\"))\n                                } else {\n                                    throw t\n                                }\n                            }\n                        }\n                        AppDatabase.instance.readingListPageDao().updateReadingListPages(localPages)\n                    }\n                }\n            } catch (e: CancellationException) {\n                throw e\n            } catch (t: Throwable) {\n                var errorMsg = t\n                if (client.isErrorType(t, \"not-set-up\")) {\n                    Prefs.isReadingListSyncEnabled = false\n                    if (lastSyncTime.isEmpty()) {\n                        // This means that it's our first time attempting to sync, and we see that\n                        // syncing isn't enabled on the server. So, let's prompt the user to enable it:\n                        FlowEventBus.post(ReadingListsEnableDialogEvent())\n                    } else {\n                        // This can only mean that our reading lists have been torn down (disabled) by\n                        // another client, so we need to notify the user of this development.\n                        FlowEventBus.post(ReadingListsNoLongerSyncedEvent())\n                    }\n                }\n                if (client.isErrorType(t, \"notloggedin\")) {\n                    try {\n                        L.d(\"Server doesn't believe we're logged in, so logging in...\")\n                        CsrfTokenClient.getToken(wiki)\n                        shouldRetry = true\n                    } catch (caught: Throwable) {\n                        errorMsg = caught\n                    }\n                }\n                L.w(errorMsg)\n            } finally {\n                Prefs.readingListsLastSyncTime = client.lastDateHeader?.toString() ?: lastSyncTime\n                Prefs.readingListsDeletedIds = listIdsDeleted\n                Prefs.readingListPagesDeletedIds = pageIdsDeleted\n                readingListSyncNotification.cancelNotification(applicationContext)\n                if (shouldSendSyncEvent) {\n                    SavedPageSyncService.sendSyncEvent(extras.containsKey(SYNC_EXTRAS_REFRESHING))\n                }\n                if ((shouldRetry || shouldRetryWithForce) && !extras.containsKey(SYNC_EXTRAS_RETRYING)) {\n                    val b = Bundle()\n                    b.putAll(extras)\n                    b.putBoolean(SYNC_EXTRAS_RETRYING, true)\n                    if (shouldRetryWithForce) {\n                        b.putBoolean(SYNC_EXTRAS_FORCE_FULL_SYNC, true)\n                    }\n                    manualSync(b)\n                }\n                IN_PROGRESS = false\n                SavedPageSyncService.enqueue()\n                L.d(\"Finished sync of reading lists.\")\n            }\n            Result.success()\n        }\n    }\n\n    private fun getBooleanExtraFromData(inputData: Data): Bundle {\n        val extras = Bundle()\n        inputData.keyValueMap.forEach {\n            extras.putBoolean(it.key, it.value as Boolean)\n        }\n        return extras\n    }\n\n    private suspend fun createOrUpdatePage(listForPage: ReadingList,\n                                   remotePage: RemoteReadingListEntry) {\n        val remoteTitle = pageTitleFromRemoteEntry(remotePage)\n        var localPage = listForPage.pages.find { ReadingListPage.toPageTitle(it) == remoteTitle }\n        var updateOnly = localPage != null\n\n        if (localPage == null) {\n            localPage = ReadingListPage(pageTitleFromRemoteEntry(remotePage))\n            localPage.listId = listForPage.id\n            updateOnly = AppDatabase.instance.readingListPageDao().getPageByTitle(listForPage, remoteTitle) != null\n        }\n        localPage.remoteId = remotePage.id\n        localPage.atime = remotePage.created.toInstant(ZoneOffset.UTC).toEpochMilli()\n        localPage.mtime = remotePage.updated.toInstant(ZoneOffset.UTC).toEpochMilli()\n        if (updateOnly) {\n            L.d(\"Updating local page \" + localPage.apiTitle)\n            AppDatabase.instance.readingListPageDao().updateReadingListPage(localPage)\n        } else {\n            L.d(\"Creating local page \" + localPage.apiTitle)\n            AppDatabase.instance.readingListPageDao().addPagesToList(listForPage, listOf(localPage), false)\n        }\n    }\n\n    private suspend fun deletePageByTitle(listForPage: ReadingList, title: PageTitle) {\n        var localPage = listForPage.pages.find { ReadingListPage.toPageTitle(it) == title }\n        if (localPage == null) {\n            localPage = AppDatabase.instance.readingListPageDao().getPageByTitle(listForPage, title)\n            if (localPage == null) {\n                return\n            }\n        }\n        L.d(\"Deleting local page \" + localPage.apiTitle)\n        AppDatabase.instance.readingListPageDao().markPagesForDeletion(listForPage, listOf(localPage), false)\n    }\n\n    private fun pageTitleFromRemoteEntry(remoteEntry: RemoteReadingListEntry): PageTitle {\n        return PageTitle(remoteEntry.title(), WikiSite(remoteEntry.project()))\n    }\n\n    private fun remoteEntryFromLocalPage(localPage: ReadingListPage): RemoteReadingListEntry {\n        val title = ReadingListPage.toPageTitle(localPage)\n        return RemoteReadingListEntry(0, 0,\n            \"${title.wikiSite.scheme()}://${title.wikiSite.authority()}\", title.prefixedText,\n            created = if (localPage.atime == 0L) LocalDateTime.now() else LocalDateTime.ofInstant(Instant.ofEpochMilli(localPage.atime), ZoneOffset.UTC),\n            updated = if (localPage.mtime == 0L) LocalDateTime.now() else LocalDateTime.ofInstant(Instant.ofEpochMilli(localPage.mtime), ZoneOffset.UTC))\n    }\n\n    companion object {\n        private const val WORK_NAME = \"readingListSyncAdapter\"\n        private const val SYNC_EXTRAS_FORCE_FULL_SYNC = \"forceFullSync\"\n        private const val SYNC_EXTRAS_REFRESHING = \"refreshing\"\n        private const val SYNC_EXTRAS_RETRYING = \"retrying\"\n        private var IN_PROGRESS = false\n\n        fun inProgress(): Boolean {\n            return IN_PROGRESS\n        }\n\n        fun setSyncEnabledWithSetup() {\n            Prefs.isReadingListSyncEnabled = true\n            Prefs.isReadingListsRemoteSetupPending = true\n            Prefs.isReadingListsRemoteDeletePending = false\n            manualSync()\n        }\n\n        fun manualSyncWithDeleteList(list: ReadingList) {\n            if (list.remoteId <= 0) {\n                return\n            }\n            Prefs.addReadingListsDeletedIds(setOf(list.remoteId))\n            manualSync()\n        }\n\n        fun createIdsForDeletion(list: ReadingList, pages: Set<ReadingListPage>): Set<String> {\n            return if (list.remoteId <= 0) emptySet() else pages.map { it.remoteId }.filter { it > 0 }.map { \"${list.remoteId}:$it\" }.toSet()\n        }\n\n        fun manualSyncWithDeletePages(list: ReadingList, pages: List<ReadingListPage>) {\n            val ids = createIdsForDeletion(list, pages.toSet())\n            if (ids.isNotEmpty()) {\n                Prefs.addReadingListPagesDeletedIds(ids)\n                manualSync()\n            }\n        }\n\n        fun manualSyncWithDeletePages(lists: List<ReadingList>) {\n            val ids = lists.flatMapTo(mutableSetOf()) { list ->\n                createIdsForDeletion(list, list.pages.toSet())\n            }\n\n            if (ids.isNotEmpty()) {\n                Prefs.addReadingListPagesDeletedIds(ids)\n                manualSync()\n            }\n        }\n\n        fun manualSyncWithForce(fromRefresh: Boolean = false) {\n            val extras = bundleOf(SYNC_EXTRAS_FORCE_FULL_SYNC to true)\n            // Pull-to-refresh needs the REFRESHING flag so a ReadingListSyncEvent is emitted on\n            // completion to dismiss the refresh spinner.\n            if (fromRefresh) {\n                extras.putBoolean(SYNC_EXTRAS_REFRESHING, true)\n            }\n            manualSync(extras)\n        }\n\n        fun manualSyncWithRefresh() {\n            Prefs.isSuggestedEditsHighestPriorityEnabled = false\n            manualSync(bundleOf(SYNC_EXTRAS_REFRESHING to true))\n        }\n\n        fun manualSync(extras: Bundle = Bundle()) {\n            if (inProgress()) {\n                return\n            }\n            if (AccountUtil.account() == null || !WikipediaApp.instance.isOnline) {\n                if (extras.containsKey(SYNC_EXTRAS_REFRESHING)) {\n                    SavedPageSyncService.sendSyncEvent()\n                }\n                return\n            }\n            extras.putBoolean(ContentResolver.SYNC_EXTRAS_MANUAL, true)\n            extras.putBoolean(ContentResolver.SYNC_EXTRAS_EXPEDITED, true)\n\n            // Convert the Bundle to a Data object\n            val dataBuilder = Data.Builder()\n            extras.keySet().forEach {\n                dataBuilder.putBoolean(it, extras.getBoolean(it))\n            }\n\n            val constraints = Constraints.Builder()\n                .setRequiredNetworkType(NetworkType.CONNECTED)\n                .build()\n            val workRequest = OneTimeWorkRequestBuilder<ReadingListSyncAdapter>()\n                .setConstraints(constraints)\n                .setInputData(dataBuilder.build())\n                .build()\n            WorkManager.getInstance(WikipediaApp.instance)\n                .enqueueUniqueWork(WORK_NAME, ExistingWorkPolicy.REPLACE, workRequest)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/sync/ReadingListSyncAdapter.kt","kind":"class","line":41,"members":{"IN_PROGRESS":[508,508],"SYNC_EXTRAS_FORCE_FULL_SYNC":[505,505],"SYNC_EXTRAS_REFRESHING":[506,506],"SYNC_EXTRAS_RETRYING":[507,507],"WORK_NAME":[504,504],"context":[41,41],"createIdsForDeletion":[529,531],"createOrUpdatePage":[456,477],"deletePageByTitle":[479,489],"doWork":[43,446],"getBooleanExtraFromData":[448,454],"inProgress":[510,512],"manualSync":[567,595],"manualSyncWithDeleteList":[521,527],"manualSyncWithDeletePages":[533,539],"manualSyncWithForce":[552,560],"manualSyncWithRefresh":[562,565],"pageTitleFromRemoteEntry":[491,493],"params":[41,41],"remoteEntryFromLocalPage":[495,501],"setSyncEnabledWithSetup":[514,519]},"supers":["CoroutineWorker(context, params)"]},"ReadingListsFragment":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["saved","h-classes","Logic \u00b7 class diagram"],["saved","h-widgets","Screen \u00b7 composition"]],"code":"class ReadingListsFragment : Fragment(), SortReadingListsDialog.Callback, ReadingListItemActionsDialog.Callback {\n\n    private val viewModel: ReadingListsViewModel by viewModels()\n    private var actionMode: ActionMode? = null\n\n    private val filePickerLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->\n        if (result.resultCode == AppCompatActivity.RESULT_OK) {\n            result.data?.data?.let(::importReadingLists)\n        }\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        RecommendedReadingListEvent.submit(\"impression\", \"rrl_saved\")\n    }\n\n    override fun onCreateView(\n        inflater: LayoutInflater,\n        container: ViewGroup?,\n        savedInstanceState: Bundle?\n    ): View {\n        return ComposeView(requireContext()).apply {\n            setContent {\n                BaseTheme {\n                    val uiState by viewModel.uiState.collectAsStateWithLifecycle()\n                    val isRefreshing by viewModel.isRefreshing.collectAsStateWithLifecycle()\n                    val selectionState by viewModel.selectionState.collectAsStateWithLifecycle()\n                    ReadingListsScreen(\n                        uiState = uiState,\n                        isRefreshing = isRefreshing,\n                        pullToRefreshEnabled = !RemoteConfig.config.disableReadingListSync,\n                        isSelectionMode = selectionState.enabled,\n                        selectedListIds = selectionState.selectedListIds,\n                        selectedPageIds = selectionState.selectedPageIds,\n                        showCollectionsBadge = uiState.showCollectionsBadge,\n                        onSelectTab = ::onSelectTab,\n                        onOnboardingAction = ::onOnboardingAction,\n                        onRefresh = ::onRefresh,\n                        onListClick = ::onListClick,\n                        onListMenuAction = ::onListMenuAction,\n                        onListSelectionChange = viewModel::toggleListSelection,\n                        onPageSelectionChange = viewModel::togglePageSelection,\n                        onPageClick = ::onPageClick,\n                        onPageLongClick = ::onPageLongClick,\n                        onPageChipClick = ::onPageChipClick,\n                        onPageToggleOfflineClick = ::onToggleOfflineClick,\n                        onDiscoverCardClick = ::onDiscoverCardClick,\n                        onCreateCollectionClick = overflowCallback::createNewListClick\n                    )\n                }\n            }\n        }\n    }\n\n    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {\n        super.onViewCreated(view, savedInstanceState)\n        viewLifecycleOwner.lifecycleScope.launch {\n            viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.CREATED) {\n                FlowEventBus.events.collectLatest { event ->\n                    when (event) {\n                        // The list itself updates reactively via the DB flow; this just stops the spinner.\n                        is ReadingListSyncEvent -> viewModel.setRefreshing(false)\n                        is LoggedInEvent,\n                        is LoggedOutEvent,\n                        is LoggedOutInBackgroundEvent -> viewModel.refreshAccountState()\n                        is PageDownloadEvent -> viewModel.updatePageDownloadProgress(event.page)\n                        is ArticleSavedOrDeletedEvent -> {\n                            if (event.isAdded && Prefs.readingListsPageSaveCount < SAVE_COUNT_LIMIT) {\n                                showReadingListsSyncDialog()\n                                Prefs.readingListsPageSaveCount += 1\n                            }\n                        }\n                    }\n                }\n            }\n        }\n\n        viewLifecycleOwner.lifecycleScope.launch {\n            viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {\n                combine(viewModel.uiState, viewModel.selectionState) { _, _ -> }.collect {\n                    actionMode?.invalidate()\n                }\n            }\n        }\n\n        viewLifecycleOwner.lifecycleScope.launch {\n            viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.RESUMED) {\n                launch {\n                    val initialState = viewModel.uiState.first { !it.isLoading }\n                    ReadingListsAnalyticsHelper.logListsShown(requireContext(), initialState.listCount)\n                    viewModel.uiState\n                        .map { it.listCount >= Constants.MAX_READING_LISTS_LIMIT }\n                        .distinctUntilChanged()\n                        .collect(::maybeShowListLimitMessage)\n                }\n                launch {\n                    viewModel.uiState\n                        .map { state ->\n                            state.pendingPreviewSavedListId?.takeIf { id ->\n                                state.rows.any {\n                                    it is ReadingListRow.ListRow && it.list.id == id\n                                }\n                            }\n                        }\n                        .distinctUntilChanged()\n                        .collect { listId ->\n                            listId?.let { maybeShowPreviewSavedReadingListsSnackbar(it) }\n                        }\n                }\n            }\n        }\n    }\n\n    private fun showReadingListsSyncDialog() {\n        if (Prefs.isReadingListSyncEnabled) {\n            return\n        }\n        if (AccountUtil.isLoggedIn) {\n            ReadingListSyncBehaviorDialogs.promptEnableSyncDialog(requireActivity())\n        }\n    }\n\n    private fun onRefresh() {\n        viewModel.setRefreshing(true)\n        if (!AccountUtil.isLoggedIn || AccountUtil.isTemporaryAccount) {\n            viewModel.setRefreshing(false)\n        } else {\n            Prefs.isReadingListSyncEnabled = true\n            // TODO: Change this back to the less forceful manualSyncWithRefresh() when the\n            // service-side endpoint is fixed.\n            // https://phabricator.wikimedia.org/T351149\n            ReadingListSyncAdapter.manualSyncWithForce(fromRefresh = true)\n        }\n    }\n\n    private fun maybeShowListLimitMessage(atLimit: Boolean) {\n        if (atLimit && actionMode == null) {\n            FeedbackUtil.makeSnackbar(\n                requireActivity(),\n                getString(R.string.reading_lists_limit_message)\n            ).show()\n        }\n    }\n\n    private suspend fun maybeShowPreviewSavedReadingListsSnackbar(listId: Long) {\n        val list = viewModel.loadReadingListWithPagesById(listId) ?: return\n        ReadingListsAnalyticsHelper.logReceiveFinish(requireContext(), list)\n        FeedbackUtil.makeSnackbar(requireActivity(), getString(R.string.reading_lists_preview_saved_snackbar))\n            .setAction(R.string.suggested_edits_article_cta_snackbar_action) {\n                viewModel.clearRecentPreviewSavedList()\n                startActivity(ReadingListActivity.newIntent(requireContext(), list))\n            }\n            .show()\n        viewModel.consumePreviewSavedSnackbar(listId)\n    }\n\n    private fun maybeDeleteListFromIntent() {\n        val intent = requireActivity().intent\n        val titleToDelete = intent.getStringExtra(Constants.INTENT_EXTRA_DELETE_READING_LIST) ?: return\n        intent.removeExtra(Constants.INTENT_EXTRA_DELETE_READING_LIST)\n        viewLifecycleOwner.lifecycleScope.launch {\n            val listId = viewModel.getReadingListsWithoutContents()\n                .firstOrNull { it.title == titleToDelete }?.id ?: return@launch\n            val list = viewModel.loadReadingListWithPagesById(listId) ?: return@launch\n            ReadingListBehaviorsUtil.deleteReadingList(requireActivity(), list, false) {\n                ReadingListBehaviorsUtil.showDeleteListUndoSnackbar(requireActivity(), list) {}\n            }\n        }\n    }\n\n    private fun onOnboardingAction(action: OnboardingAction) {\n        when (action) {\n            OnboardingAction.RecommendedShown -> {\n                RecommendedReadingListEvent.submit(\"impression\", \"rrl_saved_prompt\")\n            }\n            OnboardingAction.RecommendedAccept -> {\n                startActivity(RecommendedReadingListOnboardingActivity.newIntent(requireContext()))\n                RecommendedReadingListEvent.submit(\"enter_click\", \"rrl_saved_prompt\")\n            }\n            OnboardingAction.RecommendedDismiss -> {\n                Prefs.isRecommendedReadingListOnboardingShown = true\n                FeedbackUtil.showMessage(this, getString(R.string.recommended_reading_list_onboarding_card_negative_snackbar))\n                RecommendedReadingListEvent.submit(\"nothanks_click\", \"rrl_saved_prompt\")\n            }\n            OnboardingAction.SyncEnable -> {\n                ReadingListSyncAdapter.setSyncEnabledWithSetup()\n            }\n            OnboardingAction.SyncDismiss -> {\n                Prefs.isReadingListSyncReminderEnabled = false\n            }\n            OnboardingAction.LoginRequest -> {\n                if (isAdded && requireParentFragment() is MainFragment) {\n                    (requireParentFragment() as MainFragment).onLoginRequested()\n                }\n            }\n            OnboardingAction.LoginDismiss -> {\n                Prefs.isReadingListLoginReminderEnabled = false\n            }\n        }\n    }\n\n    override fun onResume() {\n        super.onResume()\n        viewModel.refreshAccountState()\n        viewModel.refreshRecentPreviewSavedList()\n        maybeDeleteListFromIntent()\n        requireActivity().invalidateOptionsMenu()\n    }\n\n    override fun onPause() {\n        super.onPause()\n        actionMode?.finish()\n    }\n\n    // Search action mode\n    fun startSearchActionMode() {\n        (requireActivity() as AppCompatActivity).startSupportActionMode(searchActionModeCallback)\n    }\n\n    private fun onSelectTab(tab: SavedTab) {\n        actionMode?.takeIf(::isTagType)?.finish()\n        viewModel.setSelectedTab(tab)\n        searchActionModeCallback.updateSearchHint(getSearchHint(tab))\n        requireActivity().invalidateOptionsMenu()\n    }\n\n    private fun getSearchHint(tab: SavedTab): String {\n        return getString(\n            when (tab) {\n                SavedTab.ALL_ARTICLES -> R.string.reading_lists_search_saved_articles\n                SavedTab.COLLECTIONS -> R.string.reading_lists_search_collections\n            }\n        )\n    }\n\n    private val searchActionModeCallback = object : SearchActionModeCallback() {\n        override fun onCreateActionMode(mode: ActionMode, menu: Menu): Boolean {\n            actionMode = mode\n            viewModel.setSearchActive(true)\n            if (isAdded) {\n                (requireParentFragment() as MainFragment).setBottomNavVisible(false)\n            }\n            return super.onCreateActionMode(mode, menu)\n        }\n\n        override fun onQueryChange(s: String) {\n            viewModel.setSearchQuery(s.trim())\n        }\n\n        override fun onDestroyActionMode(mode: ActionMode) {\n            super.onDestroyActionMode(mode)\n            actionMode = null\n            viewModel.setSearchActive(false)\n            viewModel.setSearchQuery(null)\n            if (isAdded) {\n                (requireParentFragment() as MainFragment).setBottomNavVisible(true)\n            }\n        }\n\n        override fun getSearchHintString(): String {\n            return getSearchHint(viewModel.uiState.value.selectedTab)\n        }\n\n        override fun getParentContext(): Context {\n            return requireContext()\n        }\n    }\n\n    fun isAllArticlesSelected(): Boolean {\n        return viewModel.isSelectedTab(SavedTab.ALL_ARTICLES)\n    }\n\n    fun showReadingListsFilterMenu() {\n        if (!isAllArticlesSelected()) {\n            return\n        }\n        ReadingListsAllArticlesFilterOverflowView(requireContext()).show(\n            anchorView = (requireActivity() as MainActivity).getToolbar()\n                .findViewById(R.id.menu_filter_reading_lists_articles),\n            selectedOption = viewModel.getSelectedArticleFilter(),\n            callback = viewModel::setArticleFilter\n        )\n    }\n\n    // Overflow menu\n    fun showReadingListsOverflowMenu() {\n        ReadingListsOverflowView(requireContext()).show(\n            anchorView = (requireActivity() as MainActivity).getToolbar()\n                .findViewById(R.id.menu_overflow_button),\n            callback = overflowCallback,\n            showCollectionActions = viewModel.uiState.value.selectedTab == SavedTab.COLLECTIONS\n        )\n    }\n\n    private val overflowCallback = object : ReadingListsOverflowView.Callback {\n        override fun sortByClick() {\n            ExclusiveBottomSheetPresenter.show(\n                childFragmentManager,\n                SortReadingListsDialog.newInstance(\n                    sortOption = viewModel.uiState.value.sortMode,\n                    sortArticles = viewModel.uiState.value.selectedTab == SavedTab.ALL_ARTICLES\n                )\n            )\n        }\n\n        override fun createNewListClick() {\n            viewLifecycleOwner.lifecycleScope.launch {\n                val existingTitles = viewModel.getReadingListsWithoutContents()\n                    .map { it.title }\n                ReadingListTitleDialog.readingListTitleDialog(\n                    activity = requireActivity(),\n                    title = getString(R.string.reading_list_name_sample),\n                    description = \"\",\n                    otherTitles = existingTitles,\n                    callback = object : ReadingListTitleDialog.Callback {\n                        override fun onSuccess(text: String, description: String) {\n                            viewLifecycleOwner.lifecycleScope.launch(\n                                CoroutineExceptionHandler { _, throwable -> L.w(throwable) }\n                            ) {\n                                viewModel.createReadingList(text, description)\n                            }\n                        }\n                    }\n                ).show()\n            }\n        }\n\n        override fun importNewList() {\n            val intent = Intent(Intent.ACTION_GET_CONTENT).apply { type = \"application/json\" }\n            val filePickerIntent = Intent.createChooser(intent, getString(R.string.reading_lists_import_file_picker_title))\n            filePickerLauncher.launch(filePickerIntent)\n        }\n\n        override fun selectListClick() {\n            beginMultiSelect()\n        }\n\n        override fun refreshClick() {\n            onRefresh()\n        }\n    }\n\n    override fun onSortOptionClick(position: Int) {\n        viewModel.setSortMode(position)\n    }\n\n    private fun importReadingLists(uri: android.net.Uri) {\n        val contentResolver = requireContext().contentResolver\n        viewLifecycleOwner.lifecycleScope.launch {\n            val input = withContext(Dispatchers.IO) {\n                contentResolver.openInputStream(uri)?.bufferedReader()?.use { it.readText() }\n            } ?: return@launch\n            ReadingListsExportImportHelper.importLists(requireActivity() as AppCompatActivity, input)\n        }\n    }\n\n    private fun onListClick(listId: Long) {\n        if (isTagType(actionMode)) {\n            viewModel.toggleListSelection(listId)\n            return\n        }\n        viewModel.clearRecentPreviewSavedList()\n        viewLifecycleOwner.lifecycleScope.launch {\n            val list = viewModel.loadReadingListWithPagesById(listId) ?: return@launch\n            RecommendedReadingListEvent.submit(\"open_list_click\", \"rrl_saved\")\n            startActivity(ReadingListActivity.newIntent(requireContext(), list))\n        }\n    }\n\n    // ListRow onLongClick actions\n    private fun onListMenuAction(listId: Long, action: ReadingListMenuAction) {\n        BreadCrumbLogEvent.logClick(\n            requireContext(),\n            resources.getResourceEntryName(action.breadcrumbId())\n        )\n        viewLifecycleOwner.lifecycleScope.launch {\n            val list = viewModel.loadReadingListWithPagesById(listId) ?: return@launch\n            // List refresh happens reactively via the DB flow, so these callbacks don't call updateLists.\n            when (action) {\n                ReadingListMenuAction.Rename -> {\n                    if (list.isDefault) return@launch\n                    ReadingListBehaviorsUtil.renameReadingList(requireActivity(), list) {\n                        ReadingListSyncAdapter.manualSync()\n                    }\n                }\n                ReadingListMenuAction.Delete -> {\n                    ReadingListBehaviorsUtil.deleteReadingList(requireActivity(), list, true) {\n                        ReadingListBehaviorsUtil.showDeleteListUndoSnackbar(requireActivity(), list) {}\n                    }\n                }\n                ReadingListMenuAction.SaveAllOffline -> {\n                    ReadingListBehaviorsUtil.savePagesForOffline(requireActivity(), list.pages) {}\n                }\n                ReadingListMenuAction.RemoveAllOffline -> {\n                    ReadingListBehaviorsUtil.removePagesFromOffline(requireActivity(), list.pages) {}\n                }\n                ReadingListMenuAction.Export -> {\n                    ReadingListsExportImportHelper.exportLists(requireActivity() as BaseActivity, listOf(list))\n                }\n                ReadingListMenuAction.Select -> {\n                    beginMultiSelect()\n                    viewModel.toggleListSelection(listId)\n                }\n                ReadingListMenuAction.Share -> {\n                    ReadingListsShareHelper.shareReadingList(requireActivity() as AppCompatActivity, list)\n                }\n            }\n        }\n    }\n\n    private fun ReadingListMenuAction.breadcrumbId(): Int {\n        return when (this) {\n            ReadingListMenuAction.Rename -> R.id.menu_reading_list_rename\n            ReadingListMenuAction.Delete -> R.id.menu_reading_list_delete\n            ReadingListMenuAction.SaveAllOffline -> R.id.menu_reading_list_save_all_offline\n            ReadingListMenuAction.RemoveAllOffline -> R.id.menu_reading_list_remove_all_offline\n            ReadingListMenuAction.Export -> R.id.menu_reading_list_export\n            ReadingListMenuAction.Select -> R.id.menu_reading_list_select\n            ReadingListMenuAction.Share -> R.id.menu_reading_list_share\n        }\n    }\n\n    private fun onPageClick(pageId: Long) {\n        if (isTagType(actionMode)) {\n            viewModel.togglePageSelection(pageId)\n            return\n        }\n        launchWithPage(pageId) { page ->\n            val entry = HistoryEntry(ReadingListPage.toPageTitle(page), HistoryEntry.SOURCE_READING_LIST)\n            ReadingListBehaviorsUtil.updateReadingListPage(page)\n            startActivity(PageActivity.newIntentForCurrentTab(requireContext(), entry, entry.title))\n        }\n    }\n\n    private fun onPageLongClick(pageId: Long) {\n        val containingLists = viewModel.containingLists(pageId)\n        if (containingLists.isEmpty()) {\n            return\n        }\n        ExclusiveBottomSheetPresenter.show(\n            childFragmentManager,\n            ReadingListItemActionsDialog.newInstance(\n                containingLists.first().title,\n                containingLists.size,\n                pageId,\n                actionMode != null,\n                containingLists.count { !it.isDefault }\n            )\n        )\n    }\n\n    private fun onToggleOfflineClick(pageId: Long) {\n        launchWithPage(pageId) { page ->\n            if (Prefs.isDownloadOnlyOverWiFiEnabled && !DeviceUtil.isOnWiFi &&\n                page.status == ReadingListPage.STATUS_QUEUE_FOR_SAVE) {\n                page.offline = false\n            }\n            if (page.saving) {\n                Toast.makeText(requireContext(), R.string.reading_list_article_save_in_progress, Toast.LENGTH_LONG).show()\n            } else {\n                ReadingListBehaviorsUtil.toggleOffline(requireActivity(), page) {\n                    viewModel.updatePageDownloadProgress(page)\n                }\n            }\n        }\n    }\n\n    private fun onDiscoverCardClick() {\n        startActivity(ReadingListActivity.newIntent(requireActivity(), ReadingListMode.RECOMMENDED))\n    }\n\n    private fun onPageChipClick(listId: Long) {\n        viewLifecycleOwner.lifecycleScope.launch {\n            val list = viewModel.loadReadingListWithPagesById(listId) ?: return@launch\n            startActivity(ReadingListActivity.newIntent(requireContext(), list))\n        }\n    }\n\n    // PageRow OnLongClick ReadingListItemActionsDialog Callbacks\n    override fun onToggleItemOffline(pageId: Long) {\n        launchWithPage(pageId) { page ->\n            ReadingListBehaviorsUtil.togglePageOffline(requireActivity(), page) {\n                viewModel.updatePageDownloadProgress(page)\n            }\n        }\n    }\n\n    override fun onShareItem(pageId: Long) {\n        launchWithPage(pageId) { page ->\n            ShareUtil.shareText(requireActivity(), ReadingListPage.toPageTitle(page))\n        }\n    }\n\n    override fun onManageCollections(pageId: Long) {\n        launchWithPage(pageId) { page ->\n            SaveArticleSheetDialog.show(childFragmentManager, ReadingListPage.toPageTitle(page))\n        }\n    }\n\n    override fun onSelectItem(pageId: Long) {\n        beginMultiSelect()\n        viewModel.togglePageSelection(pageId)\n    }\n\n    override fun onDeleteItem(pageId: Long) {\n        viewLifecycleOwner.lifecycleScope.launch {\n            val deletion = viewModel.prepareSelectedPagesForDeletion(setOf(pageId)) ?: return@launch\n            ReadingListBehaviorsUtil.deletePagesFromLists(\n                requireActivity(),\n                deletion.selectedPageCount,\n                deletion.readingLists,\n                {}\n            ) {}\n        }\n    }\n\n    private fun launchWithPage(pageId: Long, action: suspend (ReadingListPage) -> Unit) {\n        viewLifecycleOwner.lifecycleScope.launch {\n            val page = viewModel.getPageById(pageId) ?: return@launch\n            action(page)\n        }\n    }\n\n    private fun beginMultiSelect() {\n        if (!isTagType(actionMode)) {\n            viewModel.setSelectionMode(true)\n            val callback = when (viewModel.uiState.value.selectedTab) {\n                SavedTab.ALL_ARTICLES -> articleSelectionCallback\n                SavedTab.COLLECTIONS -> collectionSelectionCallback\n            }\n            actionMode = (requireActivity() as AppCompatActivity)\n                .startSupportActionMode(callback)\n        }\n    }\n\n    private val collectionSelectionCallback = object : MultiSelectActionModeCallback() {\n        override fun onCreateActionMode(mode: ActionMode, menu: Menu): Boolean {\n            super.onCreateActionMode(mode, menu)\n            mode.menuInflater.inflate(R.menu.menu_action_mode_reading_lists, menu)\n            actionMode = mode\n            val deleteItem = menu.findItem(R.id.menu_delete_selected)\n            deleteItem.isEnabled = false\n            return true\n        }\n\n        override fun onPrepareActionMode(mode: ActionMode, menu: Menu): Boolean {\n            val selectedIds = viewModel.selectionState.value.selectedListIds\n            val listRows = viewModel.uiState.value.rows.filterIsInstance<ReadingListRow.ListRow>()\n            val selectedLists = listRows.filter { it.list.id in selectedIds }\n            val allListIds = listRows.map { it.list.id }\n            val allSelected = allListIds.isNotEmpty() && selectedIds.containsAll(allListIds)\n            val onlyDefaultSelected = selectedLists.size == 1 && selectedLists.single().list.isDefault\n\n            mode.title = if (selectedLists.isEmpty()) \"\" else {\n                getString(R.string.multi_select_items_selected, selectedLists.size)\n            }\n            val fullOpacity = 255\n            val halfOpacity = 80\n            menu.findItem(R.id.menu_delete_selected).apply {\n                isEnabled = selectedLists.isNotEmpty() && !onlyDefaultSelected\n                icon?.alpha = if (selectedLists.isEmpty() || onlyDefaultSelected) halfOpacity else fullOpacity\n            }\n            menu.findItem(R.id.menu_export_selected).apply {\n                isEnabled = selectedLists.isNotEmpty()\n                val exportColor = ResourceUtil.getThemedColor(requireContext(), R.attr.progressive_color)\n                title = buildSpannedString {\n                    color(ColorUtils.setAlphaComponent(exportColor, if (selectedLists.isEmpty()) halfOpacity else fullOpacity)) {\n                        append(getString(R.string.reading_lists_action_menu_export_lists))\n                    }\n                }\n            }\n            menu.findItem(R.id.menu_select).apply {\n                setIcon(when {\n                    selectedLists.isEmpty() -> R.drawable.ic_outline_library_add_check_24\n                    allSelected -> R.drawable.ic_deselect_all\n                    else -> R.drawable.ic_select_indeterminate\n                })\n                title = when {\n                    selectedLists.isEmpty() -> getString(R.string.notifications_menu_check_all)\n                    allSelected -> getString(R.string.notifications_menu_uncheck_all)\n                    else -> \"\"\n                }\n            }\n            return true\n        }\n\n        override fun onActionItemClicked(mode: ActionMode, menuItem: MenuItem): Boolean {\n            return when (menuItem.itemId) {\n                R.id.menu_delete_selected -> {\n                    onDeleteSelected()\n                    true\n                }\n                R.id.menu_export_selected -> {\n                    exportSelectedLists()\n                    true\n                }\n                R.id.menu_select -> {\n                    val allListIds = viewModel.uiState.value.rows\n                        .filterIsInstance<ReadingListRow.ListRow>()\n                        .map { it.list.id }\n                    val selectedIds = viewModel.selectionState.value.selectedListIds\n                    if (allListIds.isNotEmpty() && selectedIds.containsAll(allListIds)) {\n                        viewModel.clearListSelection()\n                    } else {\n                        viewModel.selectAllLists()\n                    }\n                    true\n                }\n                else -> super.onActionItemClicked(mode, menuItem)\n            }\n        }\n\n        override fun onDeleteSelected() {\n            deleteSelectedLists()\n        }\n\n        override fun onDestroyActionMode(mode: ActionMode) {\n            viewModel.setSelectionMode(false)\n            actionMode = null\n            super.onDestroyActionMode(mode)\n        }\n    }\n\n    private val articleSelectionCallback = object : MultiSelectActionModeCallback() {\n        override fun onCreateActionMode(mode: ActionMode, menu: Menu): Boolean {\n            super.onCreateActionMode(mode, menu)\n            mode.menuInflater.inflate(R.menu.menu_action_mode_reading_list_articles, menu)\n            actionMode = mode\n            return true\n        }\n\n        override fun onPrepareActionMode(mode: ActionMode, menu: Menu): Boolean {\n            val selectedIds = viewModel.selectionState.value.selectedPageIds\n            val allPageIds = viewModel.uiState.value.rows\n                .filterIsInstance<ReadingListRow.PageRow>()\n                .map { it.page.id }\n            val allSelected = allPageIds.isNotEmpty() && selectedIds.containsAll(allPageIds)\n\n            mode.title = if (selectedIds.isEmpty()) \"\" else {\n                getString(R.string.multi_select_items_selected, selectedIds.size)\n            }\n            menu.findItem(R.id.menu_delete_selected).apply {\n                isEnabled = selectedIds.isNotEmpty()\n                icon?.alpha = if (selectedIds.isEmpty()) 80 else 255\n            }\n            menu.findItem(R.id.menu_select).apply {\n                setIcon(when {\n                    selectedIds.isEmpty() -> R.drawable.ic_outline_library_add_check_24\n                    allSelected -> R.drawable.ic_deselect_all\n                    else -> R.drawable.ic_select_indeterminate\n                })\n                title = when {\n                    selectedIds.isEmpty() -> getString(R.string.notifications_menu_check_all)\n                    allSelected -> getString(R.string.notifications_menu_uncheck_all)\n                    else -> \"\"\n                }\n            }\n            return true\n        }\n\n        override fun onActionItemClicked(mode: ActionMode, menuItem: MenuItem): Boolean {\n            return when (menuItem.itemId) {\n                R.id.menu_delete_selected -> {\n                    onDeleteSelected()\n                    true\n                }\n                R.id.menu_remove_from_offline -> {\n                    updateSelectedPagesOffline(saveForOffline = false)\n                    true\n                }\n                R.id.menu_save_for_offline -> {\n                    updateSelectedPagesOffline(saveForOffline = true)\n                    true\n                }\n                R.id.menu_add_to_another_list -> {\n                    addSelectedPagesToList()\n                    true\n                }\n                R.id.menu_select -> {\n                    val allPageIds = viewModel.uiState.value.rows\n                        .filterIsInstance<ReadingListRow.PageRow>()\n                        .map { it.page.id }\n                    val selectedIds = viewModel.selectionState.value.selectedPageIds\n                    if (allPageIds.isNotEmpty() && selectedIds.containsAll(allPageIds)) {\n                        viewModel.clearPageSelection()\n                    } else {\n                        viewModel.selectAllPages()\n                    }\n                    true\n                }\n                else -> super.onActionItemClicked(mode, menuItem)\n            }\n        }\n\n        override fun onDeleteSelected() {\n            deleteSelectedPages()\n        }\n\n        override fun onDestroyActionMode(mode: ActionMode) {\n            viewModel.setSelectionMode(false)\n            actionMode = null\n            super.onDestroyActionMode(mode)\n        }\n    }\n\n    private fun updateSelectedPagesOffline(saveForOffline: Boolean) {\n        val selectedPageIds = viewModel.selectionState.value.selectedPageIds\n        viewLifecycleOwner.lifecycleScope.launch {\n            val pages = viewModel.getPagesByIds(selectedPageIds)\n            if (pages.isEmpty()) {\n                return@launch\n            }\n            if (saveForOffline) {\n                ReadingListBehaviorsUtil.savePagesForOffline(requireActivity(), pages) {\n                    actionMode?.finish()\n                }\n            } else {\n                ReadingListBehaviorsUtil.removePagesFromOffline(requireActivity(), pages) {\n                    actionMode?.finish()\n                }\n            }\n        }\n    }\n\n    private fun addSelectedPagesToList() {\n        val selectedPageIds = viewModel.selectionState.value.selectedPageIds\n        viewLifecycleOwner.lifecycleScope.launch {\n            val titles = viewModel.getPagesByIds(selectedPageIds)\n                .distinctBy { it.lang to it.apiTitle }\n                .map { ReadingListPage.toPageTitle(it) }\n            if (titles.isEmpty()) {\n                return@launch\n            }\n            val dialog = AddToReadingListDialog.newInstance(titles, InvokeSource.READING_LIST_ACTIVITY).apply {\n                dismissListener = DialogInterface.OnDismissListener { actionMode?.finish() }\n            }\n            ExclusiveBottomSheetPresenter.show(childFragmentManager, dialog)\n        }\n    }\n\n    private fun deleteSelectedPages() {\n        viewLifecycleOwner.lifecycleScope.launch {\n            val deletion = viewModel.prepareSelectedPagesForDeletion() ?: return@launch\n            ReadingListBehaviorsUtil.deletePagesFromLists(\n                requireActivity(),\n                deletion.selectedPageCount,\n                deletion.readingLists,\n                {}\n            ) {\n                actionMode?.finish()\n            }\n        }\n    }\n\n    private fun deleteSelectedLists() {\n        val selectedIds = viewModel.selectionState.value.selectedListIds\n        viewLifecycleOwner.lifecycleScope.launch {\n            val lists = viewModel.loadReadingListsWithPagesByIds(selectedIds)\n            if (lists.isEmpty()) {\n                return@launch\n            }\n            ReadingListBehaviorsUtil.deleteReadingLists(requireActivity(), lists) {\n                ReadingListBehaviorsUtil.showDeleteListsUndoSnackbar(requireActivity(), lists) {}\n                actionMode?.finish()\n            }\n        }\n    }\n\n    private fun exportSelectedLists() {\n        val selectedIds = viewModel.selectionState.value.selectedListIds\n        viewLifecycleOwner.lifecycleScope.launch {\n            val lists = viewModel.loadReadingListsWithPagesByIds(selectedIds)\n            if (lists.isNotEmpty()) {\n                ReadingListsExportImportHelper.exportLists(requireActivity() as BaseActivity, lists)\n                actionMode?.finish()\n            }\n        }\n    }\n\n    companion object {\n        private const val SAVE_COUNT_LIMIT = 3\n\n        fun newInstance(): ReadingListsFragment {\n            return ReadingListsFragment()\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/readinglist/ReadingListsFragment.kt","kind":"class","line":76,"members":{"SAVE_COUNT_LIMIT":[856,856],"actionMode":[79,79],"addSelectedPagesToList":[800,814],"articleSelectionCallback":[699,779],"beginMultiSelect":[599,609],"breadcrumbId":[486,496],"collectionSelectionCallback":[611,697],"deleteSelectedLists":[830,842],"deleteSelectedPages":[816,828],"exportSelectedLists":[844,853],"filePickerLauncher":[81,85],"getSearchHint":[302,309],"importReadingLists":[422,430],"isAllArticlesSelected":[344,346],"launchWithPage":[592,597],"maybeDeleteListFromIntent":[232,244],"maybeShowListLimitMessage":[211,218],"maybeShowPreviewSavedReadingListsSnackbar":[220,230],"newInstance":[858,860],"onCreate":[87,90],"onCreateView":[92,128],"onDeleteItem":[580,590],"onDiscoverCardClick":[543,545],"onListClick":[432,443],"onListMenuAction":[445,484],"onManageCollections":[569,573],"onOnboardingAction":[246,275],"onPageChipClick":[547,552],"onPageClick":[498,508],"onPageLongClick":[510,525],"onPause":[285,288],"onRefresh":[198,209],"onResume":[277,283],"onSelectItem":[575,578],"onSelectTab":[295,300],"onShareItem":[563,567],"onSortOptionClick":[418,420],"onToggleItemOffline":[554,561],"onToggleOfflineClick":[527,541],"onViewCreated":[130,187],"overflowCallback":[370,416],"searchActionModeCallback":[311,342],"showReadingListsFilterMenu":[348,358],"showReadingListsOverflowMenu":[360,368],"showReadingListsSyncDialog":[189,196],"startSearchActionMode":[290,293],"updateSelectedPagesOffline":[781,798],"viewModel":[78,78]},"shot":"shots/code/ReadingListsFragment.jpg","supers":["Fragment()","SortReadingListsDialog.Callback","ReadingListItemActionsDialog.Callback"]},"SavedPageSyncService":{"appearsIn":[["index","h-services","Services \u00b7 what the screens share"],["saved","h-classes","Logic \u00b7 class diagram"],["saved","h-sequence","Save an article and sync it \u00b7 sequence"]],"code":"class SavedPageSyncService(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {\n    private val savedPageSyncNotification = SavedPageSyncNotification.instance\n\n    override suspend fun doWork(): Result {\n        return withContext(Dispatchers.IO) {\n            if (ReadingListSyncAdapter.inProgress()) {\n                // Reading list sync was started in the meantime, so bail.\n                return@withContext Result.success()\n            }\n            val pagesToSave = AppDatabase.instance.readingListPageDao().getAllPagesToBeForcedSave().toMutableList()\n            if ((!Prefs.isDownloadOnlyOverWiFiEnabled || DeviceUtil.isOnWiFi) &&\n                Prefs.isDownloadingReadingListArticlesEnabled) {\n                pagesToSave.addAll(AppDatabase.instance.readingListPageDao().getAllPagesToBeSaved())\n            }\n            val pagesToUnSave = AppDatabase.instance.readingListPageDao().getAllPagesToBeUnsaved()\n            val pagesToDelete = AppDatabase.instance.readingListPageDao().getAllPagesToBeDeleted()\n            var shouldSendSyncEvent = false\n            try {\n                AppDatabase.instance.offlineObjectDao().deleteObjectsForPageId(pagesToDelete.map { it.id })\n                AppDatabase.instance.offlineObjectDao().deleteObjectsForPageId(pagesToUnSave.map { it.id })\n            } catch (e: Exception) {\n                L.e(\"Error while deleting page: \" + e.message)\n            } finally {\n                if (pagesToDelete.isNotEmpty()) {\n                    AppDatabase.instance.readingListPageDao().purgeDeletedPages()\n                    shouldSendSyncEvent = true\n                }\n                if (pagesToUnSave.isNotEmpty()) {\n                    AppDatabase.instance.readingListPageDao().updateStatus(\n                        oldStatus = ReadingListPage.STATUS_SAVED,\n                        newStatus = ReadingListPage.STATUS_QUEUE_FOR_SAVE,\n                        offline = false\n                    )\n                    shouldSendSyncEvent = true\n                }\n            }\n            val itemsTotal = pagesToSave.size\n            if (itemsTotal > 0) {\n                shouldSendSyncEvent = true\n            }\n            var itemsSaved = 0\n            try {\n                savePages(pagesToSave)\n            } finally {\n                if (savedPageSyncNotification.isSyncPaused()) {\n                    savedPageSyncNotification.setNotificationPaused(applicationContext, itemsTotal, itemsSaved)\n                } else {\n                    savedPageSyncNotification.cancelNotification(applicationContext)\n                    savedPageSyncNotification.setSyncCanceled(false)\n                    if (shouldSendSyncEvent) {\n                        sendSyncEvent()\n                    }\n                }\n            }.also { itemsSaved = it }\n            Result.success()\n        }\n    }\n\n    private suspend fun savePages(queue: MutableList<ReadingListPage>): Int {\n        return withContext(Dispatchers.IO) {\n            val itemsTotal = queue.size\n            var itemsSaved = 0\n            while (queue.isNotEmpty()) {\n\n                // Pick off the DB row that we'll be working on...\n                val page = queue.removeAt(0)\n                if (savedPageSyncNotification.isSyncPaused()) {\n                    // Remaining transactions will be picked up again when the service is resumed.\n                    break\n                } else if (savedPageSyncNotification.isSyncCanceled()) {\n                    // Mark remaining pages as online-only!\n                    queue.add(page)\n                    AppDatabase.instance.readingListPageDao().markPagesForOffline(queue, offline = false, forcedSave = false)\n                    break\n                }\n                savedPageSyncNotification.setNotificationProgress(applicationContext, itemsTotal, itemsSaved)\n                var success = false\n                var totalSize = 0L\n                try {\n                    // Lengthy operation during which the db state may change...\n                    totalSize = savePageFor(page)\n                    success = true\n                } catch (e: CancellationException) {\n                    throw e\n                } catch (_: InterruptedException) {\n                        // fall through\n                } catch (e: Exception) {\n                    // This can be an IOException from the storage media, or several types\n                    // of network exceptions from malformed URLs, timeouts, etc.\n                    L.e(e)\n\n                    // If we're offline, or if there's a transient network error, then don't do\n                    // anything.  Otherwise...\n                    if (!ThrowableUtil.isOffline(e) && !ThrowableUtil.isTimeout(e) && !ThrowableUtil.isNetworkError(e)) {\n                        // If it's not a transient network error (e.g. a 404 status response), it implies\n                        // that there's no way to fetch the page next time, or ever, therefore let's mark\n                        // it as \"successful\" so that it won't be retried again.\n                        success = true\n                        if (e !is HttpStatusException) {\n                            // And if it's something other than an HTTP status, let's log it and see what it is.\n                            L.logRemoteError(e)\n                        }\n                    }\n                }\n                if (ReadingListSyncAdapter.inProgress()) {\n                    // Reading list sync was started in the meantime, so bail.\n                    break\n                }\n                if (success) {\n                    page.status = ReadingListPage.STATUS_SAVED\n                    page.sizeBytes = totalSize\n                    AppDatabase.instance.readingListPageDao().updateReadingListPage(page)\n                    itemsSaved++\n                    sendSyncEvent()\n                }\n            }\n            itemsSaved\n        }\n    }\n\n    @Throws(Exception::class)\n    private suspend fun savePageFor(page: ReadingListPage): Long {\n        return withContext(Dispatchers.IO) {\n            val pageTitle = ReadingListPage.toPageTitle(page)\n\n            val summaryCall = async { ServiceFactory.getRest(pageTitle.wikiSite).getPageSummary(pageTitle.prefixedText,\n                cacheControl = OkHttpConnectionFactory.CACHE_CONTROL_FORCE_NETWORK.toString(),\n                saveHeader = OfflineCacheInterceptor.SAVE_HEADER_SAVE, langHeader = pageTitle.wikiSite.languageCode,\n                titleHeader = UriUtil.encodeURL(pageTitle.prefixedText)) }\n\n            val mediaListCall = async { ServiceFactory.getRest(pageTitle.wikiSite).getMediaList(pageTitle.prefixedText,\n                cacheControl = OkHttpConnectionFactory.CACHE_CONTROL_FORCE_NETWORK.toString(),\n                saveHeader = OfflineCacheInterceptor.SAVE_HEADER_SAVE, langHeader = pageTitle.wikiSite.languageCode,\n                titleHeader = UriUtil.encodeURL(pageTitle.prefixedText)) }\n\n            val mobileHTMLCall = async { reqMobileHTML(pageTitle) }\n\n            val summaryResponse = summaryCall.await()\n            val mediaListResponse = mediaListCall.await()\n            val mobileHTML = mobileHTMLCall.await()\n\n            page.downloadProgress = MEDIA_LIST_PROGRESS\n            FlowEventBus.post(PageDownloadEvent(page))\n\n            val fileUrls = mutableSetOf<String>()\n            // download css and javascript assets\n            fileUrls.addAll(PageComponentsUrlParser.parse(mobileHTML,\n                pageTitle.wikiSite).filter { url -> url.isNotEmpty() })\n            if (Prefs.isImageDownloadEnabled) {\n                // download thumbnail and lead image\n                if (!summaryResponse.thumbnailUrl.isNullOrEmpty()) {\n                    page.thumbUrl = UriUtil.resolveProtocolRelativeUrl(pageTitle.wikiSite, summaryResponse.thumbnailUrl.orEmpty())\n                    val existingPageImage = AppDatabase.instance.pageImagesDao()\n                        .findItemsBy(pageTitle.wikiSite.languageCode, pageTitle.namespace, pageTitle.prefixedText)\n                        .firstOrNull()\n\n                    AppDatabase.instance.pageImagesDao().insertPageImage(PageImage(\n                        pageTitle.wikiSite.languageCode,\n                        pageTitle.namespace,\n                        page.apiTitle,\n                        page.thumbUrl.orEmpty(),\n                        summaryResponse.description,\n                        existingPageImage?.timeSpentSec ?: 0,\n                        summaryResponse.coordinates?.latitude ?: 0.0,\n                        summaryResponse.coordinates?.longitude ?: 0.0\n                    ))\n                    fileUrls.add(UriUtil.resolveProtocolRelativeUrl(\n                        ImageUrlUtil.getUrlForPreferredSize(page.thumbUrl.orEmpty(), Constants.PREFERRED_CARD_THUMBNAIL_SIZE)))\n                }\n\n                // download article images\n                for (item in mediaListResponse.getItems(\"image\")) {\n                    item.srcSets.let {\n                        fileUrls.add(item.getImageUrl(DimenUtil.densityScalar))\n                    }\n                }\n            }\n            page.displayTitle = summaryResponse.displayTitle.orEmpty()\n            page.description = summaryResponse.description.orEmpty()\n\n            reqSaveFiles(page, pageTitle, fileUrls)\n\n            val totalSize = AppDatabase.instance.offlineObjectDao().getTotalBytesForPageId(page.id)\n\n            L.i(\"Saved page \" + pageTitle.prefixedText + \" (\" + totalSize + \")\")\n\n            totalSize\n        }\n    }\n\n    private suspend fun reqMobileHTML(pageTitle: PageTitle): String {\n        val request = makeUrlRequest(pageTitle.wikiSite,\n                ServiceFactory.getRestBasePath(pageTitle.wikiSite) +\n                        RestService.PAGE_HTML_ENDPOINT + UriUtil.encodeURL(pageTitle.prefixedText),\n                pageTitle).build()\n        return withContext(Dispatchers.IO) {\n            OkHttpConnectionFactory.client.newCall(request).execute().use { it.body.string() }\n        }\n    }\n\n    @Throws(IOException::class, InterruptedException::class)\n    private suspend fun reqSaveFiles(page: ReadingListPage, pageTitle: PageTitle, urls: Set<String>) {\n        val numOfImages = urls.size\n        var percentage = MEDIA_LIST_PROGRESS.toFloat()\n        val updateRate = (CircularProgressBar.MAX_PROGRESS - percentage) / numOfImages\n\n        withContext(Dispatchers.IO) {\n            for (url in urls) {\n                if (savedPageSyncNotification.isSyncPaused() || savedPageSyncNotification.isSyncCanceled()) {\n                    throw InterruptedException(\"Sync paused or cancelled.\")\n                }\n                try {\n                    reqSaveUrl(pageTitle, page.wiki, url)\n                    percentage += updateRate\n                    page.downloadProgress = percentage.toInt()\n                    FlowEventBus.post(PageDownloadEvent(page))\n                } catch (e: CancellationException) {\n                    throw e\n                } catch (e: Exception) {\n                    if (isRetryable(e)) {\n                        throw e\n                    }\n                }\n            }\n            page.downloadProgress = CircularProgressBar.MAX_PROGRESS\n            FlowEventBus.post(PageDownloadEvent(page))\n        }\n    }\n\n    @Throws(IOException::class)\n    private suspend fun reqSaveUrl(pageTitle: PageTitle, wiki: WikiSite, url: String) {\n        val request = makeUrlRequest(wiki, url, pageTitle).build()\n        withContext(Dispatchers.IO) {\n            OkHttpConnectionFactory.client.newCall(request).execute().use { response ->\n                // Read the entirety of the response, so that it's written to cache by the interceptor.\n                response.body.source().readAll(object : Sink {\n                    override fun write(source: Buffer, byteCount: Long) {}\n                    override fun flush() {}\n                    override fun timeout(): Timeout {\n                        return Timeout()\n                    }\n\n                    override fun close() {}\n                })\n            }\n        }\n    }\n\n    private fun makeUrlRequest(wiki: WikiSite, url: String, pageTitle: PageTitle): Request.Builder {\n        return Request.Builder().cacheControl(OkHttpConnectionFactory.CACHE_CONTROL_FORCE_NETWORK).url(UriUtil.resolveProtocolRelativeUrl(wiki, url))\n                .addHeader(\"Accept-Language\", WikipediaApp.instance.getAcceptLanguage(pageTitle.wikiSite))\n                .addHeader(OfflineCacheInterceptor.SAVE_HEADER, OfflineCacheInterceptor.SAVE_HEADER_SAVE)\n                .addHeader(OfflineCacheInterceptor.LANG_HEADER, pageTitle.wikiSite.languageCode)\n                .addHeader(OfflineCacheInterceptor.TITLE_HEADER, UriUtil.encodeURL(pageTitle.prefixedText))\n    }\n\n    private fun isRetryable(t: Throwable): Boolean {\n        // \"Retryable\" in this case refers to exceptions that will be rethrown up to the\n        // outer exception handler, so that the entire page can be retried on the next pass\n        // of the sync service.\n\n        // Errors that do *not* qualify for retrying include:\n        // - IllegalArgumentException (thrown for any kind of malformed URL)\n        // - HTTP 404 status (for nonexistent media)\n        return !(t is IllegalArgumentException || ThrowableUtil.is404(t))\n    }\n\n    companion object {\n        private const val WORK_NAME = \"savePageSyncService\"\n        private const val ENQUEUE_DELAY = 2L\n        const val MEDIA_LIST_PROGRESS = 30\n\n        fun enqueue() {\n            if (ReadingListSyncAdapter.inProgress()) {\n                return\n            }\n            val constraints = Constraints.Builder()\n                .setRequiredNetworkType(NetworkType.CONNECTED)\n                .build()\n            val workRequest = OneTimeWorkRequestBuilder<SavedPageSyncService>()\n                .setInitialDelay(ENQUEUE_DELAY, TimeUnit.SECONDS)\n                .setConstraints(constraints)\n                .build()\n            WorkManager.getInstance(WikipediaApp.instance)\n                .enqueueUniqueWork(WORK_NAME, ExistingWorkPolicy.REPLACE, workRequest)\n        }\n\n        fun sendSyncEvent(showMessage: Boolean = false) {\n            // Note: this method posts from a background thread but subscribers expect events to be\n            // received on the main thread.\n            FlowEventBus.post(ReadingListSyncEvent(showMessage))\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/savedpages/SavedPageSyncService.kt","kind":"class","line":46,"members":{"ENQUEUE_DELAY":[315,315],"MEDIA_LIST_PROGRESS":[316,316],"WORK_NAME":[314,314],"context":[46,46],"doWork":[49,102],"enqueue":[318,331],"isRetryable":[302,311],"makeUrlRequest":[294,300],"params":[46,46],"reqMobileHTML":[236,244],"reqSaveFiles":[246,273],"reqSaveUrl":[275,292],"savePageFor":[166,234],"savePages":[104,164],"savedPageSyncNotification":[47,47],"sendSyncEvent":[333,337]},"supers":["CoroutineWorker(context, params)"]},"SearchActivity":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["search","h-classes","Logic \u00b7 class diagram"]],"code":"class SearchActivity : SingleFragmentActivity<SearchFragment>() {\n\n    private val onBackPressedCallback = object : OnBackPressedCallback(true) {\n        override fun handleOnBackPressed() {\n\n            instrument?.submitInteraction(\"click\", elementId = \"search_back\")\n\n            isEnabled = false\n            onBackPressedDispatcher.onBackPressed()\n        }\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        if (intent.hasExtra(EXTRA_SHOW_SNACKBAR_MESSAGE)) {\n            val messageResId = intent.getIntExtra(EXTRA_SHOW_SNACKBAR_MESSAGE, 0)\n            if (messageResId != 0) {\n                FeedbackUtil.showMessage(this, messageResId)\n                intent.removeExtra(EXTRA_SHOW_SNACKBAR_MESSAGE)\n            }\n        }\n        onBackPressedDispatcher.addCallback(this, onBackPressedCallback)\n\n        _instrument = TestKitchenAdapter.client.getInstrument(\"apps-search\")\n            .setDefaultActionSource(\"search\")\n            .startFunnel(\"search\")\n            .also { SemanticSearchAbTest().setExperimentIfEligible(it) }\n    }\n\n    public override fun createFragment(): SearchFragment {\n        var source = intent.getSerializableExtra(Constants.INTENT_EXTRA_INVOKE_SOURCE) as InvokeSource?\n        if (source == null) {\n            when {\n                Intent.ACTION_SEND == intent.action -> { source = InvokeSource.INTENT_SHARE }\n                Intent.ACTION_PROCESS_TEXT == intent.action -> { source = InvokeSource.INTENT_PROCESS_TEXT }\n                else -> {\n                    source = InvokeSource.INTENT_UNKNOWN\n                    L.logRemoteErrorIfProd(RuntimeException(\"Unknown intent when launching SearchActivity: \" + intent.action.orEmpty()))\n                }\n            }\n        }\n        return SearchFragment.newInstance(\n            source = source,\n            query = intent.getStringExtra(QUERY_EXTRA),\n            returnLink = intent.getBooleanExtra(EXTRA_RETURN_LINK, false),\n            title = intent.getStringExtra(EXTRA_TITLE)\n        )\n    }\n\n    companion object {\n        const val QUERY_EXTRA = \"query\"\n        const val EXTRA_TITLE = \"articleTitle\"\n        const val EXTRA_RETURN_LINK = \"returnLink\"\n        const val EXTRA_RETURN_LINK_TITLE = \"returnLinkTitle\"\n        const val RESULT_LINK_SUCCESS = 97\n        const val EXTRA_SHOW_SNACKBAR_MESSAGE = \"showSnackbarMessage\"\n\n        fun newIntent(context: Context, source: InvokeSource, query: String?, returnLink: Boolean = false, title: String? = null): Intent {\n            return Intent(context, SearchActivity::class.java)\n                    .putExtra(Constants.INTENT_EXTRA_INVOKE_SOURCE, source)\n                    .putExtra(QUERY_EXTRA, query)\n                    .putExtra(EXTRA_RETURN_LINK, returnLink)\n                    .putExtra(EXTRA_TITLE, title)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/search/SearchActivity.kt","kind":"class","line":16,"members":{"EXTRA_RETURN_LINK":[68,68],"EXTRA_RETURN_LINK_TITLE":[69,69],"EXTRA_SHOW_SNACKBAR_MESSAGE":[71,71],"EXTRA_TITLE":[67,67],"QUERY_EXTRA":[66,66],"RESULT_LINK_SUCCESS":[70,70],"createFragment":[45,63],"newIntent":[73,79],"onBackPressedCallback":[18,26],"onCreate":[28,43]},"shot":"shots/code/SearchActivity.jpg","supers":["SingleFragmentActivity<SearchFragment>()"]},"ServiceFactory":{"appearsIn":[["activity","h-classes","Logic \u00b7 class diagram"],["activity","h-sequence","Open the Activity tab, logged in \u00b7 sequence"],["home","h-classes","Logic \u00b7 class diagram"],["home","h-sequence","Load more of the Community feed \u00b7 sequence"],["index","h-services","Services \u00b7 what the screens share"],["places","h-classes","Logic \u00b7 class diagram"],["places","h-sequence","Pan the map and open a place \u00b7 sequence"],["search","h-classes","Logic \u00b7 class diagram"],["search","h-sequence","Type a query \u00b7 sequence"]],"code":"object ServiceFactory {\n\n    private const val SERVICE_CACHE_SIZE = 8\n\n    private val SERVICE_CACHE = lruCache<WikiSite, Service>(SERVICE_CACHE_SIZE, create = {\n        // This method is called in the get() method if a value does not already exist.\n        createRetrofit(it, getBasePath(it)).create<Service>()\n    })\n\n    private val REST_SERVICE_CACHE = lruCache<WikiSite, RestService>(SERVICE_CACHE_SIZE, create = {\n        createRetrofit(it, getRestBasePath(it)).create<RestService>()\n    })\n\n    private val CORE_REST_SERVICE_CACHE = lruCache<WikiSite, CoreRestService>(SERVICE_CACHE_SIZE, create = {\n        createRetrofit(it, it.url() + \"/\" + CoreRestService.CORE_REST_API_PREFIX).create<CoreRestService>()\n    })\n\n    private val ANALYTICS_REST_SERVICE_CACHE = lruCache<DestinationEventService, EventService>(SERVICE_CACHE_SIZE, create = {\n        val intakeBaseUriOverride = Prefs.eventPlatformIntakeUriOverride.orEmpty().ifEmpty { it.baseUri }\n        createRetrofit(null, intakeBaseUriOverride).create<EventService>()\n    })\n\n    fun get(wiki: WikiSite): Service {\n        return SERVICE_CACHE[wiki]!!\n    }\n\n    fun getRest(wiki: WikiSite): RestService {\n        return REST_SERVICE_CACHE[wiki]!!\n    }\n\n    fun getCoreRest(wiki: WikiSite): CoreRestService {\n        return CORE_REST_SERVICE_CACHE[wiki]!!\n    }\n\n    fun getAnalyticsRest(destinationEventService: DestinationEventService): EventService {\n        return ANALYTICS_REST_SERVICE_CACHE[destinationEventService]!!\n    }\n\n    operator fun <T> get(wiki: WikiSite, baseUrl: String?, service: Class<T>): T {\n        val r = createRetrofit(wiki, baseUrl.orEmpty().ifEmpty { wiki.url() + \"/\" })\n        return r.create(service)\n    }\n\n    fun getBasePath(wiki: WikiSite): String {\n        var path = wiki.url()\n        if (!path.endsWith(\"/\")) {\n            path += \"/\"\n        }\n        return path\n    }\n\n    fun getRestBasePath(wiki: WikiSite): String {\n        var path = if (Prefs.restbaseUriFormat.isEmpty()) wiki.url() + \"/\" + RestService.REST_API_PREFIX\n        else String.format(Prefs.restbaseUriFormat, \"https\", wiki.authority())\n        if (!path.endsWith(\"/\")) {\n            path += \"/\"\n        }\n        return path\n    }\n\n    fun createRetrofit(wiki: WikiSite?, baseUrl: String, readTimeoutSec: Long = OkHttpConnectionFactory.DEFAULT_READ_TIMEOUT_SEC): Retrofit {\n        val builder = OkHttpConnectionFactory.client.newBuilder()\n        builder.readTimeout(readTimeoutSec, TimeUnit.SECONDS)\n        builder.interceptors().add(builder.interceptors().indexOfFirst { it is HttpLoggingInterceptor }, LanguageVariantHeaderInterceptor(wiki))\n\n        return Retrofit.Builder()\n            .baseUrl(baseUrl)\n            .client(builder.build())\n            .addConverterFactory(MwExceptionConverterFactory())\n            .build()\n    }\n\n    private class LanguageVariantHeaderInterceptor(private val wiki: WikiSite?) : Interceptor {\n        @Throws(IOException::class)\n        override fun intercept(chain: Interceptor.Chain): Response {\n            var request = chain.request().newBuilder()\n                .header(\"Accept-Language\", WikipediaApp.instance.getAcceptLanguage(wiki))\n                .build()\n            return chain.proceed(request)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/dataclient/ServiceFactory.kt","kind":"object","line":18,"members":{"ANALYTICS_REST_SERVICE_CACHE":[35,38],"CORE_REST_SERVICE_CACHE":[31,33],"LanguageVariantHeaderInterceptor":[90,98],"REST_SERVICE_CACHE":[27,29],"SERVICE_CACHE":[22,25],"SERVICE_CACHE_SIZE":[20,20],"createRetrofit":[78,88],"get":[40,42],"getAnalyticsRest":[52,54],"getBasePath":[61,67],"getCoreRest":[48,50],"getRest":[44,46],"getRestBasePath":[69,76]},"supers":[]},"SettingsActivity":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["settings","h-classes","Logic \u00b7 class diagram"]],"code":"class SettingsActivity : BaseSettingsActivity<SettingsFragment>() {\n    private lateinit var initialLanguageList: String\n    private lateinit var initialFeedCardsEnabled: List<Boolean>\n    private lateinit var initialFeedCardsLangDisabled: Map<Int, List<String>>\n    private lateinit var initialFeedCardsOrder: List<Int>\n    private val app = WikipediaApp.instance\n\n    public override fun createFragment() = SettingsFragment.newInstance()\n    override val title = R.string.settings_activity_title\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        initialLanguageList = JsonUtil.encodeToString(app.languageState.appLanguageCodes).orEmpty()\n        initialFeedCardsEnabled = Prefs.feedCardsEnabled\n        initialFeedCardsLangDisabled = Prefs.feedCardsLangDisabled\n        initialFeedCardsOrder = Prefs.feedCardsOrder\n    }\n\n    public override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {\n        super.onActivityResult(requestCode, resultCode, data)\n        val finalLanguageList = JsonUtil.encodeToString(app.languageState.appLanguageCodes)\n        if (requestCode == Constants.ACTIVITY_REQUEST_ADD_A_LANGUAGE &&\n                finalLanguageList != initialLanguageList) {\n            setResult(ACTIVITY_RESULT_LANGUAGE_CHANGED)\n        } else if (requestCode == Constants.ACTIVITY_REQUEST_FEED_CONFIGURE &&\n                (Prefs.feedCardsEnabled != initialFeedCardsEnabled || Prefs.feedCardsOrder != initialFeedCardsOrder || Prefs.feedCardsOrder != initialFeedCardsLangDisabled)) {\n            setResult(ACTIVITY_RESULT_FEED_CONFIGURATION_CHANGED)\n        }\n    }\n\n    companion object {\n        const val ACTIVITY_RESULT_LANGUAGE_CHANGED = 1\n        const val ACTIVITY_RESULT_FEED_CONFIGURATION_CHANGED = 2\n        const val ACTIVITY_RESULT_LOG_OUT = 3\n\n        fun newIntent(ctx: Context) = Intent(ctx, SettingsActivity::class.java)\n    }\n}","file":"app/src/main/java/org/wikipedia/settings/SettingsActivity.kt","kind":"class","line":11,"members":{"ACTIVITY_RESULT_FEED_CONFIGURATION_CHANGED":[43,43],"ACTIVITY_RESULT_LANGUAGE_CHANGED":[42,42],"ACTIVITY_RESULT_LOG_OUT":[44,44],"app":[16,16],"createFragment":[18,18],"initialFeedCardsEnabled":[13,13],"initialFeedCardsLangDisabled":[14,14],"initialFeedCardsOrder":[15,15],"initialLanguageList":[12,12],"newIntent":[46,46],"onActivityResult":[29,39],"onCreate":[21,27],"title":[19,19]},"shot":"shots/code/SettingsActivity.jpg","supers":["BaseSettingsActivity<SettingsFragment>()"]},"WikipediaApp":{"appearsIn":[["index","h-services","Services \u00b7 what the screens share"]],"code":"class WikipediaApp : Application() {\n    init {\n        instance = this\n    }\n\n    val mainThreadHandler by lazy { Handler(mainLooper) }\n    val languageState by lazy { AppLanguageState(this) }\n    val appSessionEvent by lazy { AppSessionEvent() }\n\n    val userAgent by lazy {\n        var channel = ReleaseUtil.getChannel(this)\n        channel = if (channel.isBlank()) \"\" else \" $channel\"\n        String.format(\"WikipediaApp/%s (Android %s; %s; %s Build/%s)%s\",\n            BuildConfig.VERSION_NAME,\n            Build.VERSION.RELEASE,\n            getString(R.string.device_type),\n            Build.MODEL,\n            Build.ID,\n            channel\n        )\n    }\n\n    private val activityLifecycleHandler = ActivityLifecycleHandler()\n    private var defaultWikiSite: WikiSite? = null\n\n    val connectionStateMonitor = ConnectionStateMonitor()\n    val tabList by lazy { mutableListOf<Tab>().also { initTabs(it) } }\n\n    var currentTheme = Theme.fallback\n        set(value) {\n            if (value !== field) {\n                field = value\n                Prefs.currentThemeId = currentTheme.marshallingId\n                FlowEventBus.post(ThemeFontChangeEvent())\n            }\n        }\n\n    val appOrSystemLanguageCode: String\n        get() = languageState.appLanguageCode\n\n    val versionCode: Int\n        get() {\n            // When we had ABI-specific version codes, they were structured in increments of 10000,\n            // so just take the actual version code modulo the increment.\n            return BuildConfig.VERSION_CODE % 10000\n        }\n\n    val appInstallID: String\n        get() {\n            var id = Prefs.appInstallId\n            if (id == null) {\n                id = UUID.randomUUID().toString()\n                Prefs.appInstallId = id\n            }\n            return id\n        }\n\n    /**\n     * Default \"home\" wiki for the app\n     * Use PageTitle.getWikiSite() to get the article wiki\n     */\n    @get:Synchronized\n    val wikiSite: WikiSite\n        get() {\n            // TODO: why don't we ensure that the app language hasn't changed here instead of the client?\n            if (defaultWikiSite == null) {\n                val lang = if (Prefs.mediaWikiBaseUriSupportsLangCode) appOrSystemLanguageCode else \"\"\n                defaultWikiSite = WikiSite.forLanguageCode(lang)\n            }\n            return defaultWikiSite!!\n        }\n\n    // handle the case where we have a single tab with an empty backstack, which shouldn't count as a valid tab:\n    val tabCount\n        get() = if (tabList.size > 1) tabList.size else if (tabList.isEmpty()) 0 else if (tabList[0].backStack.isEmpty()) 0 else tabList.size\n\n    val isOnline\n        get() = connectionStateMonitor.isOnline()\n\n    val haveMainActivity\n        get() = activityLifecycleHandler.haveMainActivity()\n\n    val currentResumedActivity\n        get() = activityLifecycleHandler.getResumedActivity()\n\n    val voiceRecognitionAvailable by lazy {\n        try {\n            val intent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH)\n            packageManager.queryIntentActivities(intent, PackageManager.MATCH_DEFAULT_ONLY).isNotEmpty()\n        } catch (e: Exception) {\n            L.e(e)\n            false\n        }\n    }\n\n    override fun onCreate() {\n        super.onCreate()\n\n        // The system WebView's sandboxed renderer can get bound to the app and run onCreate()\n        // in an isolated process, where UserManager (and thus SharedPreferences) is not available.\n        // In such a case, there's no point continuing initialization.\n        if ((Build.VERSION.SDK_INT >= Build.VERSION_CODES.P && Process.isIsolated()) ||\n            getSystemService(UserManager::class.java) == null) {\n            return\n        }\n\n        WikiSite.setDefaultBaseUrl(Prefs.mediaWikiBaseUrl)\n\n        connectionStateMonitor.enable()\n\n        setupLeakCanary()\n\n        // See Javadocs and http://developer.android.com/tools/support-library/index.html#rev23-4-0\n        AppCompatDelegate.setCompatVectorFromResourcesEnabled(true)\n\n        currentTheme = unmarshalTheme(Prefs.currentThemeId)\n\n        enableWebViewDebugging()\n        registerActivityLifecycleCallbacks(activityLifecycleHandler)\n        registerComponentCallbacks(activityLifecycleHandler)\n        NotificationCategory.createNotificationChannels(this)\n        AppShortcuts.setShortcuts(this)\n\n        // Kick the notification receiver, in case it hasn't yet been started by the system.\n        NotificationPollBroadcastReceiver.startPollTask(this)\n        InstallReferrerListener.newInstance(this)\n\n        // For good measure, explicitly call our token subscription function, in case the\n        // API failed in previous attempts.\n        WikipediaFirebaseMessagingService.updateSubscription()\n\n        EventPlatformClient.setUpStreamConfigs()\n\n        ImageService.setImplementation(CoilImageServiceLoader())\n    }\n\n    /**\n     * @return the value that should go in the Accept-Language header.\n     */\n    fun getAcceptLanguage(wiki: WikiSite?): String {\n        val wikiLang = if (wiki == null || \"meta\" == wiki.languageCode) \"\" else wiki.languageCode\n        return AcceptLanguageUtil.getAcceptLanguage(\n            wikiLang,\n            languageState.appLanguageCode,\n            languageState.systemLanguageCode)\n    }\n\n    fun constrainFontSizeMultiplier(mult: Int): Int {\n        return mult.coerceIn(resources.getInteger(R.integer.minTextSizeMultiplier),\n                resources.getInteger(R.integer.maxTextSizeMultiplier))\n    }\n\n    fun setFontSizeMultiplier(mult: Int): Boolean {\n        val multiplier = constrainFontSizeMultiplier(mult)\n        if (multiplier != Prefs.textSizeMultiplier) {\n            Prefs.textSizeMultiplier = multiplier\n            FlowEventBus.post(ChangeTextSizeEvent())\n            return true\n        }\n        return false\n    }\n\n    fun setFontFamily(fontFamily: String) {\n        if (fontFamily != Prefs.fontFamily) {\n            Prefs.fontFamily = fontFamily\n            FlowEventBus.post(ThemeFontChangeEvent())\n        }\n    }\n\n    fun logError(throwable: Throwable) {\n        L.e(throwable)\n        ClientErrorEvent().logError(throwable)\n    }\n\n    fun commitTabState() {\n        if (tabList.isEmpty()) {\n            Prefs.clearTabs()\n            initTabs(tabList)\n        } else {\n            Prefs.tabs = tabList\n        }\n    }\n\n    /**\n     * Gets the current size of the app's font. This is given as a device-specific size (not \"sp\"),\n     * and can be passed directly to setTextSize() functions.\n     * @return Actual current size of the font.\n     */\n    fun getFontSize(editing: Boolean = false): Float {\n        return DimenUtil.getFontSizeFromSp(resources.getDimension(R.dimen.textSize)) *\n                (1.0f + (if (editing) Prefs.editingTextSizeMultiplier else Prefs.textSizeMultiplier) *\n                DimenUtil.getFloat(R.dimen.textSizeMultiplierFactor))\n    }\n\n    @Synchronized\n    fun resetWikiSite() {\n        defaultWikiSite = null\n    }\n\n    fun logOut() {\n        MainScope().launch(CoroutineExceptionHandler { _, t ->\n            L.e(t)\n        }) {\n            L.d(\"Logging out\")\n            ServiceFactory.get(wikiSite).getToken().query?.csrfToken()?.let { token ->\n                WikipediaFirebaseMessagingService.unsubscribePushToken(token, Prefs.pushNotificationToken)\n                ServiceFactory.get(wikiSite).postLogout(token)\n            }\n        }.invokeOnCompletion {\n            resetAfterLogOut()\n        }\n    }\n\n    fun resetAfterLogOut() {\n        AccountUtil.removeAccount()\n        Prefs.isPushNotificationTokenSubscribed = false\n        Prefs.pushNotificationTokenOld = \"\"\n        Prefs.lastBackgroundLoginDateTime = \"\"\n        Prefs.tempAccountWelcomeShown = false\n        Prefs.tempAccountCreateDay = 0L\n        Prefs.tempAccountDialogShown = false\n        Prefs.impactLastQueryTime = 0\n        Prefs.impactLastResponseBody = emptyMap()\n        PrefsYearInReviewStore.onLoggedOut()\n        SharedPreferenceCookieManager.instance.clearAllCookies()\n        MainScope().launch {\n            AppDatabase.instance.notificationDao().deleteAll()\n        }\n        FlowEventBus.post(LoggedOutEvent())\n        L.d(\"Logout complete.\")\n    }\n\n    private fun enableWebViewDebugging() {\n        if (BuildConfig.DEBUG) {\n            WebView.setWebContentsDebuggingEnabled(true)\n        }\n    }\n\n    fun unmarshalTheme(themeId: Int): Theme {\n        var result = Theme.ofMarshallingId(themeId)\n        if (result == null) {\n            L.d(\"Theme id=$themeId is invalid, using fallback.\")\n            result = Theme.fallback\n        }\n        return result\n    }\n\n    private fun initTabs(tabs: MutableList<Tab>) {\n        if (Prefs.hasTabs) {\n            tabs.addAll(Prefs.tabs)\n        }\n        if (tabs.isEmpty()) {\n            tabs.add(Tab())\n        }\n    }\n\n    companion object {\n        lateinit var instance: WikipediaApp\n            private set\n    }\n}","file":"app/src/main/java/org/wikipedia/WikipediaApp.kt","kind":"class","line":47,"members":{"activityLifecycleHandler":[69,69],"appInstallID":[94,94],"appOrSystemLanguageCode":[84,84],"appSessionEvent":[54,54],"commitTabState":[221,228],"connectionStateMonitor":[72,72],"constrainFontSizeMultiplier":[194,197],"currentResumedActivity":[129,129],"currentTheme":[75,75],"defaultWikiSite":[70,70],"enableWebViewDebugging":[279,283],"getAcceptLanguage":[183,192],"getFontSize":[230,239],"haveMainActivity":[126,126],"initTabs":[294,301],"instance":[304,304],"isOnline":[123,123],"languageState":[53,53],"logError":[216,219],"logOut":[246,258],"mainThreadHandler":[52,52],"onCreate":[142,181],"resetAfterLogOut":[260,277],"resetWikiSite":[241,244],"setFontFamily":[209,214],"setFontSizeMultiplier":[199,207],"tabCount":[119,120],"tabList":[73,73],"unmarshalTheme":[285,292],"userAgent":[56,67],"versionCode":[87,87],"voiceRecognitionAvailable":[132,140],"wikiSite":[104,109]},"supers":["Application()"]}},"sourceUrl":"https://github.com/wikimedia/apps-android-wikipedia/blob/a94b2dd658c6a6bdc7f131c5bf5fa97ba9ae6bfd/"};
